/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20160307-3","meetingId":"h28-c-budget","date":"2016年3月7日","dateIso":"2016-03-07","committee":"予算特別委員会","time":"午前１０時００分～午後６時０６分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を196件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"おはようあります。私からは、２３３ページの心身障害者福祉会館運営費の中の高次脳機能障害相談、２４５ページ、ＡＥＤ設置費助成についてお伺いいたします。２３３ページ、高次脳機能障害相談についてお聞きいたします。そこで、質問いたします。高次脳機能障害者窓口が会館内にあると思いますが、その相談実績、区で把握している高次脳機能障害者の人数を教えてください。","respondent":"中山障害者福祉課長","answer":"平成２５年度は２３８件、平成２６年度が６５８件ということで、これは会館の相談だけではないのですけれども、高次脳機能障害の相談窓口の周知をこの間してまいりましたことに伴いまして、徐々に増えてきているところです。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問","question":"先ほども高次脳機能障害者が外見では障害があることがわかりにくい、誤解を受けやすい、見えない障害と言われていますけれども、中には、区内の在住者でも高次脳機能障害なのだけれどもまだわからないという、予備軍というか、その患者さんがいらっしゃると思うのですけれども、区としてはその辺のことはどういうふうに捉えているのか、教えてください。","respondent":"中山障害者福祉課長","answer":"ご自身が高次脳機能障害であるということの認識が少ない、あるいは医療機関でもなかなかどこに相談を持っていったらいいかわからないという予備軍の方がいらっしゃるかと思います。昨年度、品川区では、高次脳機能障害のパンフレットを作成いたしました。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問","question":"どうもありがとうあります。わかりました。それと、会館内に高次脳機能障害者のために部屋を開放しているとお聞きいたしましたけれども、具体的に訓練、支援等で活用しているのでしょうか。愛知県では高次脳機能障害支援課がありますけれども、今後、区として高次脳機能障害者のご本人、ご家族に向けて情報発信、サービスを行っていくのでしょうか、教えてください。","respondent":"中山障害者福祉課長","answer":"会館の中には一般開放をしております貸し施設もあります。そういったところをご利用になられて、高次脳機能障害の家族会の会議であるとか、事業であるとか、そういったことも実施されているところです。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問","question":"続きまして、２４５ページ、ＡＥＤ設置費助成についてお伺いいたします。認可保育園、そして私立保育園等々でＡＥＤの設置が今進んでいるところであると思うのですけれども、どの程度完了しているのでしょうか、教えてください。そして、ＡＥＤはメーカーによっていろいろ形態が違うと思うのですけれども、その辺も含めて教えていただければと思います。よろしくお願いします。","respondent":"竹田保育課長","answer":"私立認可保育園におきましては、３２園中２７園で設置が済んでおりまして、残りの園につきましては平成２８年度に全て設置できるように事業者と交渉を進めております。それから、認証保育所につきましては、現在２２園のうち１５園で設置が既に完了しております。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"私からは、２２９ページ、障害者作品展６４万７,０００円、芸術活動支援事業４２０万円が計上されております。このことを確認します。これは、昨年、しながわ水族館でアール・ブリュット展が開催され、平成２８年度は天王洲地域でということで予定されている事業であるかと思いますが、この事業の内容を少し教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"来年度につきましては、今のところ予定として天王洲アイルの周辺ということで、地域に広げた形で実施しようと考えているところです。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"この障害者福祉の予算の中に芸術支援のための予算をつけた意義と、また今後の品川区の方向性をお聞かせいただきたいと思います。","respondent":"中山障害者福祉課長","answer":"障害のある方が守られる存在だけではなく、力を発揮する場というところの観点からも非常に推進していきたいと考えているところです。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"続けて、質問いたします。昨年１１月に公職選挙法改正と知的障害者への投票支援等の講演会が東京都知的障害者育成会主催で、狛江市で行われました。この４月から障害者差別解消法が全面的に施行されるこのときに、品川区としてもさまざまご対応いただいておりますが、今こそ知的障害者のための選挙支援として、障害者のための模擬投票をぜひ行っていただきたいと思いますが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"障害者福祉課のほうからも、ぜひ、こういう今、障害のある方のために投票所でもさまざまな工夫をされているということをお伝えすると同時に、育成会のほうでも模擬投票みたいなものの実施についての希望というのは聞いてありますので。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"できましたら選挙管理委員会からもお答えをいただきたいのですが、いかがでしょうか。","respondent":"工藤選挙管理委員会事務局長","answer":"模擬投票の件ですけれども、まずは、障害者団体の方からお話がございましたら、一度、障害者福祉部門と私どものほうで、どのような形で模擬投票、体験投票的なものをするのかという部分をまず協議させていただきまして、今後、検討してまいりたいと思っているところです。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひ、福祉部門、そして選挙管理委員会と連携をとって、また当事者ともしっかりと連携をとっていただきながら、早い模擬投票の開催を要望します。少し時間がありますので、２２７ページの地域生活の支援、その中の日中一時支援事業の予算の確認をします。そして、前年度、平成２６年度を見てみますと、どうも平成２６年度の予算に戻ったような予算になっていることがわかりました。","respondent":"中山障害者福祉課長","answer":"日中一時支援事業ということでよろしいでしょうか。日中一時支援事業は「にじのひろば」の事業になりますが、これ自体は予算はさほど変わっていないです。ちなみに、平成２７年度が３,０４８万円、今年度が３,０５８万５,０００円という数字かと思います。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"これは増やすため、しっかりと支援の拡大をしていただきたいと思います。予算をつけたから増えるということではないと思うのですけれども、何か課題があるのかなと思いますので、ぜひともしっかりとこれからよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私からは、２２１ページ、平塚シルバーセンター跡高齢者福祉施設整備と、２４３ページ、待機児童解消対策費、２４９ページ、ひろまち保育園についてお伺いいたします。代替えがなくなってしまう。進め方も、内容も、納得がいっていないと地域の方はおっしゃっておられますが、説明会をぜひ開いていただきたい、やり直していただきたいと求めますが、いかがでしょうか。","respondent":"松山高齢者地域支援課長","answer":"平塚シルバーセンターの跡地利用についての説明会ですけれども、ご利用者の方、もちろん代表者の方だけではなくて利用者の方への周知ということで、平成２４年度以降からこれまでに８回説明会を催しまして、丁寧に説明しています。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"８回やられたということですが、ここはとても利用者が多いといったところにおいては、そこから漏れていらっしゃる方もたくさんいらっしゃる。書面で要望したらば、ほかの施設を利用してください。ぜひ説明会をやり直していただきたい。シルバーセンターは活用されている地域の皆さんの財産であるということをしっかり受けとめて、ぜひこの要望を聞いていただきたいと思いますが、もう一回、いかがでしょうか。","respondent":"松山高齢者地域支援課長","answer":"平塚シルバーセンターの方々につきましては、今後も説明会は予定しています。さまざまなご意見がございましたら、必ずこちらの当課のほうにお寄せいただきまして、個別に丁寧に対応していく所存です。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これからの工事説明会ではなく、意見をしっかりと聞くこと、あと改善のための説明会をぜひやっていただきたいと、これは要望いたしておきます。２月中旬、ブログに「保育園落ちた。同じ境遇の人が何千人、何万人もいるということをわかってほしいのだという声が多数届いていますけれども、区はこの事態をどう受けとめるのか、１点。入れない子があふれるのも当然だと思いますが、この点いかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"今後も、待機児童、今現在、一次ということで今発表しているところですけれども、二次の入園可能数は少ないところでございましたけれども、例年内定の辞退等がありますので、その方も含めて速やかにマッチングしていく、今後も。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一次のゼロ歳から２歳、先ほど２.７６倍と計算してなりました。３人に２人が入れない、ゼロ歳児、１歳児、２歳児。今まで頑張って枠を広げてきましたといっても、３人に２人が入れない。その次を求めたいと思います。支援強化を求める、国に対して強化を求めるとともに、品川区自身も直ちに緊急対策を行っていかなければいけない。大至急緊急の対策をとるべきであると思いますが、いかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"東京都のほうから詳しい説明はまだですけれども、安心こども基金の解消に伴いまして、さまざまな助成金についても東京都が待機児童解消の市区町村助成事業で追加するなど、さまざまな対策を国、都ともにとっております。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"直ちに緊急対策を行うことを国にも求めていくこと。この点は本当に強く、強く要望いたしますとともに、受けとめていただきたい。ぜひ受けとめていただきたいと思います。夢工房について、人件費比率、離職率、経験年数、平均年収を伺います。職員の処遇を法人任せにするのではなく、チェックをする仕組みがあるのかないのか、しっかりチェックをすべきであると思いますが、いかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"２５１ページ、区立保育園運営業務委託費の中に、こちらに委託の経費が大体、委託経費として３億円程度、それから、いわゆる私立保育園の特別支援ですとか、アレルギーをお持ちのお子さんの実績ベースの支払いの部分もありますので。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう一点、３００人大規模の安全確保について伺います。国基準に上乗せがどうなっているのか、３００人規模なので３園分であると思っています。１歳児が４８名、２歳児５４名、３歳児、４歳児、５歳児がそれぞれ６６名、大規模ですので、ぜひ小グループで保育ができるような対策をとっていただきたいので、この点について。隣の駐車場をぜひ園庭に確保していただきたい、強く求めます。いかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"今回オール電化で、全てこちらの施設はやっておりますので、避難ということではまずは現場で発災がなければ待機と考えております。","id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"遠隔地から人材を確保した場合に、入職者が負担した施設見学や面接にかかる交通費、引越し代等を採用法人に対して助成するとありますけれども、この「等」というのはどこまで助成されるのか、伺いたいと思います。区内の特別養護老人ホーム、老人保健施設の運営法人が獲得に要した経費には、求人広告等も含まれておりますけれども、１法人当たり最大どれぐらいの助成を検討されているのか伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"一律支度金として１０万円で、上限が２０万円となっております。法人に対して、獲得した経費として５万円を上限に助成することになっておりますけれども、こちらにつきましても、人材確保をするにあたっての交通費だとか、求人広告等を予定しているものです。","id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"現在の採用状況について伺いたいと思いますけれども、採用状況というのは、品川区では現在、特別養護老人ホーム９カ所、老人保健施設などを合わせますと１５カ所あります。","respondent":"永尾高齢者福祉課長","answer":"こちらにつきましては全員、修学資金貸付金を利用されております。修学資金貸付金を利用していない卒業予定者の方はお二人いまして、１名が特定施設、１名が三徳会に就職が内定しています。","id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"こうした現状を踏まえて、介護のほうにも力を入れていただければと思います。今後の課題と対策について伺いたいと思います。近年、高齢者の人口も増えてきております。そのことについて、品川区は介護施設について今後どのような対策をとっていかれるのか、目標について伺いたいと思います。介護人材の不足を招いている原因について、区のご見解をお伺いしたいと思います。","respondent":"大串福祉計画課長、永尾高齢者福祉課長","answer":"こういった形での施設整備だけではなく、私ども高齢者福祉に携わる者としてはソフトの支援、こういったものも大切と考えておりまして、そういったもの２つを両輪として今後の福祉施策を進めてまいりたいと考えております。今後の福祉人材のことですけれども、これから高齢者の方々がどんどん増えるということで、福祉人材をどんどん確保していかなければいけないと考えておりますが、介護福祉専門学校が幸い品川区の場合。","id":"exchange-019"},{"speaker":"松永委員","kind":"提案","question":"職場環境での充実というのもとても大事だと、私も思っております。その中でやはり給料の面での不安があるのではないかと私は考えます。そこで提案ですけれども、一律給料を増やすということはなかなか難しいことだと思いますので、区営住宅や空き家等を活用しながら家賃を少し助成するなどして、経済的支援ということがとても大事だと思いますけれども、その辺について区のご見解をお伺いしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"今回、新規事業といたしまして、遠隔地から転入されて介護の職についた方についての住居確保支援というのも行っております。こういう新しい事業を進める中で、処遇改善についても検討していきたいと考えております。","id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"ぜひ先を見据えた対策をとっていただければと思います。次に、関連して介護ロボットの試験導入について伺います。介護ロボットは主にどういったものなのか伺いたいと思います。その試験導入される施設についてですが、一斉に行われるのか、また試験導入される施設はどのようにして決められる予定であるのか、伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"ロボットスーツ型で簡単に装着できるものを今、想定していますので、それについて社会福祉法人のほうで手を挙げていただいて、導入を目指していきたいと考えております。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"試験導入された後、結果がよければどんどん広がっていくと思いますが、もし介護ロボットが導入された場合に施設に対してどのくらい助成されるのか、どのように考えているのか、伺いたいと思います。もし、まだ決まっていなければ、今後介護ロボットをどのような形で進めていくのか、目標について伺います。","respondent":"永尾高齢者福祉課長","answer":"レンタル料として一月８万４,２４０円を想定しています。このロボットの業界につきましては今技術がどんどん進んでおりますので、そういうところも見ながらこの製品の品目等を考えていきたいと考えております。","id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"２２３ページの高齢者外出習慣化事業について伺います。昨年は４２９万１,０００円で、本年度が５８７万６,０００円となっておりますが、まず昨年度の実績について、およそでいいので参加人数、そして参加者の男女の割合、開催場所について伺いたいと思います。本年度では約１５０万円増加となっておりますが、どういったことが変わったのか、伺いたいと思います。","respondent":"松山高齢者地域支援課長","answer":"高齢者外出習慣化事業の昨年度の実績です。昨年度につきましては、南品川シルバーセンター、東品川シルバーセンター、それから大井林町の高齢者施設の憩いの場、それから身近なお店、区の商店街連合会にご協力いただきまして、その１店ということで、４カ所で実施しております。","id":"exchange-023"},{"speaker":"松永委員","kind":"質問","question":"引きこもりがちな高齢者の方、こうした取組みによって少しずつ減ってきていると思います。男性が２割というのは残念なのですけれども。そこで、改めて、そうした方への周知方法ですけれども、昨年と同じようなやり方で皆さんにお伝えされているのか。応募数に関してですけれども、行きたくても外れてしまったよとか、そういったことはあったのか、伺いたいと思います。","respondent":"松山高齢者地域支援課長","answer":"周知方法についてのお尋ねです。昨年までは民生委員協議会での説明、あるいは広報で周知するとともに、シルバーセンター、地域センターなどにチラシを置き、周知を図ってまいりました。","id":"exchange-024"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ、今後、参加できなかった方に対しても対策をとっていただければと思います。最後に、２２１ページの認知症高齢者の支援とケアの充実について伺います。徘徊高齢者早期発見アイテムの見守りツールですけれども、交付のために事前登録が必要とありますが、少しわかりづらかったので、その登録方法について流れを教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"アイロンシール等につきましては登録の番号をふっておきますので、もしわからなくなったときにその番号を問い合わせていただければどの方かということが把握できますので、それによって徘徊された方を保護することができるというような流れになっております。","id":"exchange-025"},{"speaker":"松永委員","kind":"提案","question":"最後に、提案ですけれども、若年層の方、要するに若くて認知症になられる方も多いので、若年層の方に対しての対策もよろしくお願いします。入っていれば、いいのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"２１５ページ、やさしいまちづくり推進費、社会福祉協議会運営助成、それと、２３９ページ、児童相談事業、それと、２４３ページの区内私立保育園経費の運営費、それと２１７ページの児童発達支援事業運営助成、同ページの福祉人材確保・定着事業についてお伺いします。初めにやさしいまちづくりですけれども、ホームドアについてお伺いします。ＪＲでも、京浜急行でも、東急でも、活発化してきました。","respondent":"中村都市計画課長","answer":"それ以降ですけれども、現在まだ具体的には決定はしておりませんけれども、平成２７年１月、昨年１月におきましては東急電鉄が、東横線、田園都市線、それから大井町線、全駅６４駅にホームドアを設置の予定ですので、今後、品川区内におきまして平成３２年までに下神明駅。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問・要望","question":"駅をおりて商店街がという形になっておりますので、ぜひこれを推進していっていただきたいと思います。次に、社会福祉協議会への助成ですが、決算特別委員会のときからお伺いしていますけれども、今回は本部助成についてお伺いしたいと思います。役割は大きいし、私は否定するものではないのですけれども、この運営助成の本部向けの中身についてお伺いします。","respondent":"永尾高齢者福祉課長","answer":"本部の助成の中身といたしましては、人件費の部分、あと紙おむつの支給事業、あと訪問理美容事業、あと本部の事務室の維持管理費、会計システム等のシステムの更新等の一部について助成しているものです。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"児童の発達支援ですけれども、最近子どもの総数も増えていますが、発達障害の子どもも増えていると伺っているのですけれども、この数年の数が増えているというデータはありますか。結果として、ニートと呼ぶ人が増えれば、社会的な損失にもなると思うのですが、今後の取組みについてお伺いします。","respondent":"中山障害者福祉課長","answer":"児童発達支援の中の発達障害児への対応というところだと思います。発達障害の方だけを取り分けているわけではないのですが、児童発達支援センターのほうで、発達に遅れがある、あるいは心配だといった相談を受け付けております。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"よくわかりました。次に、児童相談所についてお伺いしますけれども、最近の虐待の状況、あと件数などを教えてください。それと、先週、報道にもありましたが、児童相談所全国共通ダイヤルの「１８９」の電話の案内が長くて不評ということなのですけれども、区としてはどう考えているか、お伺いします。いつもこの件でお伺いするのですけれども、児童相談所の移管について新しい動きがあったら教えてください。","respondent":"伊崎子ども育成課長","answer":"最近の児童相談所移管の動きですが、都区の検討につきましては今年度の６月に特別区の児童相談所移管モデルについての具体案を都にお示しをいたしましたが、交渉のほうは膠着状態、平行線です。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"移管、早く決着することを心より祈念しております。それで、次へいきますが、私立保育園運営費ですが、平成２７年度から新制度がスタートしました。従前の制度と比べて区としての持ち出しは増えたのか、減ったのか。そして、従来は保育園費や運営費が、たしか７４.２％が区の負担だったと入園案内にも書いてありましたが、いかがでしょうか。","respondent":"竹田保育課長","answer":"全体の運営費がベースアップしております。しかし、負担割合は、国が２分の１、都が４分の１という負担割合は変わっておりませんので、区の支出は増えると考えております。例年７５％前後で推移しておりますが、若干変わることも考えられます。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"品川区は先見性があって介護福祉専門学校を設立していますが、保育士の確保と同じように家賃補助も新年度から始まるということはわかっているのですけれども、例えば今回開設の西中延ではどうなのか、既存のところではどうなのか。品川区では今後、上大崎が開設しますし、今後の見通しについてお伺いします。","respondent":"永尾高齢者福祉課長","answer":"それを受けまして、今回、緊急の人材確保の対策を新しく設置したものです。ただ、品川区の法人の離職率というのは、一般の日本全国でいきますとかなり低い状況になっておりますので、それについては今までと同様、きちんと意見を聞きながらやっていきたいと考えています。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"一番私が今思っている問題は、２０２５年問題なのです。団塊の世代の方が後期高齢者に入ってくる。全員介護というわけではないです。介護予防もやっていますし。そして、２０００年でしたか、介護保険制度が導入されて。介護がビジネスになった。はお金をもうけないとやっていけないわけですから。ですから、そろそろ直接介護士さんにという思いがあるのですけれども、その辺についてはいかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"その中に、全員にそういう手当を出すにしては、介護保険の仕組みを逸脱してしまうこともありますので、法人には助成しますけれども、きちんと法人から報告をいただいて、その管理をやっていきたいと考えています。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"区とこういう話をすると、区は直接介護士さんと話すよりも法人と話すほうが好きというか、やるではないですか。やはり大変なのです、現場でやっている方というのは。本当に大変。それで給料の差もある、人間関係もある。ですから、このせっかく品川区は先見性があるのだから、一歩踏み込んでもらいたいのです、そこを。で、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"区としては、福祉カレッジだとか、ケース会議等で現場の職員と接触する機会が非常に多くなっておりますので、その中での意見交換をきちんとやっていきたいと考えています。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問","question":"私からは、２１５ページ、訪問理美容について、２２７ページ、難病・高次脳機能障害者について、２３９ページの児童虐待防止対策強化啓発についてをお伺いいたします。訪問理美容についてお伺いいたします。","respondent":"永尾高齢者福祉課長","answer":"理美容をやっていただける方につきましても、高齢者の対応ということでいろいろ気を使っていただいていると聞いているところです。","id":"exchange-035"},{"speaker":"横山委員","kind":"質問","question":"現在の訪問理美容の対象者は高齢者というところなのでしょうか、どういった形で今、品川区としては捉えていらっしゃるのか教えてください。この規制緩和がもし実施された場合、品川区において何か変更点等生じる可能性はありますでしょうか。お願いいたします。","respondent":"永尾高齢者福祉課長","answer":"国の規制緩和の件ですけれども、現在、協定を結びながら、東京都理美容生活衛生同業組合と協定を結んでやっているところですので、そんなに大きな変化はないのではないかなと考えております。","id":"exchange-036"},{"speaker":"横山委員","kind":"質問","question":"実施団体、訪問理美容の実際に、高齢者の方、在宅の寝たきりの要介護度３から５の方のところに実際に行っていただいている方というのは、どういった方なのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"理容については、品川支部、荏原支部合わせて６６店、美容の部分については品川、大井、荏原合わせて５４店でやっていただいているところです。","id":"exchange-037"},{"speaker":"横山委員","kind":"質問","question":"難病・高次脳機能障害者についてお伺いいたします。相談のほうが６５８件で、手帳をお持ちの方は相談者の方、その中に含まれている方、そうでない方もいらっしゃるかと思うのですけれども、品川区以外の他区の高次脳機能障害者の方の人数の状況ですとか、またはほかの障害者の方と比較して、推測と現在区が把握されている数、そのあたりについて区としてはどういうふうに見ていらっしゃるのでしょうか。","respondent":"中山障害者福祉課長","answer":"それ以外の方も多分手帳を持たずに数多くいらっしゃいますし、実は高齢者の介護保険のサービスをお使いになっている方の中にも高次脳機能障害の方というのはたくさんいらっしゃいます。個別の具体的な数字というのは、区のほうでは把握しているものではございません。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"現在、医療機関等にパンフレットを置いたりなど、ＰＲをしていただいているかと思うのですけれども、さらなる強化を要望させていただきたいと思います。大田区との医療機関でのＰＲの連携、また３区合同の講演会なども行っているかと思います。こちらですけれども、ＰＲ、そして講演会以外に連携の事業としてどういったものを今後行っていくのでしょうか。お願いいたします。","respondent":"中山障害者福祉課長","answer":"３区合同の講演会も、家族会を中心に今こうした活動を進めていらっしゃるところです。家族会の中では、今後、高次脳機能障害者のサポーター養成事業みたいなものもつくっていきながら、理解を広げていくような輪をつくっていきたいと考えているところです。","id":"exchange-039"},{"speaker":"横山委員","kind":"確認","question":"サポーター養成講座というところ、移動支援を担うボランティアの方の人材育成ということなのかなと勘違いしていたのですけれども、こうした理解を広げていくための場として、そしてそういった機会として、来年度、行っていくということでよろしいのでしょうか。確認させていただけたらと思います。","respondent":"中山障害者福祉課長","answer":"それで、高次脳機能障害サポーターのほうですけれども、それについては家族会のほうが中心となってボランティアの養成、高次脳機能障害を理解してもらう中でボランティアを育てていったり、あるいは支援者の育成ということで今、会の活動として進めているところです。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問","question":"児童虐待防止対策強化啓発についてお伺いいたします。先ほど、ほかの委員からも話がありましたけれども、品川区の移管の現状について、昨年の決算特別委員会で濱野区長のご答弁の中であり方検討会の再開というキーワードをいただきました。児童相談所の部分、ただいま膠着した状態かと思いますけれども、この辺もう一度、現在の動き、この５カ月間の動き、何かございましたらお願いいたします。","respondent":"伊崎子ども育成課長","answer":"児童相談行政のあり方にかかわる都区の検討についてということで検討会が持たれておりまして、今年度になりましてからは第６回目、平成２４年度から第１回目が始まったのですが、第６回目の検討会が開かれております。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"区側としては強く要望を進めていただいているといった状況かと思います。具体的なスケジュール、そして都が求めてきた部分で具体案を示していらっしゃる、そういった状況かと思います。国のほうも、児童福祉法等の改正法案、平成２８年度通常国会提出を目指すということでさまざまな指針を示されております。細かいところを数点お聞きできればと考えています。","respondent":"伊崎子ども育成課長","answer":"児童虐待、要支援児童等に関するケースの管理ですけれども、要保護児童対策地域協議会の組織の中で児童虐待防止会議というのを設けまして、俗称ＰＣＡＮと呼んでおりますけれども、そちらの会議を月に１回定例で行うほか、ケース進行管理会議も同じく月１回。","id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"品川区内の連携はもちろんなのですけれども、児童相談所との連携もさまざまな課題が残っているかと思います。ケースが関係機関のすき間に落ちたり、また責任の所在が曖昧になるということを防いでいただきながら、これからも協働を進めていただいて、現在できること、そして移管に向けてできること、両建てでやっていただきたいということを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"あくつ委員","kind":"確認","question":"私からは、２４３ページ、子育て支援情報発信アプリ運用と、２２７ページ、２２９ページ、障害者福祉費から障害者週間・記念のつどいと、芸術活動支援事業、時間があれば２３９ページ、ひとり親家庭支援事業、子どもの貧困について質問をしたいと思います。１番目の子育て支援アプリですけれども、端的に伺います。今回導入するアプリの開発事業者と、他区における実績を確認させてください。","respondent":"伊崎子ども育成課長","answer":"今回のアプリを一緒に開発しております事業者ですけれども、実績としましては、世田谷区や墨田区で子育てアプリの構築、運用の実績があります。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問","question":"私も調べさせていただいて、大阪市の株式会社スマートバリュー。従業員数２４５名の会社ということで、世田谷区では２０１４年から、墨田区では２０１５年から同じところが導入されているということでした。今回の品川区版の目玉機能というのは一体何なのかというところで、伺います。ホームページの内容以外のものを何かプッシュ送信されるのか、その点について何かお考えのところがあれば教えてください。","respondent":"伊崎子ども育成課長","answer":"今、委員からご指摘いただきましたさまざまな子育て情報はもちろん掲載いたしますが、品川区の一つの特徴としましては、子育ての専門の方から子育てアドバイスというのを毎月掲載していただくようにしておりまして、そちらを配信していくということと、あとは。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"確認","question":"株式会社ミラボというところが特許を取って、これは千代田区の会社ですけれども、ここが特許を取っていて、スケジューラーはほかのところがつくれないということで、私も一瞬、品川区のものもスケジューラーがついているのかなと思ったら、どうもついていないようなのですけれども、だから、他区では結構、今回のアプリとスケジューラーを組み合わせて使っているところも、墨田区なんかも使っているし。","respondent":"伊崎子ども育成課長","answer":"予防接種の情報についてはほしいという意見はいただいたのですが、自分の情報をカスタマイズするところまでというご意見はなかなか、多くなかったということと、あと、実際には予防接種のスケジューラーのほうもいろいろ運用上、課題もあると聞いておりますので。","id":"exchange-046"},{"speaker":"あくつ委員","kind":"質問・要望","question":"接種の１カ月ぐらい前からカウントダウンでパパ、ママのところに５回ぐらいメールが来ると、こんなような内容も入っているみたいなので、ぜひお願いしたいと思います。最後に、品川区のプレス発表に、掲載情報はオープンデータ対応で、ＣＳＶやＸＭＬ等の形式で抽出可能とあるのですけれども、これは何を想定されているのか教えてください。","respondent":"仁平情報推進課長","answer":"こちらに蓄積されましたデータを二次利用可能な電子データとして取り出しまして、オープンデータとして区として公開していこうという予定になっております。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問","question":"イベント等、どのように事業者とか、民間で活用するのかイメージがわかないところがあるのですけれども、それは改めて伺いたいと思います。続きまして、障害者福祉費の芸術活動支援事業と、障害者週間・記念のつどいについて伺います。先ほど、天王洲地域に広げてというご答弁もあったのですけれども、会場や展示の規模等について、もう少し詳しく教えてください。","respondent":"中山障害者福祉課長","answer":"会場につきましては、天王洲アイルのビルのオーナーにお願いいたしまして、１階の部分を開放していただきながら、できれば駅からのアクセスというところで、ポスター展みたいなものができればということで現在、準備を進めているところです。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"提案","question":"ポスター展のような、私もさまざまなところで、まちとの親和性がアール・ブリュットというのは高いものですから、ぜひそういうものを進めていただきたいと思います。前にも提案させていただいたことがあるのですけれども。１つ気になっているのが、前回、しながわ水族館でやったときに、これもすばらしい取組みだった。これはもちろん当然だと思うのです。","respondent":"中山障害者福祉課長","answer":"第１回目はしながわ水族館で開催しましたのは、多くの方に見ていただきたいという思いからしながわ水族館で開催させていただきました。今回は天王洲アイルの地域を活用してということになりますので、入館料その他については特に必要はございません。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そうした展覧会でよく行われているのは、日時を決めて、その作品の前で作家の方がみずからその作品について、ご自分の生い立ちとか、言ってしまえば病歴等、さまざまなことを語りながら、どういう思いでその作品をつくられたのか、またそれをアートディレクターの方が補助をしながら説明をする、解説をするギャラリートークというものが結構行われていまして。","respondent":"中山障害者福祉課長","answer":"ギャラリートークについてのお尋ねです。今年度実施した事業についてはアフタートークということで、当事者の方は残念ながらお話ししていただく機会はございませんでした。当事者の方の中にはお話しできない方も多くいらっしゃる。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ロンドンオリンピック・パラリンピックでそういったところが非常に取り上げられて、全世界に発信をしていったというところも含めると、品川区においてもこういう障害者の方のダンスイベントを開催したり、また育成していくということを障害者分野の方と、またスポーツ分野の方でお話をしていただく、こんなことを検討していただきたいと思うのですが、いかがでしょうか。","respondent":"中山障害者福祉課長、池田スポーツ推進課長","answer":"障害のある方の芸術活動の中の身体表現というのですか、そういったところは確保ばかりではない、体を動かすこともすごく大事になってきていますので、活動の場ができるだけ広げられるような応援というのは考えていきたいと考えています。私どもは戸越体育館で障害者のためのスポーツの教室を毎年２月から３月の間、全５回でやっておりますけれども、以前、平成１９年には車椅子ダンスということで取り上げさせていただきまして。","id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問","question":"時間がありませんので、最後に子どもの貧困について１問だけ伺います。先日の一般質問のご答弁で、ひとり親家庭の中でさまざまな新しい仕組みを調査というか、分析をするのにつくられたというお話がありました、住民基本台帳ネットワークを活用した。それによって一体どのような対策ができるのか、今お考えのことを教えてください。","respondent":"廣田子ども家庭支援課長","answer":"現在のところ、ひとり親についてこれまで手当の受給者という形でしか把握できていなかったのですが、住民基本台帳から情報を得ることで手当を受給していないひとり親家庭の数とか、内訳について確認できるようになりましたので、ほかの手法と組み合わせまして。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"意見","question":"３つのターゲット、生活保護を受けている方、また、今ありましたひとり親家庭ということについては具体的なお答えがあったのですけれども、例示させていただいた就学援助を受けている方、この方たちが実は潜在的な、相対的貧困の方たちが非常に多く含まれているのではないかという認識がありますので、それは教育費のところでやれたらやりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"吉田委員","kind":"確認","question":"私からは、１項社会福祉費の中から、２２５ページ、重症心身障害児（者）在宅レスパイト事業と、２２５ページ、同じく１項社会福祉費の同行援護について伺います。それからもう１個、２６１ページの３項生活保護費の医療扶助について伺いたいと思います。ケースワーカーの数もそれに応じて増えているのか確認したいので、数を教えてください。","respondent":"伊東生活福祉課長","answer":"ケースワーカーの数ですけれども、現在では４３名のケースワーカーがおります。平成２６年に２名増やして４３名になりまして、平成２６年、平成２７年と来ております。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問","question":"それで、医療扶助の交通費のことを伺いたいのですけれども、生活保護者の中で医療扶助を受ける人には、条件はあるが交通費の扶助もあるというようにケースワーカーからきちんと伝えることになっているのか、現在、伝えているかどうか、把握していらっしゃるでしょうか。そのことを伺います。","respondent":"伊東生活福祉課長","answer":"説明というところだと思いますけれども、生活保護の受給が決まりましたら、担当ケースワーカーから生活保護のしおりに基づきまして、ある程度細かな部分まで説明をしています。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問","question":"移送費という言葉は、自分が主語で何かを移動させるときの費用というようにとれるのですが、広辞苑にも他の場所へ移し送ることとあります。これは確かに交通費のこととして捉えていいのか、また、この言葉のとおり、物を移送するときの費用も出ると考えていいのか、伺います。","respondent":"伊東生活福祉課長","answer":"日常的には通院とかで必要な場合は交通費という言い方もしているところでございまして、その辺に関しましては個々の方の相談を受けた中で、必要と認められる分に関しては支給しているという状況です。","id":"exchange-056"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、やはり感覚として、移送費というと自分が動くときの交通費とは捉えにくいのではないでしょうか。これは要望です。それから３点目は、先ほどケースワーカーの数を伺いましたけれども、具体的な数は挙げませんが、品川区の福祉に出ている医療扶助を受けている方の数を見ると、かなり多い。その辺のことは見直す必要があるのではないかと思いますが、この３点について見解を伺いたいと思います。","respondent":"伊東生活福祉課長","answer":"先ほど申し上げましたとおり、大きくケースが増えたときに職員のケースワーカーも増やしているという状況がありますので、今後の推移を見ながら、職員数については対応していきたいと考えております。","id":"exchange-057"},{"speaker":"吉田委員","kind":"質問","question":"ぜひ必要な人に必要な保護が行くように対応していただけるようにお願いします。次にいきます。次に、２２５ページの重症心身障害児（者）在宅レスパイト事業とあわせて、２３５ページの重症心身障害者通所施設運営費について伺います。これは、これまで課題があったピッコロの重症心身障害児レスパイト事業を契約どおりに遂行するための分の人件費として捉えてよろしいでしょうか。","respondent":"中山障害者福祉課長","answer":"本体の職員の配置を１人増やすことで、常時、必ず１日１名のレスパイトが受けられるような体制をということで、今回予算組みをしたものです。","id":"exchange-058"},{"speaker":"吉田委員","kind":"質問","question":"決特のときも質問させていただいたのですけれども、それができたということで、非常に評価しております。１日１人を受け入れる体制をつくるということですが、今までなかなか難しかったということを考えると、周知が必要かと思いますが、その辺どのように考えていらっしゃるか、伺いたいと思います。その辺の見直しを今後の検討課題とできないか、その点について伺います。","respondent":"中山障害者福祉課長","answer":"その方の状況の把握、それから、１回では出なかったけれども複数回様子を見ることで逆にわかってくる特別な支援、医療的に配慮しなければいけない支援も見えてくると思いますので、こちらについては、安全に安心してお使いいただくための次善の策と考えておりますので。","id":"exchange-059"},{"speaker":"吉田委員","kind":"提案","question":"３回というのがやはり使いにくいことの１つだと伺ったので、安全性の確保も必要だと思いますが、もし検討していただければと思いました。もう１つ、２２５ページの在宅レスパイト事業については新規ということですが、昨年の決特のときに課長のご答弁で、これはピッコロでの障害児レスパイトの使いにくさを補う形にもなる提案、あのときのご提案の１つと考えてよろしいでしょうか。","respondent":"中山障害者福祉課長","answer":"こちらについては、今、要綱を準備しているところとなります。それから、周知等の関係もありますし、事業者へあわせてご協力のお願いということで事業の周知等をする関係があるので、４月の実施は厳しいかなと思っているところです。","id":"exchange-060"},{"speaker":"吉田委員","kind":"質問・要望","question":"２２５ページの同行援護についてなのですが、まず、予算が増えていることについて、申請の増加を見込んでのことと考えますが、その増加の見込みの意味を伺いたいのと、それから、本当にメインで伺いたいのは、同行援護を受けている方たちが６５歳になったときの問題です。この答弁のとおり、同行援護は視覚障害特有のサービスとして考えてよろしいでしょうか。","respondent":"中山障害者福祉課長","answer":"それで、６５歳以上の方の介護保険優先の考え方についてなのですが、同行援護は介護保険優先のところとは外れると思っています。視覚障害のある方への移動、それから情報の援護ということになります。","id":"exchange-061"},{"speaker":"吉田委員","kind":"確認","question":"その点、確認できてよかったと思います。ただ、現実的には、６５歳になる前から、６５歳になったら介護保険に移るということを同行援護を利用されている方が言われていることがあるようなのです。やはり情報量の少ない障害の方は、それはおかしいというふうにきっちり反論ができない方もいらっしゃるのですが、その点についてはいかがでしょうか。","respondent":"中山障害者福祉課長","answer":"居宅介護で、例えば家事支援を受けている、あるいは買い物サービスを受けているというようなものは介護保険に移っていただくようになるのですが、ご本人様の外出支援と情報のそこにプラスアルファしての支援というところでは同行援護をご利用いただくようになりますので、職員。","id":"exchange-062"},{"speaker":"吉田委員","kind":"確認","question":"その点、確認できて大変よかったです。もう１点伺いたいのだけれども、視覚障害者で体が健康な方については介護保険を受ける必要がありませんよね。こういう場合も、介護保険適用になって、視覚障害特有のサービスだから同行援護は障害福祉のほうを利用するという、制度上の形はそういうことになるのでしょうか。わからないので教えてください。","respondent":"中山障害者福祉課長","answer":"６５歳になる前のサービスが同行援護だけであれば、介護保険の認定はなく、そのまま障害福祉サービスをご利用いただけます。","id":"exchange-063"},{"speaker":"吉田委員","kind":"意見","question":"いろいろなことが整理されて、わかりました。いろいろな点で、やはりこの６５歳問題は当事者の方にも誤解があるようなので、この辺、私からもお伝えしますけれども、ぜひ丁寧な説明をよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、２２２ページ、障害者福祉費にかかわって、合理的配慮とバリアフリーについて伺いたいと思います。平成２５年６月に障害者差別解消法が制定されて、その法の趣旨に沿って合理的配慮の具体化がこれから進められることになると思います。品川区障害者計画にも合理的配慮とバリアフリーが重要だと、進めていくとありますけれども、合理的配慮とバリアフリーの関係性について伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"障害者差別解消法がこの４月に施行されることに伴いまして、区は行政機関として合理的配慮の義務が生じてまいります。","id":"exchange-065"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"視覚障害者の方のところから、毎年、視覚障害者、また、団体の皆さんから要望書が出されていると思います。なぜ進まないのか、伺いたいと思います。そして、大井町線全駅にホームドアが設置されるということが、さっき、ほかの委員の質問でもあったのですが、旗の台駅にはいつ設置をされるのか、これも伺いたいと思います。あれば、伺いたいと思います。","respondent":"中村都市計画課長","answer":"旗の台駅のホームドア等の安全対策ですけれども、こちらも東急大井町線におきましては、東急電鉄株式会社が平成３２年までに整備を行うという計画のところまでは公表されておりますけれども、現在、来年度の中延駅の設置以降の計画につきましてはまだ検討中ということで。","id":"exchange-066"},{"speaker":"石田（ち）委員","kind":"提案","question":"旗の台駅のホームドアについては、毎年出されている要望だと思いますので、最優先に進めていただきたいなと思います。大井町駅前に点字の地図の案内板を設置してはどうかと提案をしたいと思います。一瞬忘れても確認できる、これは私たち目が見える者でも、駅前には地図があります。そういったことを視覚障害者の方にもしっかりと提供していただきたいのですけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"鉄道事業者につきましては、東急電鉄のみならず、ＪＲをはじめ、品川区内の鉄道事業者に対しましては、引き続き早急に実現をするようにお願いをしてまいります。その結果、現在、来年度以降の計画となったわけですけれども、引き続き依頼をしてまいります。","id":"exchange-067"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"点字の地図のほうはすぐにできることだと思いますので、ぜひ早急に進めていただきたいと思います。そしてさらに、私の地元ですけれども、南品川の新馬場駅南口に、住民の皆さんからエレベーターの設置が強く求められています。ぜひこうした状況を障害者福祉課にも知っていただいて、また、ほかの課と連携し、京急に改善を働きかけていただきたいと思いますけれども、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"ですから、費用のところと、それからやはり障害者の方の利便性を考えたときに、どういった策がとれるかというのは考えていかなければいけない問題かとは思っています。","id":"exchange-068"},{"speaker":"石田（ち）委員","kind":"質問","question":"障害者福祉計画にも、障害者にやさしいまちづくりの推進のところに、鉄道事業者を支援し、区内鉄道駅においてバリアフリー化を進めますとしっかりと明記されています。ですので、こういった観点からも、バリアフリー、合理的配慮の観点からも、現地調査をして、ぜひ改善をお願いしたいと思います。新年度、合理的配慮として、区役所や区の施設で改善されるところは何か、伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"これから職員対応要領もつくってまいりますが、その中では、個別の場面において職員が障害のある方と向き合ったときにどのような配慮が必要かということを明記し、職員研修なども行うことで、職員１人１人がこの合理的配慮ができるようにやっていきたいと考えています。","id":"exchange-069"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"職員の対応のところで要領ということですけれども、ハードの部分は今回は入っていないと。この間、共産党としても、区役所窓口に磁気ループの設置を求めてきました。相談や問い合わせ、コミュニケーションに大事なものだと思います。障害者福祉課や高齢者福祉課の窓口はもちろんですが、保育課や国保医療年金課など、すべての窓口に磁気ループの設置を求めたいのですが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"個別の窓口で、聞き取りにくいというお声があれば、やはり職員が１人１人対応し、音からの情報だけではなく、例えばメモを書いて視覚からの情報にも訴えるとか、相手の方が理解して、相談に来て、必ずその結果として理解ができたというものをお持ち帰りいただけるような。","id":"exchange-070"},{"speaker":"石田（ち）委員","kind":"質問","question":"は職員１人１人のというのは大事なところですけれども、そういった職員の皆さんも磁気ループがあることでよりよいコミュニケーションが区民ととれるのではないかなと思います。現在はイヤホンは増やされているのでしょうか。そして、磁気ループが設置されている区の施設はどこかを伺いたいと思います。そして、それぞれイヤホンがどれぐらい用意されているのかを伺いたいと思います。","respondent":"間部文化観光課長","answer":"スクエア荏原の磁気ループの状況ですが、スクエア荏原につきましてはひらつかホールに常設型の磁気ループが設置されております。移動型が１セットということで、どのお部屋でも使える状況になっております。専用の受信機につきましては５台常設をしています。","id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"積極的に知らせることを求めたいと思います。声を寄せていただくというのはうれしいことですけれども、それだけ改善してほしいことがあるということですので、障害者計画をつくるにあたってアンケートもとられたと思うのですけれども、ぜひ区のほうでさらに広く声を聞いていただきまして、ほかの障害者同士も理解し合えるようなシンポジウムも行ってはいかがかなと思いますけれども、いかがでしょうか。","respondent":"間部文化観光課長、中山障害者福祉課長","answer":"きゅりあんの大ホールにおきましては、骨伝導のヘッドホンが５台あります。イベントホールにつきましては補聴器は１０台設置しています。五反田文化センターにおきましても、イヤホンについては５台セットしています。そうした中でも、区の中でこういう施設でこういう取組みがあるというようなことであったり、あるいは区役所の中で合理的配慮でこういうことを今やっていますというようなことを周知していくように努めてまいりたいと思います。","id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"さらなるＰＲをお願いしたいと思います。違う障害を持った皆さんが、それぞれの障害がどういうものなのか、どういった配慮が必要なのかということをそれぞれが知っていく、そういった場をつくってこそ、１人１人の障害者の声に応えていくという合理的配慮が進むのではないかなと思いますので、ぜひ検討していただきまして、合理的配慮とバリアフリーをさらに進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"鈴木（博）委員","kind":"質問","question":"品川区の待機児童対策についてお伺いします。第１回定例会の質問や予算特別委員会のこの間の質疑などにより、平成２８年度もかなりの待機児童が出る可能性があると認識しました。私はこの１年間、文教委員会で活動してきました。このような懸命なご努力にもかかわらず増え続ける待機児童を区はどのように分析され、今後どのような対応策をお考えなのでしょうか。","respondent":"今井待機児童対策担当課長","answer":"今、いろいろな区で、自治体で開設してほしいということでそれぞれの事業者が対応しておりますので、引き続き特区の活用で用地の確保などとともに、事業者をよく見きわめながら、開設に向けてさらに努力をしていきたいと考えています。","id":"exchange-074"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ありがとうございました。今井課長らしいご答弁だったので、よくわかりました。それは場所が限られているということと、保育園を選定しても地域住民が反対する事例もあったように伺います。とりわけ保育士が足りないということは、現場にいる私として、これは大きな問題だと日々感じています。そこで質問いたします。区は保育士不足をどのように捉えているのでしょうか。その点もご報告をお願いいたします。","respondent":"竹田保育課長","answer":"それからもう１つ、保育士資格を持っているけれども未就職の保育士に対して、現在の保育事情を説明し、体験していただくことによって再就職を促すセカンドチャレンジ保育士支援事業をやっているところです。","id":"exchange-075"},{"speaker":"鈴木（博）委員","kind":"質問","question":"待機児童に対する取組みは全国の自治体で強化され、先ほど課長からもお話があったように、保育所が急増する中で保育士不足は深刻です。保育士の奪い合いは保育所の質の低下を招きます。先ほどの委員会での課長の答弁では保育士の離職率の高さについて言及がありましたが、保育士の離職対策に関しては、今少しお話もありましたが、区はどのような具体的な対策をお考えなのか、もう一度ご説明をお願いします。","respondent":"竹田保育課長","answer":"先ほど申し上げました保育士不足の施策をさらに推進することによって、保育士の確保に最大限、全力を挙げて取り組んでいきたいと考えております。","id":"exchange-076"},{"speaker":"鈴木（博）委員","kind":"質問","question":"待遇の面での対応は当然必要なのですが、保育士が離職する原因として、職場のストレス、これは親だとか同僚だとか子どもそのものだとか、あるいは利用者の保護者だとか、こういう精神的なケアも非常に大事だと思うのですが、その辺の対応策も考えていらっしゃるのでしょうか。","respondent":"竹田保育課長","answer":"私立保育園に関することですが、私立保育園にはそれぞれ独自の方針、保育、教育がありますので、それらを尊重しながら、連合会と十分相談しながら、できる限りの支援をしていきたいと考えております。","id":"exchange-077"},{"speaker":"鈴木（博）委員","kind":"提案","question":"先に進みます。さらに２０１５年９月には、厚労省は保育・介護などのサービスが１つの施設で受けられる共生型施設の普及を打ち出しました。品川区でも始まったおとしよりと子どものふれあい事業にも通じる、介護と保育の一体化した国の施策を先取りした人材育成を始めることは、福祉・子育ての先進区、品川ならではの取組みと評価されると考えますが、将来の課題として区はいかがお考えでしょうか。","respondent":"竹田保育課長","answer":"委員のご提案は大変興味深いものですが、国の動きを注視しながら研究させていただきたいと考えております。","id":"exchange-078"},{"speaker":"鈴木（博）委員","kind":"質問","question":"簡潔なお答えをありがとうございました。次に、認可外保育施設についてお伺いします。認可外保育施設について簡単にご説明をお願いしたいのと、品川区には認可外保育施設が幾つぐらいあるのでしょうか。東京都福祉保健局に認可外保育施設として届出を行っている認可外保育施設も、届出を行っていない、無届けの認可外保育施設も品川区には存在するのでしょうか。","respondent":"竹田保育課長","answer":"認可外保育施設にも基準等がございまして、保育に従事する人数、面積あるいは消防用具や非常口設置等の基準があります。その基準に基づいて都に届出をしている施設が、認証保育所を除きますと、区から補助を受けていない施設が約１４施設あります。","id":"exchange-079"},{"speaker":"鈴木（博）委員","kind":"質問","question":"杉並区では、平成１９年から子育て応援券を発券しています。例えば品川区では出産・子育て応援カタログギフトという１万円のクーポン券の配布を始めましたが、物品購入だけではなく、保育所やさまざまな育児サービスの利用にも使用できるようになれば、子育て家庭にとって非常に喜ばれるのではないでしょうか。ぜひ子育て応援券の検討をお願いしたいと思いますが、区の考えはいかがでしょうか。","respondent":"伊崎子ども育成課長","answer":"区の子育て支援施策の考え方としましては、それぞれの区民の方のニーズに合った事業を提供したり、あとは補助していくという考え方ですので、現在、新たに子育て応援券という、そのものを導入する考え方は持っておりません。","id":"exchange-080"},{"speaker":"鈴木（博）委員","kind":"質問","question":"わかりました。これについてはまたおいおい続けて質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"塚本委員","kind":"確認","question":"重症心身障害児（者）在宅レスパイト事業なのですけれども、これは先ほどの委員からもあったのですが、１点だけ確認をしたいのですが、訪問看護型ということで今度実施されるということなのですが、訪問看護は利用者が訪問看護ステーションから看護師を派遣していただいてということなのですけれども、主治医意見書により状態像を確認、把握ということで、医者と看護師との連携というか。","respondent":"中山障害者福祉課長","answer":"こちらは通常在宅にいらして既に訪問看護を使っている方が対象になっておりまして、同様の看護ステーションからレスパイト事業の分を配置する予定でおります。ですので、主治医との連携についても十分できているという想定のもとで行うものです。","id":"exchange-082"},{"speaker":"塚本委員","kind":"質問","question":"そうしますと、今現在利用していない方が新たに利用していこうとした場合はどういった手続になるのか、簡単にご説明をお願いします。","respondent":"中山障害者福祉課長","answer":"ただ、やはりそういった中でも一定の訪問看護事業を使っていただいて、慣れた看護師のもと、レスパイトを行ったほうがいいのではないかと考えておりますので、こちらの事業を使う前には相談をいただきまして、支給決定をして。","id":"exchange-083"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。次に、児童発達支援事業等運営補助事業なのですけれども、これは平成２７年、今年度の予算にも計上されておりましたが、今時点でこの事業について検討している業者が存在するのかどうか、また、この児童発達支援事業の利用を想定している人はどういう方なのか、この施設は今ないわけなので、現在そういった方々はどういったご苦労があるのか、そういったところをお伺いします。","respondent":"中山障害者福祉課長","answer":"その中の１つの社会福祉法人とこのまま事業ができそうなところまで行ったのですけれども、結果的に確保した物件の最終的な契約の段階で、オーナーから断られてしまいまして、今年度実施することができませんでした。","id":"exchange-084"},{"speaker":"塚本委員","kind":"質問・要望","question":"断られてしまったということで、理由はここでは特に聞きませんけれども、求められている利用者の方はきっとたくさん品川区にいらっしゃるのだろうと思います。ぜひ来年度、この事業が開設できるようにご尽力いただきたいなという思いですので、どうぞよろしくお願い申し上げます。","respondent":"高森国保医療年金課長","answer":"それと、軽度リスク保持者対策ということで、ご案内のありました国保保健指導、現在も実施しているわけですけれども、こちらについては対象は１,５００件ということで、今までは利用案内につきまして一律同じ文言でご案内をしていたところですけれども。","id":"exchange-085"},{"speaker":"塚本委員","kind":"質問","question":"１つだけお伺いしたいのですけれども、この事業でインセンティブという考え方も厚労省から示されておりますが、インセンティブについて、今回品川区が事業をやる上で何か検討されていることがあったのか、そのことを一言だけお願いします。","respondent":"高森国保医療年金課長","answer":"平成２７年度も実施しているのですけれども、早得キャンペーンということで、６月、７月。","id":"exchange-086"},{"speaker":"木村委員","kind":"質問","question":"私からは、２１３ページの上から５行目、成年後見制度利用支援事業３４３万３,０００円からの質問ですけれども、後見制度とは判断能力の十分でない方々の財産を第三者が管理する制度ですが、提示をされている３４３万３,０００円は高齢者と障害者の方にお使いになる予算と思いますけれども、高齢者何名分、そして障害者何名分の記載がありません。","respondent":"大串福祉計画課長、中山障害者福祉課長","answer":"こちらにつきましては１０万円の経費がかかるということで４件分。それ以外には収入印紙代ですとか、あるいは郵券代、こういったものが入って１２７万３,０００円という金額になっているところです。基本報酬７件分と、それから監督人をつけた場合の監督人の２件分ということになっております。","id":"exchange-087"},{"speaker":"木村委員","kind":"意見","question":"３類型あると思いますけれども、後見、保佐、それから補助のうち、本区にはどの類型が多くいらっしゃるのかということ、そして、行政として認知症と思われる人が区内にどのくらいいるのかということは把握されているのか、お聞かせください。","respondent":"大串福祉計画課長","answer":"委員おっしゃるように、類型としては３類型あるのですが、類型ごとでの集計は手元に持ってございません。基本的に後見人の後見類型が一番多くなっているという形です。","id":"exchange-088"},{"speaker":"木村委員","kind":"意見","question":"現在、医療や薬、そしてあらゆることが発達をし、進歩しまして、男女ともに平均寿命自体が延びております。男性は約９年間、女性におきましては１２年間が医療や介護を必要とされる年数でありますけれども、現在までの状況で、年間どのぐらいそういう方々が増えているのかどうかということをお聞かせください。","respondent":"大串福祉計画課長","answer":"後見の申立て件数ということでよろしいでしょうか。区長申立てということで、平成１６年以前からこれを行っておりますけれども、平成２７年度末現在で家庭裁判所に申し立てた件数は３６６件という数字になっております。","id":"exchange-089"},{"speaker":"木村委員","kind":"質問","question":"先日の新聞で若年性認知症が増えてきているという報道がありました。本区でもそのような調査をされているのかどうか。若年とは幾つを指して言う言葉なのでしょうか。行政としては患者削減の方法というお考えがあるかどうか、お聞かせください。その方法です。あったら教えてください。","respondent":"永尾高齢者福祉課長","answer":"若年の認知症の方の件数ですけれども、区でつかんでいるというのは、認定をしている方の中で４０歳から６４歳までの方で高齢者の日常生活自立度が２以下の方ということですけれども、大体１２２人が今、区でわかっているところです。","id":"exchange-090"},{"speaker":"木村委員","kind":"質問","question":"基本的には家族が看ることがベストなのですけれども、後見人になる方は、法律家以外ではどのようなことに、また、どのような方々が後見人としてついていただけるのか、教えてください。","respondent":"大串福祉計画課長","answer":"それ以外にも、例えば「しんきん成年後見サポート」ですとか、あるいは市民後見人、こういったＮＰＯ、成年後見が増えていく中で、いろいろな形で支えていくような団体、ＮＰＯが増えてきているといった状況です。","id":"exchange-091"},{"speaker":"木村委員","kind":"質問","question":"今度は２１５ページの上から６行目、やさしいまちづくり推進費からですけれども、このやさしいまちづくりとは、ハードとソフトの面がありますけれども、こちらではどちらの推進のことでしょうか。そして、やさしいまちづくりとは、誰もが普通に暮らせるまちづくりが基本ですけれども、ユニバーサルデザインの考えがベースになっていると考えてよいのでしょうか。お聞かせください。","respondent":"大串福祉計画課長","answer":"ユニバーサルデザインの普及啓発や、あるいはその一環としてやっておりますおたがいさま運動の普及啓発、こういった形で誰もが安心して快適に暮らせるような福祉のまちづくりをソフトの面から普及啓発、こういったことを通じて行っていくという事業です。","id":"exchange-092"},{"speaker":"木村委員","kind":"質問","question":"ユニバーサルデザインの考え方を基本として、ソフトの部分の充実に取り組む「すべての人にやさしいまちづくり推進計画」の活用について、区民の方の理解度はどれぐらい行き届いているとお考えでしょうか。この推進計画をどのように区民に周知をしていくのでしょうか。お聞かせください。","respondent":"大串福祉計画課長","answer":"区民の方の理解度というところですけれども、なかなか数値的にはあらわすことが難しいのかなと考えているところです。","id":"exchange-093"},{"speaker":"西本委員","kind":"質問","question":"２５３ページ、児童センター事業についてお聞きします。この間、いろいろと質問していますが、いろいろ答弁いただいてもどうしても納得いきませんので、再度お聞きします。なぜ民営化なのでしょうかという理由をまずお聞かせください。年代も０歳、お腹にいるときから１８歳ぐらいまでをカバーしている。そして、児童センターそのものの役割がどこにあるのかを教えてください。","respondent":"竹田保育課長、伊崎子ども育成課長","answer":"さらに今後、老朽化した施設の改築、大規模改修等を控え、増加していく行政需要に対して行政サービスを提供していくためには、より効率的な行政運営を考えなければならないことは当然のことであり、その１つが民営化と考えております。それにあわせまして地域の子育て世帯への支援を行っていく施設と考えております。","id":"exchange-094"},{"speaker":"西本委員","kind":"質問","question":"確かに当たり前ですよね、経費が増えていくのは。待機児童解消ですから、待機児童を解消していくために保育園をつくっていくのは当然のことだと思います。待機児童ゼロを目指している。それだけのコストをかけるというのは当然、当たり前といいますか。そうすると、公立保育園の役割は何ですか。品川区のこれからの公立保育園の役割は、どうなのでしょう、終わってしまったと考えてよろしいのでしょうか。","respondent":"竹田保育課長","answer":"品川区の公立保育園、今まで全国に先駆けて数々の事業を実施してまいりました。これからもそういう気構えで進めていくことに変わりはございません。","id":"exchange-095"},{"speaker":"西本委員","kind":"質問","question":"最近、見えないのです。子育て支援の中での保育園ひとつとっても、品川区の子育て支援を考えたときに、どういうビジョンがあって、どういう流れがあるから、なので今回は民間が育ってきたので民間に頼んでいきましょうというようなことがあるのかもしれませんけれども、全体をどうしていくのか、その中での民営化ということなのか。その辺はいかがでしょうか。","respondent":"竹田保育課長","answer":"そういったことは私立保育園とも共有できるところであり、しっかりと連携できる、あるいは今後も進めていけると考えております。","id":"exchange-096"},{"speaker":"西本委員","kind":"質問","question":"公立である意味というのはどういうところなのでしょうか。先ほども質問しましたけれども、公立保育園の役割をどう考えられているのでしょうか。再度お聞きします。","respondent":"竹田保育課長","answer":"公立の役割ということですが、さまざまなものがあると思います。私立保育園が難しい部分をしっかりとカバーして連携していきたいと考えております。","id":"exchange-097"},{"speaker":"西本委員","kind":"質問","question":"よくわかりません、今の話では。今の答弁では全くわかりません。公立保育園の意義は何ですか。これから品川区がやろうとしている子育て支援の中での公立保育園の役割は何ですか。なので、品川区のこれからの子育ての位置づけとして公立保育園をどう考えられているのでしょうか。お答えください。","respondent":"金子子ども未来部長","answer":"ただ、委員にお話しいただいたように、最近ではやはりどうしても公設公営であることはコストがかさむということもありまして、品川区としては公設民営、そしてまた、民立民営を一部検討していくということで考えているところです。","id":"exchange-098"},{"speaker":"沢田委員","kind":"確認","question":"２３９ページのひとり親家庭支援事業と、それから２２５ページ、２２９ページの障害者の自立支援、就労支援についてお伺いしたいと思います。先ほどあくつ委員からもありましたけれども、ひとり親家庭のことについて、確認したいことも含めて聞いていきたいと思います。子どもの貧困、貧困の連鎖ということもありますけれども、区としてのひとり親世帯の現状と状況の推移について確認をさせてください。","respondent":"廣田子ども家庭支援課長","answer":"品川区のひとり親の実態ですが、手当等を受けている世帯数につきまして、現在、品川区で児童扶養手当については１,８７１世帯、児童育成手当については２,４５９世帯で、基準が異なっておりますので、児童育成手当の２,４５９世帯が。","id":"exchange-099"},{"speaker":"沢田委員","kind":"確認","question":"今お話ありましたとおり、ひとり親家庭は年々増えているということで、品川区においても状況的には１年であっても増えてきているということであります。制度自体を知らないひとり親家庭が４割を超えているという状況です。このことに対して、区の状況の認識と、周知とか広報についてはどのような形で必要な方に制度が行き届いているのかということで、確認をさせてください。","respondent":"廣田子ども家庭支援課長","answer":"今後、充実していく事業もありますので、周知を図り、さらに拡大ということで、ひとり親に対するしおりを毎年作成しておりますが、ここの拡充を図るということと、平成２８年度に関しましては、広報紙である程度大きい紙面をもらって。","id":"exchange-100"},{"speaker":"沢田委員","kind":"意見","question":"今、広報体制は今回の予算の中でもひとり親家庭のしおりの作成ということで、こうやって広報していくということでありますけれども、待っているという姿勢だけでなく、ある程度出ていくというか、出向いていって、訪問して相談に乗ったり、アウトリーチ型の相談を積極的に行っていくことも考えてはどうかと思うのですけれども、そのあたりのことについてお聞かせください。","respondent":"廣田子ども家庭支援課長","answer":"事業の周知という面も含めてですが、児童育成手当でありますとか、ひとり親の手当を受給している世帯に対してしおり等は郵送で送って、事業を認識していただくように努めようと考えています。","id":"exchange-101"},{"speaker":"沢田委員","kind":"質問・要望","question":"そういったことも考えると、死別というのは精神的にも大変大きなダメージを受けた直後に、現実的にはやり慣れていない家事とか子育てが待ち受けているということで、本当にそういった意味ではすごく厳しいということで、都の資料の事例に、相談に行ったら、児童養護施設に相談に行かれたらどうですかというようなことを言われたという事例も載っていましたけれども。","respondent":"廣田子ども家庭支援課長","answer":"相談件数等につきましても、父子家庭からも相談はいただいておりますが、現在、件数が母子家庭のほうが圧倒的に多いという状態ですので、父子家庭については、今後、相談の内容等で分析しまして、検討課題として施策については考えていきたと考えています。","id":"exchange-102"},{"speaker":"沢田委員","kind":"質問・要望","question":"今回のもそうですけれども、ひとり親家庭支援は本当に多岐にわたって、生活福祉的な部分から学習支援や相談事業に至るまで、さまざまなことが行われていますけれども、基本的にはワンストップというか、窓口としては子ども家庭支援課ということでよろしいのか、最後に確認をさせてください。","respondent":"廣田子ども家庭支援課長","answer":"現在も暮らし・しごと応援センターの窓口と、私ども子ども家庭支援課の窓口とで、ケースによって連携はとっているところですが、なかなか見えにくいというご意見をいただいておりますので、ひとり親のしおりに、窓口について連携しているというところで図示したものをつけまして。","id":"exchange-103"},{"speaker":"沢田委員","kind":"質問・要望","question":"ちゃんと取り組まれているということで、いろいろな分野にわたっている窓口をできるだけ１つにまとめて、しっかりとした支援体制を整えていっていただきたいと思います。それで、受注等をあっ旋したり、仲介する業務を行う共同の受注の窓口等の整備をするなど、そういった障害者の就労について、より積極的に取り組んでいくべきではないかと思っているのですけれども、区の体制についてお聞かせください。","respondent":"中山障害者福祉課長","answer":"それで、例えば今年度ですけれども、地域の開拓支援ということで、企業のご相談に乗ったり、あるいは勤めている方を見にいきがてら、お話をしたりということで、現在、相談実績としては、企業の相談実績が５４０件、それから地域開拓支援ということで。","id":"exchange-104"},{"speaker":"沢田委員","kind":"質問・要望","question":"ＣＳＲ協議会もありますけれども、加盟企業等を、積極的にそういったところに干渉していって、企業側から積極的なマッチングをしていけるということを区としても求めていっていただきたいと思うのですけれども、そのあたりの対応はどうなっているでしょうか。","respondent":"中山障害者福祉課長","answer":"こうしたことをＣＳＲ協議会加盟の企業にもお伝えしつつ、実質的に障害のある方が一般企業で働くことができる風土づくりも行っていきたいと考えております。","id":"exchange-105"},{"speaker":"こんの委員","kind":"質問","question":"私からは、２５１ページのオアシスルーム運営費の中の開設経費、もう１つが２５５ページのすまいるスクール運営費、その２つをお聞きしたいと思います。","respondent":"竹田保育課長","answer":"従来、商業・ものづくり課で全て使用していた施設ですけれども、面積に余裕が出るということで、今回、在宅支援の強化という観点あるいはネウボラネットワークの観点から、オアシスルームを増設する用地として活用する計画です。","id":"exchange-106"},{"speaker":"こんの委員","kind":"質問","question":"開設するのは承知しております。どのような形で施設が開設をされていくのか。あの建物自体のいわゆる開設費用が出ているということですから、改修工事なども行われて、そこにお子さんを受け入れる施設として生まれ変わると想像するのですが、どのようなものになっていくのでしょうか。","respondent":"竹田保育課長","answer":"大変失礼しました。こちらの施設は、対象が生後４カ月のお子さんから１２人の定員を予定しておりまして、センターの１階部分にオアシスルームを設置する予定です。","id":"exchange-107"},{"speaker":"こんの委員","kind":"質問","question":"かなりの費用がかけられているここの開設費用ですけれども、確かにお子さんを受け入れて、ショートステイもするということですから、預かってお泊りができる施設に生まれ変わるのだろうと思うのですけれども、あそこの周りの環境をお聞きしたいのですが、施設の周りの環境、隣は区の公園があるのですが、その側道、いわゆる建物の側道は大井第一小学校の坂道をずっと下がってくるところで。","respondent":"伊崎子ども育成課長、竹田保育課長","answer":"今、委員からご指摘ございましたショートステイですが、こちらはものづくり創造センター内で行うということではなく、今現在実施しております家庭あんしんセンターの中の子育て支援センターでのショートステイの要件を拡充するです。現在の工事の計画ですが、中央部分に玄関を設けまして、入って左手がオアシスルームで、その奥にスタッフルーム、厨房等を計画しております。","id":"exchange-108"},{"speaker":"こんの委員","kind":"質問・要望","question":"歩道が狭い、そうしたところの入り口の安全面はどうするのか、開設するにあたってはよくよくここの整備をしていただきたいということのお願いです。もう１つの質問にまいります。すまいるスクールの運営費なのですけれども、こちらも時間延長、利用されるお母様方がこれから大変に喜ばれるところでありますが、この時間延長についての職員の体制をまず教えてください。","respondent":"竹田保育課長、伊崎子ども育成課長","answer":"敷地右手に駐車スペースがありますので、十分安全を確保した体制にしたいと考えています。必ずリーダー、またはリーダーにかわる責任を負う者と、あともう１人以上。人数については利用の児童数に応じてということになりますが、最低２人以上の委託の職員を常駐させることになります。","id":"exchange-109"},{"speaker":"こんの委員","kind":"質問","question":"委託業者の方が預かるお子さんの人数によって２人以上つくと。聞くところによりますと、リーダーがつかない場合、また、区の職員がつかない延長保育での体制は、何かあったとき、緊急時にはどう対応したらいいのかという声も聞こえておりますし、また、保護者の間でもそれはどうなっているのかしらというお声も聞こえますので、委託業者への説明、そして徹底はどのようにされていますでしょうか。","respondent":"伊崎子ども育成課長","answer":"委託業者に関しましては、来年度以降の事業についてということで説明を行っておりますが、特に午後６時以降の体制についてということを取り上げて説明を今現在していることではございませんので、おそらくそこの説明が十分行き渡っていない状況であるかと思います。","id":"exchange-110"},{"speaker":"こんの委員","kind":"質問","question":"ぜひお願いしたいと思います。もう１つ、すまいるスクールは来年４月１日から、春休み中から預かってくださることになると思いますが、新１年生については、幼稚園、保育園、３月下旬は春休みに入っておりますけれども、この体制は３月、既に来年４月１日と決まっているのですけれども、今後、春休みの３月下旬から預かっていただく体制というのはどのようにお考えでしょうか。","respondent":"伊崎子ども育成課長","answer":"春休み期間のご利用につきましては、やはり小学校１年生の年齢になられます４月１日からと考えております。３月中は、保育園のお子さんでしたら保育園で、幼稚園のお子さんでしたらご自宅で就学に向けての準備を十分に整えていただきたいと考えております。","id":"exchange-111"},{"speaker":"のだて委員","kind":"質問","question":"私からは、２３１ページの特別養護老人ホーム運営費に関連して質問します。半年間で約１００人が入れるかどうかというところですので、長年申し込んでも入れず諦めてしまう方や、入れないまま亡くなる方もいらっしゃるくらい、待機者を生み出しているという状況です。区の新たな人口推計でも、高齢者人口は平成６７年まで増え続けていきます。４カ所目の検討で何がどこまで進んだのか、伺います。","respondent":"大串福祉計画課長","answer":"今後増えていく高齢者の皆様の個々のニーズや状態像、あるいは介護保険に与える影響といったものを全体的に総合的に判断しながら、施設整備については検討していきたいと考えているところです。","id":"exchange-112"},{"speaker":"のだて委員","kind":"質問","question":"総合的に判断していくということですけれども、今、特養の検討地について伺いました。総合的にというだけでは中身が全然見えてきません。この間、平成２７年度と平成２８年度では、この検討、何がどう違うのでしょうか。","respondent":"大串福祉計画課長","answer":"それ以外にもグループホーム以外の施設、あるいは、先ほども申し上げましたけれども、ソフトの支援といったものを含めて総合的に判断をしながら、高齢者の施策を進めていっているところです。","id":"exchange-113"},{"speaker":"のだて委員","kind":"質問","question":"これから整備していくということですけれども、それで増えても２００人分が増える。今、待機者が４５０人ということなので、まだ２００人以上待機者がいることになってしまいます。現状で足りていると思っているのでしょうか。","respondent":"大串福祉計画課長","answer":"特養だけではないということを再三申し上げているところです。それ以外の施設の整備も行っておりますし、また、こういったハード整備だけではなく、ソフトの支援もあわせて行っていくといったところで、総合的に高齢者の施策を進めていくべきものと考えているところです。","id":"exchange-114"},{"speaker":"のだて委員","kind":"質問","question":"総合的にやっていくということですけれども、特養の整備について今お伺いしています。今の数が今後整備されて１,１８４人分になると思うのですけれども、それで足りていると思っているのか、ここを聞いているので、もう一度お願いします。","respondent":"大串福祉計画課長","answer":"再三の答弁になりますけれども、特養だけが高齢者施策の施設というわけではございません。それ以外の施設の整備も含めて全体的に高齢者施策を考えていくべきものと考えております。","id":"exchange-115"},{"speaker":"のだて委員","kind":"質問","question":"幾ら聞いても総合的にというだけなのですけれども、足りていないという気持ちがないのかと思ってしまいます。今、老老介護が原因で無理心中するような報道もされております。在宅介護が困難で、何とか生活している方もいらっしゃいます。こういった方を助けるためにも、特養ホームなどの入居施設の増設で介護の負担軽減をしていくべきだと思いますが、いかがでしょうか。","respondent":"大串福祉計画課長","answer":"私も品川区の考えといたしましても、住み慣れた我が家でいつまでも暮らし続けるといったところを支援するというのが一番大きな目的です。","id":"exchange-116"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間、無理心中の件でも、長年連れ添ったパートナーをみずから殺すということは、私には想像できない苦しみがあると思うのですけれども、そういう方をなくすための対策が必要だと思いますが、区はどう考えているのか、伺います。","respondent":"大串福祉計画課長","answer":"特養につきましても、先ほども申し上げましたように、２カ所を計画し、整備を順次進めているところで、セーフティーネットの整備、あるいはまた、在宅生活を継続するような形でのソフト、こういったサービスの充実、総合的に展開をしています。","id":"exchange-117"},{"speaker":"のだて委員","kind":"質問・要望","question":"さまざまやっていくということなのですけれども、具体的には何をやっていくのか、伺いたいと思います。定期借地権期間の５０年の中で、事業者負担も４８％から３９％に軽減されるとしています。この新たな制度も活用して、小山台住宅や峰友寮跡地などの国有地に特養ホームを増設していただきたいと思いますが、区としてはこの新制度の活用を考えているのでしょうか。","respondent":"大串福祉計画課長","answer":"今例示を挙げていただいた国有地等々ですが、先般の第１回定例会の一般質問でもお答えしましたように、それぞれの土地の特性あるいは利用状況等々ありますので、そういったものを十分考慮しながら判断をしていきたいと考えているところです。","id":"exchange-118"},{"speaker":"のだて委員","kind":"質問・要望","question":"無理心中の具体的な対策もお聞きしたので、答えていただきたいと思います。土地の特性によって検討していくということですけれども、やはり特養ホームが全然足りていないと思いますので、新しい制度もしっかり活用して、増設していっていただきたいと思います。あわせて、介護老人保健施設も足りません。ぜひ３カ所目以降も計画していただきたい。３カ所目を踏み出せない課題は何でしょうか、伺います。","respondent":"大串福祉計画課長","answer":"それにあわせた形での福祉のソフトのサービス、こういったものとあわせながら、高齢者の施策を進めていくべきと考えております。これまでも区はそのような形で取り組んでおりますし、今後ともそうした姿勢で取り組んでまいりたいと考えているところです。","id":"exchange-119"},{"speaker":"のだて委員","kind":"質問・要望","question":"総合的な判断の中にも、特養と老健を含めて増設していっていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"渡部委員","kind":"質問","question":"児童福祉費について伺います。誰かが聞いてくれればそれで済むと思っていたのですが、２５５ページ、児童センター運営費の中で、「わっくわくランドしながわ」を説明してください。","respondent":"伊崎子ども育成課長","answer":"それを５月の児童福祉週間のときに、屋外でやるということで、名称も変更して、リニューアルして行うものです。","id":"exchange-121"},{"speaker":"渡部委員","kind":"質問","question":"委託の方とかは、この４月、間に合っていくのか。まさか子どもが現金を封筒に入れて持っていくわけないと思いますので、となれば、そういう手続も踏んでいかなければいけないとなると、相当スピード感を持って、当然４月にしかできないのかもしれない、逆に言うと４月がそれだけ大変になるのかなと思うのですけれども、その辺の仕組みを教えていただけますでしょうか。","respondent":"伊崎子ども育成課長","answer":"保護者の方々へのご説明ですが、新１年生の保護者の方につきましては、１０月の学校説明会のときにまず文書を配布していただきまして、その後、１１月の就学児健診でも同じように文書を配布いたしました。","id":"exchange-122"},{"speaker":"渡部委員","kind":"確認","question":"わかりました。これは一月まとめて申込みですから、７時まで何曜日とか、具体的な申し込みではないですよね。基本的には私の家の子どもは７時まで預かってもらいますという契約だと思うのですけれども、その中で来る日来ない日の判断までそこで出してもらっているのですか。無理ですよね。ではなくて、当然そのときそのときになりますけれども、そういうときの確認はいつまでとかというルールはあるのですか。","respondent":"伊崎子ども育成課長","answer":"特に１、２年生については、すまいるスクールに来るはずなのに来ないというときは、電話連絡を保護者にとることもできますので、そういった方については必ず変更のご連絡をいただくようにしております。","id":"exchange-123"},{"speaker":"渡部委員","kind":"質問","question":"７％というのは全体のパイに対してではなくて、１年生から３年生の割合の中の７％ということですよね。でも、結構申込みがあるのだなと思います。この辺は何か延長と関係があったのかどうかというのを教えてください。","respondent":"伊崎子ども育成課長","answer":"先ほど申し上げました６時までと７時までのお申込みの割合につきましては、お申込み総数８,６３２人のうちのパーセンテージです。それから、職員数の増につきましては、この時間延長と直接関係があるものではなく、再任用職員を含めた職員数の増です。","id":"exchange-124"},{"speaker":"渡部委員","kind":"確認","question":"わかりました。すまいるスクールは、平成１３年に第二延山小から始まって、いろいろ紆余曲折があって所管が変わったり、全校で始まってという中で、初めての大きな制度変更のような気がいたします。ただ、私は１つ、これは先に確認をしたかったのですけれども、品川区においてはネウボラネットワークという新たな仕組みをつくって、子ども育成課でネットワークとかを組んでいくということです。","respondent":"伊崎子ども育成課長","answer":"委員ご指摘のとおり、これまでも母子保健、子育て支援、保育、教育その他、品川区ではさまざま力を入れて先進的な事業も取り組んでまいりました。","id":"exchange-125"},{"speaker":"渡部委員","kind":"質問・要望","question":"わかりました。これからいろいろ動き出していく中で、平成２８年度には全てがスタートしていきます。先ほども話がありましたけれども、子育てするなら品川区です。本当にそれが実行できるように、しっかり進めていただきたいと思います。そこを出ている子どもたち、いわゆるティーンズ館が始まって中学校の頃お世話になっていた子どもたちが、既に成人をしていきます。何か活用する方法はないでしょうか。","respondent":"伊崎子ども育成課長","answer":"そういった中で、今ご指摘いただきました、自分たちが経験してきたものを次に活かしていこうという気持ちを持っている方たちも含めまして、地域の方の力をどのように活用していくかということも１つの課題と考えておりますので。","id":"exchange-126"},{"speaker":"渡部委員","kind":"質問・要望","question":"最後に１点だけ質問します。ずっとやり続けていましたプレーパーク、いよいよ平成２９年度に開設ですか、間違っていたかな、どっちでもいいのですけれども、場所が重要で、区民公園で開設をします。区民公園の人の集まりを考えますと、土曜日、日曜日は必須だと思いますので、ぜひ委託をかけるときに、日曜日にやってもらうことを前提にお願いしたいのですが、いかがでしょうか。","respondent":"伊崎子ども育成課長","answer":"しながわ区民公園内のプレーパークにつきましては、平成２９年度にオープンを考えておりますので、平成２８年度に運営事業者の決定も含めてさまざま検討していきたいと考えております。","id":"exchange-127"},{"speaker":"大倉委員","kind":"確認","question":"２２３ページ、高齢者外出習慣化事業の中から、「身近なお店」について、事業の説明を教えてください。このアプリですが、２２５万６,０００円の運用費、これは年間なのか、確認させてください。子育て応援コラムの費用については今回１回限りの計上なのでしょうか。数年に１度、こうしたコラムの更新ができるのか、変更がシステム的にできるようになっているのか、教えてください。","respondent":"松山高齢者地域支援課長、伊崎子ども育成課長","answer":"こちらは、引きこもりがちな高齢者に対しまして、食事を提供し、外出習慣化を促す、そして、終了後も高齢者地域支援課あるいは区のほかの介護予防事業に参加していただいて、健康を保つことを目的とした事業です。こちらに載せておりますアプリの経費ですが、この中に、運営経費のほかに、来年度必要に応じて更新をする経費を７０万円含めておりますので。","id":"exchange-128"},{"speaker":"大倉委員","kind":"質問・要望","question":"健康を保つため、また、今後、終了後もこうした取組みに参加していただくためというところで、今現在、この「身近なお店」については、先ほどもしかしたら数を伺ったかもしれませんが、定数はどのぐらいで、定員というのですか、何人で、応募がどのくらいあったのかというところと、今現在行われている中で区はどういった評価をされているのか、また、参加者からの声とかがあれば、どんなものがあったのか。","respondent":"松山高齢者地域支援課長、伊崎子ども育成課長","answer":"１点目、定員ですけれども、前期、後期２４名ずつということで、毎月１回、全６回を１期としております。合計４８人の方に参加していただきました。応募人数ですけれども、１回目は４４人、２回目は３７人の応募がございました。このアプリの検討にあたりまして連携をとっている課ですが、情報という意味合いでは保育課、子ども家庭支援課、あと、保健予防課、保健センターと健康課など、子どもの健康と子育て支援にかかわるところとの連携をとっておりまして。","id":"exchange-129"},{"speaker":"大倉委員","kind":"質問・要望","question":"「身近なお店」について伺いますが、満足している人がかなりいるというところで、今後のこの事業の展開について教えていただきたいのですが、今、応募が定員数をかなり超えているという部分では、こういったものを例えば今は１店舗でやっているところですが２店舗に増やしていくとか、今後の考え方を教えていただきたいのと、また、商店街連合会にいろいろご協力いただいているというところですが。","respondent":"松山高齢者地域支援課長、伊崎子ども育成課長","answer":"終了後にほかの事業につながりやすいというのは、こちらとしては施設であれば、施設内のいろいろな事業を紹介できるというメリットがありますので、来年度につきましては「身近なお店」１店舗を継続させていただきまして。最終的にこのアプリで全てを解決しようということは考えておりませんので、このアプリをきっかけにしてさまざまなところとつながっていただくような仕組みをつくっておりますので、個別対応ということは考えておりません。","id":"exchange-130"},{"speaker":"大倉委員","kind":"意見","question":"最後に、子育て支援情報発信アプリですが、これはほかのところの取組みも見ましたら、お父さんとかと情報を共有する、夫婦でアプリをとってもらって、お父さんもそのアプリの中で子育てについて、奥さんの状況について、妊婦の状況について、子どもの状況について把握をすることで、こうやって子どもたち、お母さんとか苦労しているのだなということがわかって。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問","question":"２３５ページ、北品川つばさの家運営費について、それから、２４７ページ、保育園運営費で、特別支援保育なのですが、項目がこの中のどこになるのかわからないので、それについて。先に、北品川つばさの家運営費についてです。こちらの運営にかかわる指定管理者制度について、お伺いいたします。それの設置目的上、根幹にかかわる業務と考えますが、区のご見解をお伺いします。","respondent":"中山障害者福祉課長","answer":"これから障害者の方も重度化してまいりますので、そのことを考えたときにはやはり世話人業務という仕事自体の中身も重くなってくることが１点、それから、東京都から口頭で指摘を受けたということをあわせまして、品川総合福祉センターと、「ぴゅあ・さぽーと」といいますか。","id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そこで、指定管理者制度におけるこういった部分、私は根幹の部分だと思っているのですが、この制度設計に対しては反するものではないかということで、つばさの家ということではなくて、指定管理者制度全体という意味で、このような再委託について、担当セクション、企画の課長のご見解はいかがでしょうか。","respondent":"柏原企画調整課長","answer":"そういったところを、実際に法人が運営していく中でのきちんとしたルールづくりといいますか、きちんとした進め方ができるようにということで、それを見える化するのも、我々、区の指定管理者を担当するセクションとしては必要な部分だろうということでありまして。","id":"exchange-133"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"決して指定管理者制度を否定するものではなく、民間のノウハウを活かして、そして最小のコストによって最大の区民サービス提供ということを目指していただきたいのですが、今、課長からお話がありましたけれども、そういった状況で見える化を進めていくということなのですが、このような形で区のさまざまな施設で指定管理制度、さまざま採用しております。","respondent":"柏原企画調整課長","answer":"今回、北品川の部分については、そういった口頭のやりとりがあったとは聞いてあります。その他施設につきましては、そういったことはないと認識しています。","id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"質問","question":"ちょっと古くなりますが、埼玉県の公営のプールで再委託をしたということで、泳いでいる方が亡くなったという事件もあります。それから、旗の台の心身障害者福祉会館もあります。今後、品川区は、このような伝統があり、そして福祉事業の重要な担い手であった老舗法人をどのような形で活用し、そして今後の状況をどのようにお考えでしょうか。社会福祉法人の今後について、大変心配であります。","respondent":"中山障害者福祉課長","answer":"今回、児童学園については、プロポーザルの結果、別の法人にはなりましたが、でも、今までと同様、この２法人、そして新しく誕生した社会福祉法人げんき、それぞれあわせていいところを伸ばしながら、刺激しあって、障害者の施策がより前に進むように。","id":"exchange-135"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これら伝統のある区内の、老舗法人という言い方が適切かどうか、あれですけれども、今後に期待します。区として一体となってこの福祉事業に貢献していただくように、協力、そして指導をしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"若林委員","kind":"質問・要望","question":"このまますっきり帰れない答弁でございましたので、特に前の歩道等、危険性をこんの委員が指摘をされて、それに対して、例えば４,８００万円余のうち、どういうお金を使ってどのような整備を行うのか、ここら辺について、予算審議ですので、しっかりとしたお話、説明をまずは１点、伺いたいと思います。続いて、２２７ページの障害者福祉費、社会参加への支援、福祉タクシーについて伺いたいと思います。","respondent":"竹田保育課長、永尾高齢者福祉課長、中山障害者福祉課長","answer":"ご指摘いただきました歩道については、課題として考えております。入院時の紙おむつにつきましては、金額といたしましては、予算でいきますと、平成２７年度が５,４６０万円で。こちらは、３台の委託をしていたところを、実績見合いで１台に変更したものです。人材の話ですけれども、通所の無資格の人材不足の件ですけれども、倒産になった数字については区としては持ち合わせていません。","id":"exchange-137"},{"speaker":"若林委員","kind":"質問","question":"入院時の助成のほうは、社会福祉協議会から見ると受託事業として行っていると。ここが大きな違い。それから、福祉タクシーのほうは、年齢別は把握されていないということで、今後これは把握すべき１つのテーマかなと思いますけれども、例えば福祉タクシー利用券については、下肢とか体幹機能障害が３級以上であるとか、さまざま障害の認定、級によって対象者が決まっております。","respondent":"永尾高齢者福祉課長、中山障害者福祉課長","answer":"それで、無資格者のサービスの中でも、やはり将来的には実務者研修等を受けて、質の担保を図るための支援等も行っていかなければならないし、また、資格のない方でも。そういった中で、今後は実際の年齢別のところは把握していければと思っています。こうした方々が６５歳になって介護認定を受けたときにどのような状態かということなのですが、非常に難しいところです。","id":"exchange-138"},{"speaker":"若林委員","kind":"質問","question":"在宅の方と入院の方、いわゆる対象者が違うということにもう１点、スポットを当てますと、例えば在宅で要介護度３から５の方、そして所得制限がないというのが現状です。そして、入院後、応急措置を終えてまた在宅に戻ると、またそこで段差ができるという、大変にシームレスでない制度かなと思いますので、ここら辺のシームレスな介護のあり方について、１点お聞きをしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"お一人の方がいろいろ状況が変わって、入院されたり在宅に戻ったりされることも多いかと思います。そういうことも考えまして、同じ社会福祉協議会で事業を実施することによって個別の対応がきちんとできると考えているところです。","id":"exchange-139"},{"speaker":"若林委員","kind":"質問・要望","question":"今後、またさまざま見直しをかけるですが、今のシームレスという考え方は見方として大きいかなと思いますので、ぜひご検討の１つに加えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-140"},{"speaker":"鈴木（真）委員","kind":"質問","question":"高齢者多世代交流支援施設、これまでのシルバーセンターとは違う形の交流をつくっていく、この形、どのようなことを目標にしているのかを１点教えてください。それから、高齢者相談員のところです。ひとり暮らしの方の訪問をしている中で、今、品川区として、ひとり暮らしの世帯の数はどのぐらいと考え、そのうちどのぐらいの世帯に訪問している状況なのか、その点を教えてください。","respondent":"松山高齢者地域支援課長、大串福祉計画課長","answer":"それに加えて、高齢者多世代交流支援施設では、高齢者と多世代の区民との交流を促進する、それをもってして高齢者の福祉の増進を図るものです。大体お一人１０人から２０人ぐらいを担当されているというのが現状ですので、約２８０人ほどいらっしゃいますので、それ掛ける１０で、２,８００人から３,０００人程度が。","id":"exchange-141"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それと同時に、この施設の管理はどこがしていくのか。そこら辺について教えていただきたいと思います。これから高齢者の一人世帯がまだまだ増えていく中で、この事業をこれからどのように展開していくのか、高齢者相談員になることが非常に重要な問題だと思うのですが、お一人１０件ぐらいというお話がありましたけれども、これからの人数を考えたときに、展開を教えていただきたいと思います。","respondent":"松山高齢者地域支援課長、大串福祉計画課長","answer":"高齢者多世代交流支援施設ですが、これまでのシルバーセンター登録団体の調整の仕方ですけれども、まずは今年度、説明会を設けまして、この利用につきまして。ではどうすればといったところですけれども、例えば支え愛・ほっとステーションを順次開設していく中での地域支援員の確保、あるいは町会や自治会の皆様にお願いしております見守り活動ですとか。","id":"exchange-142"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"あれは結構いい形でできていると思いますので、ぜひそのような形と、それから高齢者の方との調整をうまく図っていただきたい。これをお願いします。障害者の関係で品川児童学園についてお聞きします。品川から新しい福祉のカタチをつくる。こちらの法人、それこそ訪問していくのが主だというお話も伺っていますが、その辺の意識と連携をどのようにとっていくのか、その辺を教えてください。","respondent":"中山障害者福祉課長","answer":"できるだけ今お勤めいただいている職員にも残っていただき、新法人の理念とかも説明する中で、平成２９年度からそちらの法人に移行ができるかどうか、それから、事業の療育の中身についても、まずは特に発達相談のところは八潮の「こみゅにてぃぷらざ」で行うような。","id":"exchange-143"},{"speaker":"鈴木（真）委員","kind":"意見","question":"児童の方、また、親御さんについても途切れない関係を保っていくことが大事だと思いますので、その辺をお願いしたいのと、それから、せっかくグローが品川に入ってくるこのパワーをほかの法人にもうまく連携をとっていってもらいたいなとお願いして、終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-144"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私からは、虐待相談についてと、ページが出てこなかったのであれですが、高齢者の運転免許について、それと、２３７ページの臨時福祉給付金についてお伺いをします。２３７ページの臨時福祉給付金については、まず予算書には人数等は書いてあるのですが、対象者、いわゆる支給要件について教えていただきたいのと、その中にシステム保守と改修が入っているのですが、どのようなシステム改修をされるのか。","respondent":"伊崎子ども育成課長、永尾高齢者福祉課長、中山障害者福祉課長、田口交通安全担当課長、大串福祉計画課長","answer":"虐待相談ということで、児童虐待に関しましては、啓発といたしましては。それとまた、事業所連絡会が頻繁に行われておりますので、そういう事件があったときにはすぐに防止の対応について周知しています。障害者の施設における障害者虐待防止の施設でのＰＲですが、それぞれの施設では研修を実施したり、あるいは第三者評価委員という制度がありますので。高齢者の免許証の自主返納制度で、以前はそういった事業を行っていたと聞いておりますが、一定の効果が出たので打ち切ったと聞いてあります。","id":"exchange-145"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"今回、４,５００万円をかけてまた改修をするという中で、平成２７年度をベースにシステムを使うのに、なぜ４,５００万円、これは国の事業ですから区としてどうこう言うあれではないと思うのですが、今、私、システムを考えると、対象者が変わってもそれはそれなりにソートをかけてやっていくようなシステム構築をしっかりしていけば、たとえ国がどういった対象人数にしたとしても何とかなるのかなと。","respondent":"伊崎子ども育成課長、永尾高齢者福祉課長、田口交通安全担当課長、大串福祉計画課長","answer":"児童関係につきましては、児童センターについては同じ所管ですので、義務化というよりも本課からの指示ということで全て張っておりますし、あと。区立施設を中心に、見守りホットラインのチラシやポスターの掲示に努めていきたいと考えています。自主返納に向けた事業の関係ですが、確かに高齢ドライバーの事故が多いというのも現状ですので、今後の検討課題とさせていただきたいと思います。システム改修の件ですけれども、やはりどうしても対象の方が異なってきているといったところで。","id":"exchange-146"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、４２３ページの国保と、それから５１１ページからの介護保険について伺いたいと思います。保険料引き下げに活用できるにもかかわらず、引き下げには使わず、国の一般財源を減らすことに使ったことが明らかになりましたけれども、これが国、都、区の分で合計３億７,６５５万円ということですが、これで全額かということを改めて確認させていただきたいと思います。それが１点です。改めて確認をします。","respondent":"高森国保医療年金課長","answer":"ただ、高額療養費につきましては、まず前提として１３億円かというご質問ですが、保険料自体の算定におきまして、２３区の統一保険料方式をとっておりまして、この中で前期高齢者交付金等々が動いたりなんかすると微妙にずれてくるということで。","id":"exchange-147"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからもう１つお聞きしたいのが、代表質問でも伺ったのですが、東京都の調整交付金について、東京都からは９％の交付金という仕組みですが、その１つに収納率向上に関わる取組成績別交付算定表というものがあって、収納率を上げるほど、また、差押え件数が高いほど交付金が出る仕組みになっています。東京都全体でここに使っているのが約４０億円と聞きました。","respondent":"高森国保医療年金課長","answer":"収納率向上にかかわる取組成績別の交付算定表についてのご質問ですが、実は平成２６年度については平成２７年度に支給されるということで、現在まだ、私どもは資料は出してあるのですけれども、決定通知をいただいていない状況でございまして、１年遅れでお金が来るということで。","id":"exchange-148"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"わかりました。これは東京都の仕組みですから、東京都にもぜひこの仕組みをやめるように言っていただきたいと思っていますけれども、そして、滞納者への差押えなのですけれども、徴収法の第７６条では差押え禁止財産として１人１２万円を定めています。私は、滞納者が著しく困窮に陥るような場合は差押えをすべきではないと思いますが、いかがでしょうか。","respondent":"高森国保医療年金課長","answer":"それぞれの状況に見合った形で、個々に、やはり福祉の視点でもって対応していきたいと考えています。","id":"exchange-149"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国がこれだけ、国会の答弁でもこういう答弁をしているわけですから、ぜひこれに基づいてやっていただきたいということを強く求めておきます。そしてもう１つは、子どもの保険証についてなのですが、親が滞納について分納計画を出さないと子どもの保険証を出さないという対応がありました。昨年４定で部長は通知にのっとってやっていきたいという答弁をされましたけれども、その後、改善されたのか、伺います。","respondent":"高森国保医療年金課長","answer":"子どもの保険証につきましては、おいでいただければ、窓口に一時的に留め置きするという形になりますけれども、その後、滞納がなければ子どもの保険証は現在送るようにしています。それと、短期証の発行件数ですが、平成２７年１０月現在の短期証の発行数は１,８４０件です。","id":"exchange-150"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成２７年に基金を取り崩した額と、平成２８年度に取り崩す予定の額を教えていただきたいと思います。そして、平成２８年度末の基金残高、これは見込みですけれども、その評価についてもお聞きしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"平成２７年度に取り崩した金額が５,３１１万６,０００円です。平成２８年度に取り崩す予定の額は６,４８５万７,０００円です。それと、基金残高の評価についてですけれども、保険料というのは、３年間の給付費の見込みで保険料を決めておりまして、それが固定されております。","id":"exchange-151"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区の介護財政はゆとりがあるのだと、ここの基金にもあらわれていると私は思います。今回、総合事業で区独自の単価を介護報酬よりも大きく引き下げましたけれども、この引き下げた金額をぜひ介護報酬並みに引き上げていただくことを求めて、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-152"},{"speaker":"たけうち委員","kind":"質問","question":"その辺の普及されている状況。ただ、支給の要件の中に平成２７年度の住民税が非課税の方というものがあるのですが、去年の臨時給付金のときには、６月中旬以降にならないと住民税の確定にならないので、６月中旬以降に申請書がいきますよとなっていたのですけれども、今回は随分早くて、早い分にはいいのですけれども、その辺のところが大丈夫なのかなというところを教えてください。","respondent":"永尾高齢者福祉課長、中山障害者福祉課長、大串福祉計画課長","answer":"平成２８年度予算で介護福祉専門学校修学資金貸付金の想定している人数ですけれども、前期が６２人、後期が５８人分です。個別にお問い合わせがあって、ほしいという方には郵送でも送らせていただいております。低所得の高齢者向けということで、委員ご指摘のとおり、昨年までは６月の税の確定後になっていましたけれども、今回は先ほどご紹介ありましたが。","id":"exchange-153"},{"speaker":"たけうち委員","kind":"質問","question":"ちょうど３月５日の東京新聞の夕刊で、ヘルプカードではないのですけれども、ヘルプマークについて、東京都でつくったものを、今、東京オリンピック・パラリンピックも踏まえて、障害者の方の理解を進めるために活用していこうということで、全国に呼びかけて、幾つかの自治体で新たに採用されるところもあるみたいなのですが、実際には都営地下鉄ですとか都営バスで配布をしたりしているものですから。","respondent":"永尾高齢者福祉課長、中山障害者福祉課長、大串福祉計画課長","answer":"品川介護福祉専門学校の修学資金の件と国の制度についてですけれども、区で実施しているのが３年間、品川区内の施設に就労したら免除という条件で。ご相談の中で、なかなか周りからわかりにくい障害のご相談があったときには、ヘルプマークをご紹介しながら配布に努めてまいります。秋以降、９月以降を予定しておりますけれども、低所得の障害・遺族基礎年金受給者向け。","id":"exchange-154"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました。臨時福祉給付金は、我々がこれを見てもなかなかわかりづらいので、しっかりと対象者に行くように、今回、特に前半のほうは３万円ですから、よろしくお願いします。それから、ヘルプマークについても都から来ているということなので、ぜひ積極的にＰＲしていただいて、都のほうもしっかり活用していきたいという意向があるみたいなので、またさらなる周知をよろしくお願いしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"国のほうも要綱が出てきていないので、詳細がまだわからないところもありますので、要綱が出てきた段階で、どういうふうに使えるかどうかということを考えていきたいと考えています。","id":"exchange-155"},{"speaker":"松澤委員","kind":"質問","question":"２２３ページ、１項社会福祉費、２目高齢福祉費、仮称ふれあいステーション事業、８地区、７,４８６万２,０００円。それと、同じページで高齢者見守り事業、地域見守りネットワーク事業。２２１ページ、大井三丁目高齢者憩いの場整備について。２２３ページ、家具転倒防止対策助成について、お伺いをしたいと思います。仮称ふれあいステーション事業、８地区、７,４８６万２,０００円。","respondent":"大串福祉計画課長","answer":"いわゆる公的なサービス、公的な領域というのは、介護保険事業であるとか、あるいは先ほどご質問ありましたけれども、民生委員が見守っているとか、そういった形で誰かが関与している、そういった方以外の方に対してもこのステーション。","id":"exchange-156"},{"speaker":"松澤委員","kind":"質問","question":"この費用には、コーディネーター、社会福祉士と、サブコーディネーターの２人が常駐するということと、支援員と書いてあるのですが、この支援員というのはどういうことなのでしょうか。まだ人がいるということなのでしょうか。その点をお聞きしたいと思います。","respondent":"大串福祉計画課長","answer":"地域支援員と言っておりますけれども、基本的にはこれはボランティアになります。","id":"exchange-157"},{"speaker":"松澤委員","kind":"質問","question":"これは相談が２００件、１年間ですからね。月火水木金掛ける２０掛ける１２。これから祭日を引くと、２人常駐して、支援員がいて、相談が１日１件ですよ。訪問は１６７件から２６０件、これも１日１件。支援員もいるということですから、そうしますと、これだけの人数を使って、実際には１日１件ぐらいしか相談が来ない中で、どういう事業をこれから展開していくのか。その辺の決意をお聞きしたいと思います。","respondent":"大串福祉計画課長","answer":"今言っていただいた実績については、そういった相談、訪問という数ですけれども、それ以外にも日々さまざまな形で、掘り起こしという形で、アウトリーチといった活動もやっているというところ、そうした中で地域のボランティア、支援員についても発掘といいますか。","id":"exchange-158"},{"speaker":"松澤委員","kind":"質問","question":"今お話を伺いましたので、それぞれまだまだやっているということですから、それはそれとして、今後の展開、これは大事なことなのでいいと思うのですが、相談する方が１日１件ぐらい来ているという、この方たちはどういうところでこの情報を得て、来ているのでしょうか。公的な支援ではなくてということで、広報を見て来るのか、その辺のことをお聞きしたいと思います。","respondent":"大串福祉計画課長","answer":"この事業、ステーションを各地域センターの中に置かせていただいております。それが一番大きなポイントと考えておりまして、その地域の中での回覧板ですとか、あるいは掲示板にチラシ等々を張らせていただいて周知に努めている。","id":"exchange-159"},{"speaker":"松澤委員","kind":"質問","question":"実はこういうふうに相談に来る方というのは１日１件ですけれども、来たときに寄る、そうすると、大体が町会に入っていない、高齢者クラブに入っていない方かなと思うのです。そういうところに、こういうのに入りなさいよとか、高齢者クラブいいですよ、町会も入ってくださいよということをしているのでしょうか。この点をお聞きしたいと思います。","respondent":"大串福祉計画課長","answer":"ご相談、あるいはコーディネーターが訪問する中で、町会加入あるいは高齢者クラブへの加入の推薦までは特にしていない状況です。","id":"exchange-160"},{"speaker":"松澤委員","kind":"質問","question":"わかりました。この中で、地域社会から孤立しがちな高齢者の生活不安を住民同士が支え合う共助の充実とうたわれているのですけれども、「町会・自治会が主体となって」となっているのです。これは何で高齢者クラブがその主体者にかかわらないのでしょうか。この辺をお聞きしたいと思います。","respondent":"大串福祉計画課長","answer":"こちらの地域見守りは、あくまでも町会・自治会での見守り活動の中で、町会・自治会の中にいらっしゃる方を見守っていただくというところで事業展開をさせていただいているところでございまして。","id":"exchange-161","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"質問","question":"私は、やはりこれ、高齢者クラブも関与できる形にしたほうがいいと思うのです。今、高齢者クラブで一生懸命やっているのが８３運動。子どもたちの通学路を見ながら一生懸命やっている。こういう事業があって、これに参画できない。そういう中で、やはり高齢者クラブがこういうのに参画できる道を開いていかなかったらいけないと思うのですが、その辺をお聞きしたい。","respondent":"松山高齢者地域支援課長","answer":"委員ご指摘のとおり、高齢者クラブなのですけれども、昨年度、事業の見直しを行いまして、友愛活動部を発足しております。会長はじめ、友愛活動、いわゆるボランティア、見守り活動に今年は力を入れていこうということで、全力で努めているところです。","id":"exchange-162"},{"speaker":"松澤委員","kind":"質問","question":"今の答弁でとどめておきたいと思います。３つ目、大井三丁目高齢者憩いの場整備について。これは寄附して、これを直してということなのですけれども、この経緯を伺いたいというのと、あの建物は、見た感じ、まだ使えると思ったのです。表が駐車場、３台、４台ぐらい入るのかな。今までのあれを使ったってできたのではないかと思うのですが、その辺をお聞きしたいと思います。","respondent":"松山高齢者地域支援課長","answer":"こちらは区民の方より土地・建物を区にご寄附をいただいたという経緯があります。確かに委員おっしゃるとおり、非常に雰囲気のある建物でして、区としても残したい思いはあったのですけれども、耐震補強ができないということで、１度解体という形になりました。","id":"exchange-163"},{"speaker":"松澤委員","kind":"質問・要望","question":"わかりました。そんな意味では、地域の方たちが使えるような施設、高齢者が本当に集えるような施設をつくっていただきたいと思います。４点目、２２３ページ、家具転倒防止対策助成について、今年度、どれぐらい助成についての申請があったのか、お聞きしたいと思います。","respondent":"松山高齢者地域支援課長","answer":"今年度の家具転倒防止の実績ですが、今年度につきましては３４件の申請件数がございました。","id":"exchange-164"},{"speaker":"松澤委員","kind":"質問","question":"家具転倒防止策は、自助で一番大事なことなのです。地震が起きたときに、昔は地震だ、火を消せと言ったのです。今は違うのです。区長の英断で、所得制限なしで高齢者の世帯に広げていただいたのですけれども、これはもっと利用されなくてはいけないと思っているのですけれども、これの広報活動をどのようにしているのか、その辺をお聞きしたいと思います。","respondent":"松山高齢者地域支援課長","answer":"家具転倒防止策の周知です。広報をはじめ、民生委員協議会での周知があります。は防災の所管課と連携しまして、何か祭りとかがありました場合、そちらにチラシを置かせていただくような形をとっております。","id":"exchange-165"},{"speaker":"松澤委員","kind":"意見","question":"時間がないですけれども、地域で地区ごとに防災訓練をやっていますよね。やはりそれに絶対置くべきだと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-166"},{"speaker":"須貝委員","kind":"質問","question":"私は、２３８ページ、児童福祉費の中の待機児について、２１９ページ、高齢福祉費の介護について、お聞きしたいと思います。は先ほどもお話が出ました。国会で取り上げられた「保育園落ちた。年収で２４０万円、なかなかそれから上がっていかないところが多く、保育士の定着率が悪いようですが、これらについて、どう思いますか。そして、これは区の重要課題の１つですか。お答えください。","respondent":"今井待機児童対策担当課長、竹田保育課長","answer":"今後、このようなものを含めて、さらに新規保育園の開設等を行ってまいりたいと考えています。保育士が働き続けるものの一番大きなモチベーションの１つとして、賃金があろうかと思います。今年度より、キャリアアップ補助事業を開始しまして、賃金の改善等を通して、保育士の確保、定着に努めているところです。","id":"exchange-167"},{"speaker":"須貝委員","kind":"質問","question":"品川区にまず人口が流入することが一番問題だと思います。何でここだけこうやって来るのか、これだけ毎年枠を増やしてもまたいっぱいになってしまう。ここでお聞きしたいのですが、子どもすこやか医療費助成事業は、０歳児から中学３年生まで医療費が無料だと思ったのですが、先ほどお話しした無認可の保育料はなぜ認可、認証、小規模と同様に助成されないのか。このバランスをお聞かせください。","respondent":"竹田保育課長","answer":"認可外保育施設の件です。あくまでも認可外保育施設等は認可保育所を補完するものと考えております。認可外保育施設の中にはさまざまな形態や目的の施設があり、現時点では認証保育所のような保護者への補助金などのような一律の助成は難しいと考えております。","id":"exchange-168"},{"speaker":"須貝委員","kind":"質問","question":"入れなかったわけではないですか。その中で、民間の介護付き有料老人ホームがあり、どんどんできていますが、自己負担が月に３０万円から４０万円。職員の方にもいらっしゃったと思うのですが、いわゆる介護離職者ですが、やめると収入は０円です。週３日ぐらいの深夜勤務で、入居者から罵声を浴びせられたり、肉体的な攻撃を受けたりする中、交代するヘルパー不足により、超過勤務を要請されています。","respondent":"永尾高齢者福祉課長","answer":"これから高齢者の方がどんどん増えていきますので、今までと同じやり方をしていては当然間に合わないのかなと実感しております。そういう意味で、区としても重点課題だと捉えているところです。","id":"exchange-169"},{"speaker":"須貝委員","kind":"意見","question":"それで、細かい点で恐縮なのですが、要介護度改善ケア奨励助成がありますよね。ケアを改善するには、１人のヘルパーがつきっきりにならないと、私は無理だと思うのです。１人で例えば３人見ている一般的なヘルパーではなかなか対応できない。果たしてこれがいいのかどうか。それだったら、多くの方を１人のヘルパーで見ていただけるような方向のほうがいいのかなと。個室で、中には浴室があります。いるだけ。","respondent":"永尾高齢者福祉課長","answer":"それで、要介護度改善ケアで改善をした方について、１人の人がつきっきりというお話ですけれども、最初に改善を始めるときは当然そういうふうに手をかけるようになるのですが、一定程度手をかけると、今度はご自身から何かをしたいという気持ちが湧いてきますので。","id":"exchange-170"},{"speaker":"須貝委員","kind":"質問","question":"財政課にお聞きしたいと思います。本当に緊急に対応しなければいけない。それが、何でそれは後回しにするのですか。ですから、介護でも、待機児、保育の問題でも、重要課題として区が取り上げる。だったら、文化スポーツ振興基金を出す、これは後でもいいのではないですか。やめろとは言わないけれども、先に持ってくるほう、基金を積み上げるほうが違うのではないですか。ご返答をお願いします。","respondent":"秋山財政課長","answer":"もちろん待機児童、介護含めて、重要な問題であるとの認識は当然持っております。それにあわせて、区としましても、介護であるか待機児童であるかというところに毎年資金を入れて政策を進めているわけです。","id":"exchange-171"},{"speaker":"須貝委員","kind":"質問","question":"基金というのは区のこれからの施策をあらわすものだというお話を前にお聞きしました。だったら、今、大都市問題で一番重要な、２つあれば、２つですよね、やはり重要課題というのは、先々見据えて、やはりしっかりやるために区として看板を掲げるのが私は筋ではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-172"},{"speaker":"あべ委員","kind":"確認","question":"ニーズがないということよりも、何かほかにも改善すべき点があるのではないかと思いますが、区のご見解をお伺いします。それから、昨年秋から医療的なケアが必要な未就学の子どもに対する訪問保育の制度をつくっていただきまして、これがこの項目でよかったのか確認も含めてなのですけれども、利用の実績についてお伺いできればと思います。","respondent":"永尾高齢者福祉課長、中山障害者福祉課長、竹田保育課長","answer":"認知症カフェは８カ所できておりますけれども、カフェそれぞれが工夫の中でやっているところですので、そのカフェが今度は１つになって情報交換をし。移動支援の研修なども行ってはいるのですけれども、事業所の中で移動支援に取り組める事業者。障害をお持ちの方の件ですが、私どもとしましては居宅訪問型事業あるいは医療的ケアの必要な障害児の方には保育料助成等のメニューをご用意しまして。","id":"exchange-173"},{"speaker":"あべ委員","kind":"質問・要望","question":"認知症カフェのほう、よろしくお願いいたします。それで、移動支援なのですけれども、今お話があったように、やはり支える側の人材の数がまだまだ不足しているとは私も利用者側からも伺っております。毎日ということでなくても、集団の中での育ちができるような機会をぜひ考えていただきたいと思うのですが、それについてもお考えをお聞かせください。","respondent":"中山障害者福祉課長、竹田保育課長","answer":"ここは、今までの仕組みだけでは多分解決できない課題であるかなと考えておりますので、地域の中の支えあいみたいなものも視野に入れながら、どうした方向があるかは、これから課題として考えてまいります。平成２８年度についても継続する事業です。集団保育についてですが、お子さんにとってプラスになるということを踏まえつつ、考えていきたいと考えています。","id":"exchange-174"},{"speaker":"あべ委員","kind":"質問・要望","question":"次の質問に移りたいと思います。今、保育士が足りないという中で、やはり保育の学校というのもぜひ考えていただきたいなと考えています。それから、今、民間の保育園では、運営費を事業拡大のために充てることが認められていると聞いておりますけれども、公設民営でもその運営費がほかの開設資金に充てることが可能なのかどうか、確認したいと思います。","respondent":"竹田保育課長、今井待機児童対策担当課長","answer":"保育士の奨学金の件ですが、こちらについては今後研究させていただきたいと考えております。離職率はやはりどの法人、民間事業者もそうですけれども、数年前よりは改善しているということで、１０％台というのは確認しておりますけれども、詳細については、申しわけありません、今、ございません。","id":"exchange-175"},{"speaker":"あべ委員","kind":"質問","question":"保育園に関連して、今回、一次に入れなかったお子さんが大勢いらっしゃったわけですけれども、その中で、３、４、５歳児でも不承諾というお子さんがいらっしゃいました。そういった方々なのですけれども、転園希望で入れなかったのか、それともどこにも入れない３歳以上のお子さんもいるのかどうかということを教えてください。","respondent":"今井待機児童対策担当課長","answer":"３歳以上につきましては、現在、一定、利用不可ということで通知した方もいらっしゃいますけれども、実は認可保育園の内定辞退で私立幼稚園を選ばれるという辞退届もいただいている状況ですので、一次、二次、そして区内、区外の認証も含めまして、今後。","id":"exchange-176"},{"speaker":"あべ委員","kind":"質問・要望","question":"今、３歳以上の保育の枠はかなり厳しいところまでやってきていると思うので、ぜひそこのバランスを考えながら、定員等々も配慮して、今後もやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-177"},{"speaker":"南委員","kind":"質問・要望","question":"２３９ページの児童相談事業について伺います。幾つかの事業があるのですけれども、相談事業、児童相談員活動経費、そして、要保護児童対策地域協議会。とりわけ地域協議会のほうの会議の回数と、どのような内容が議論されているのか、まずそれを教えていただきたいと思います。","respondent":"伊崎子ども育成課長","answer":"この下にありますケース会議につきましては、その年によってケースの状況によって異なってくるところでございまして、ちなみに平成２６年度におきましては３４回実施をしておりまして、平成２７年度におきましては、今のところ、２１回です。","id":"exchange-178"},{"speaker":"南委員","kind":"質問","question":"今、子どもの貧困率が１６.１％という状況になっていて、格差と貧困が広がっている、そういうところに子どもが置かれているという実態は社会問題で、本当に心が痛む問題です。マスコミでもさまざまな番組が取り組まれて、実態が告発されています。そして、こういう子どもの貧困と子ども食堂の広がりが起きている現状について、品川区の見解、認識を教えてください。","respondent":"廣田子ども家庭支援課長","answer":"子ども食堂につきましては、国の子どもの貧困対策で考えられている子供の未来応援基金のほうで食事の提供等、ＮＰＯ等の活動についての支援をするという構想が含まれているやに聞いておりますけれども、まだ今後どうなるか、はっきりはしていない状況だと思われますので。","id":"exchange-179"},{"speaker":"南委員","kind":"質問","question":"そういうふうに反応が非常に高くてうれしいと。行政として、何かしらの支援が必要だと私は思うのですけれども、こういう状況について、区としてどういうふうに見ているのか、あるいは善意のある人のいい活動と傍観していていいのかと思うわけで、その辺について区はどういうふうに考えているか、改めて区内に具体的にそういう実態があることを紹介した上で、どういうふうに思うか、教えてください。","respondent":"廣田子ども家庭支援課長","answer":"２３区におきましても子ども食堂について把握していますかというような調査等もございましたけれども、各区でさまざまで、子ども食堂の活動自体は貴重な地域活動というところで皆認めているところですけれども、今後、行政とどう絡んでいくかにつきましては検討課題ということで。","id":"exchange-180"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で、安全、安心で新鮮な食材を手に入れて子どもたちに提供する、そういうところでの一定程度の区の支援をやはり考えていただきたいと思っているのですけれども、そういう点についてはどうでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"区が介入することで、また衛生面でありますとか規制等も考えなければならないようなところも出てきてしまうこともあろうかと思いますので、動向を見守りながら、今後、行政と民間の方とのお付き合いについては考えてまいりたいと考えております。","id":"exchange-181"},{"speaker":"南委員","kind":"質問・要望","question":"それと、４８０ページの後期高齢者医療の問題について、お尋ねしたいと思います。特例軽減が継続されたことになった理由は何かということと、低所得者層への軽減税率が均等割では９割減額あるいは８割５分の減額、あるいは所得割もそれぞれされておりますけれども、低所得者に対してこういう減額措置をしている理由は何なのかということを伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"高齢者の医療制度に加入されている被保険者の方につきましては、低所得者の方が多いということで、そのような措置が継続されたと聞いてあります。","id":"exchange-182"},{"speaker":"南委員","kind":"質問","question":"それと、保険料そのものの引き下げもするべきだと思うのです。高齢者に対しての窓口負担をゼロにする、あるいは医療費を無料化する、そういうふうに考えて、命を守る、支える、そういう立場に自治体としてしっかり立つべきだと思っているのですけれども、その点についての見解も伺います。","respondent":"高森国保医療年金課長","answer":"軽減につきましては、国のほうでは平成２９年度に緩やかな廃止という状況で話はありますけれども、軟着陸という形で、多分その辺のところについては、すっぱり廃止ということではなく、少しずつ、緩やかですけれども、東京都の広域連合を通しまして。","id":"exchange-183"},{"speaker":"南委員","kind":"質問・要望","question":"やはり廃止ではなくて、保険料の負担軽減、窓口の負担もゼロにという、その立場でこれからも頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-184"},{"speaker":"浅野委員","kind":"質問","question":"最初に養護老人ホームの件ですけれども、こちら、人数で１０６人と出ております。この１０６人の意味を教えていただければと思います。過去の決算書を見ると、延べ人数ですか、例えば１,１００人程度の数字が出ておりますが、この関係について教えてください。","respondent":"永尾高齢者福祉課長","answer":"養護老人ホームは、措置によって入所するという施設になっております。介護保険ができたことによって、ほとんどの施設については契約型になっているのですけれども、さまざまな事情がある方について、措置の対応ということで、件数も減っているということになります。","id":"exchange-185"},{"speaker":"浅野委員","kind":"質問","question":"決算のほうも聞いたのですけれども、昔の決算書を見ると、延べ人数で１,１００人程度の数字が出ておりますけれども、こちらの数字と予算のほうの１０６人程度の数字というのはどういう関係になるのかということを教えてください。","respondent":"永尾高齢者福祉課長","answer":"延べ人数でいくと１,１４１人という数字があるかと思います。こちらの予算書に載っている数字は実人数で出しているものです。","id":"exchange-186"},{"speaker":"浅野委員","kind":"質問","question":"延べ人数の意味ですけれども、これは１０６人の方が１２カ月という意味であると答弁していただければ一番よかったと思うのですけれども、そういう数字だということで認識しておきます。措置という形になるので区のほうが決めることになるかと思います。入所するのは、満杯というのでしょうか、難しいとも聞いておりますが、入所できなくて待っている方、その間、どのような対応をされるのか、教えてください。","respondent":"永尾高齢者福祉課長","answer":"それは施設側の問題というよりは、本人の家庭環境の問題とか、今住んでいる家をどうしたらいいかとか、そういう諸処の理由がございましてすぐに動けないということになります。その間については区の在宅支援システムの中できちんと支援をしていっているところです。","id":"exchange-187"},{"speaker":"浅野委員","kind":"質問","question":"よく理解できました。本当にありがとうあります。その中で、今度、区民の方が入所している施設なのですけれども、これは何カ所ぐらいに分散しているのか、また、場所からするとどういう場所にこの施設があるのか、お答えできる範囲で教えてください。","respondent":"永尾高齢者福祉課長","answer":"数について今手元に用意はしていないのですけれども、場所としては多摩地区が多くなっております。全国にそういう施設がありますので、ご利用者の状況にあわせて入所させているところです。","id":"exchange-188"},{"speaker":"浅野委員","kind":"質問","question":"細かいところまでお伺いしましたけれども、やはり今後、家庭の中で高齢者の方にうまく対応できないという状況の中では、措置という形で行われるということで、場所の確保は難しいかと思いますが、適宜対応していただければと思います。人間ドックの助成事業に移ります。ホームページですとか、いろいろな媒体はあるかと思いますが、いかがでしょうか。","respondent":"高森国保医療年金課長","answer":"国保のほうでは、わかりやすい国保という冊子を毎年４月に発行しておりまして、そちらでご案内をしていると同時に、実は国保基本健診の受診券を５月中旬ぐらいに４０歳以上の方を対象にお送りしているわけですけれども。","id":"exchange-189"},{"speaker":"浅野委員","kind":"質問","question":"そういう意味ではやはりホームページでわかりやすくやるというのも、ホームページをそのために見るという方も少ないのかなと思うので、例えば今、品川区のメールマガジンでしょうか、しなメールということで行っておりますが、時々このような形でしなメールでお知らせをするというのも１つの手ではないかなと思いますが、ご見解を教えてください。","respondent":"高森国保医療年金課長","answer":"現在、ホームページ等でもご案内をしているところでございまして、もう一歩踏み込んでというお話かと思いますけれども、少し検討させていただきたいと思います。","id":"exchange-190"},{"speaker":"浅野委員","kind":"質問","question":"ぜひとも検討していただければと思います。このように伺っているわけですが、このようなものが例えばそろわなかったということで助成が受けられなかったというケースは発生しているのかどうかということ、あと、区内の人間ドックに対応している病院を積極的に広報というのでしょうか、お知らせをするようなことは考えているのか、教えてください。","respondent":"高森国保医療年金課長","answer":"人間ドックの８,０００円の助成対象ということで、検査結果をいただくわけですが、こちらは国保基本健診の基本的な検査ということで、いわゆるスタンダードな資料をいただくという形で、人間ドックの助成を満たしている状況です。","id":"exchange-191"},{"speaker":"浅野委員","kind":"質問","question":"最後の質問になりますが、要介護度改善ケア奨励助成ということで１点お伺いします。以前、この質問の答弁として、施設の現場で働いている職員は介護報酬についてあまり理解していないので、周知度をアップさせる取組みを進めるという答弁があったわけですけれども、最近、このように変化は見られるのかどうか、教えてください。","respondent":"永尾高齢者福祉課長","answer":"区では説明会を毎年やっている中で、施設側も一般の介護職員に対して周知を図られており、大分増えてきているところです。","id":"exchange-192"},{"speaker":"渡辺委員","kind":"質問・要望","question":"私は、２５１ページの就学前乳幼児教育事業、「ぷりすくーる」とあわせて伺います。それとあと、２１５ページのボランティアセンターの観点から伺います。これが自治体直接なのかどうなのかというのは正直わからないですが、やはり場の設定、区が積極的に行うべきものと思っているので、方法論はいろいろあると思いますが、見解を伺おうと思います。以上、まずお願いします。","respondent":"竹田保育課長","answer":"場の提供ですが、昨年度、私立保育園と協働で、ハローワークとも連携しながら、場を設けたところですが、参加者が非常に少なかったというところで、今後、新たな方法がないかどうか、検討してまいりたいと考えております。","id":"exchange-193"},{"speaker":"渡辺委員","kind":"質問・要望","question":"これもやはり幼児教育で、現在の窓口があるはあると思うのですが、事業者、運営者の連携と、あとやはり保護者の方から見たときのわかりやすさという点から、これもやはり総合的な一体化をわかりやすく展開するのはどうかというのを質問させていただきたいと思います。ちょうどこの時期なので、聞くところによると、平成２９年度の春が１つの目標という中で、要所のスケジュールがあると思うのです。","respondent":"竹田保育課長","answer":"在園保護者の方にも機を逸することのないように、適切な時期にご説明していきたいと考えております。","id":"exchange-194"},{"speaker":"渡辺委員","kind":"質問","question":"適切な時期のところ、おそらく別に公の話として平成２８年度は難しい、そして平成２９年度４月を目標にしようと。そうすると、いろいろなスケジュール、節目が自然だと思うので、そこだけ教えてください。時期の問題。それと関連して、ボランティアのところを伺います。その中で、主な事業、予算の内訳的なもの、あと、このボランティアセンターの体制のところ、まずこれを教えてください。","respondent":"永尾高齢者福祉課長、金子子ども未来部長","answer":"それで、あとはボランティア保険の助成とボランティア団体助成がそれぞれ５００万円と２１万円という内訳になってあります。体制については後ほど説明いたします。委員ご指摘のとおり、園児募集等々の絡みがありますので、これについては条例化等々、平成２８年度の早い時期がふさわしいのかなということは考えておりますけれども、今後、詰めていきたいと考えております。","id":"exchange-195"},{"speaker":"渡辺委員","kind":"質問","question":"「ぷりすくーる」に関しては、本当に国に先駆けてやった幼保一体型施設というので、関係者含めて誇りに思っている部分、やはり今後も大事な部分だと思ったので、見通しを伺った次第であります。というのは、これは何を伺ったかというと、ボランティアセンターの役割は、災害時のときにも本当に大きな役割だと。そんなことも含めて、総合情報を今後の課題としてどう提供していくか。","respondent":"柏原企画調整課長","answer":"どういった形で持っていくかというのは難しい部分がありますけれども、大きな検討課題として考えさせていただければと思います。","id":"exchange-196"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/257095?Template=document&Id=1042#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":129669,"voices":466}},{"id":"h28-20160308-3","meetingId":"h28-c-budget","date":"2016年3月8日","dateIso":"2016-03-08","committee":"予算特別委員会","time":"午前１０時００分～午後５時５５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を171件抜き出しています。","topics":[{"id":"topic-01","title":"平成２８年度品川区一般会計予算","agenda":"平成２８年度品川区一般会計予算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"事業内容、平成２８年３月に東京都が策定する「環境基本方針」に基づいて、エネルギー需要供給等の情勢の変化、技術革新も踏まえて、平成２８年度から平成２９年度にかけて、現行の環境三計画を改訂するということですけれども、これは今現在、区の方針、そして東京都の方針があると思うのですけれども、この現在の区がお考えになっている改訂内容、わかる範囲でお知らせいただきたいのが１点と、これ。","respondent":"三ツ橋環境課長","answer":"地域推進計画につきましては、こちらも地球温暖化対策の推進に関する法律に基づきまして、品川区全体、地域、区民、区、そして事業者が全体のＣＯ２削減に取り組んでおります。次に、エコラにつきましてです。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今ご説明あったように、この第二次品川区環境計画を拝見すると、同じ内容だと思うのですけれども、この重点プロジェクト、これは２０１３年のものを今拝見しているのですけれども、これ、重点プロジェクト５の中で、共通目標、環境教育・環境コミュニケーションを充実するということなのですけれども、これ、私事で恐縮なのですけれども、私も区内の小学校で、ＰＴＡの家庭教育の中の一環で、海の環境事業。","respondent":"三ツ橋環境課長","answer":"そちらは全小学生を対象に募集しておりまして、夏休みに環境学習をしております。６回ほど開催しております。そのほか関係する部署とも連携しております。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ぜひこれ、２０２０年、東京オリンピック・パラリンピックに向けて、環境保全、そして創出もよろしくお願いいたします。続いて次の質問に移らせていただきます。品川区もったいないプロジェクトについて質問をいたします。改めてプロジェクトの事業内容等お知らせください。","respondent":"三ツ橋環境課長","answer":"具体的に申し上げますと、４つの取組みを考えておりまして、例えば、お店が少なめに対応しているとか、食べ残し削減のＰＲをしているとか、食品販売における対応をしているとか、その他です。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これは初めての実施ということで、旗が岡商店街がまず声を上げて挙手をしたそうですけれども、これ、今現在の実施状況、そして、これをもっと今後、啓発活動、推進店をもっと啓発すべきだと私は思っているのですけれども、ＰＲを含めて、今後、展開はどういうふうにやっていくのでしょうか。教えてください。","respondent":"三ツ橋環境課長","answer":"実際に推進店、モデル店といたしまして、委員ご指摘のございました旗が岡商店街をモデル店として実施して、今、展開しておりますのは、６商店街で展開しております。そして、６商店街の中で、個店も含めますと全部で４４店舗展開しております。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"私からは、２８３ページ、もったいないプロジェクト、そして２６９ページ、胃がんリスク検診、そして３０７ページ、勤労者共済会運営補助についてお伺いいたします。そして、ただいまもありましたけれども、このもったいないプロジェクト、現在、４４店舗加入されているということで、私が確認したとき、３０何店舗でしたので、大きく推進をされたなと考えています。食堂が新しくオープンをいたしました。","respondent":"川島健康課長、三ツ橋環境課長、山崎商業・ものづくり課長","answer":"現行では、バリウムの検査も併用して、年１回、４０歳以上、毎年実施していいというような形にもなってありますので、自治体のほうも体制がとれ次第。今回、１番目の少なめに対応という項目に該当いたしますので、早急に食堂ももったいない推進店として対象に取り組んでまいりたいと考えています。主なものとしましては、中小企業センターにおける日曜コンサートですとか、中小企業センター祭り、中には、勤労者共済会の事業がございまして。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"胃カメラの導入に関しましては、やはりバリウムを飲めない方、また、過去に傷がある方がどうしても毎回このバリウムだと写ってしまう方にとっては、胃カメラの検査も大変有効的かと思いますので、早期の導入を要望させていただきたいと思います。そして、婚活事業のところですが、現在行われている婚活事業の中での、例えば成果とか、どれだけ参加率があるのか、具体的に教えていただきたいと思います。","respondent":"川島健康課長、山崎商業・ものづくり課長、三ツ橋環境課長","answer":"厚生労働省でピロリ菌の抗体検査の研究を開始するというふうにも聞いてありますので、そちらの動向も注視しつつ、今回の検診の位置付けでは。相談会あるいはセミナー、パーティーなど各種やっておりまして、延べの参加人数が、今年度、現時点で４６名。店舗数ですけれども、全体の店舗数が５０店舗になりましたら、啓発冊子を作成していきたいと考えています。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"私からは、２８１ページの環境三計画改訂プロジェクトと、あと、３０１ページ、商店街活性化推進事業全般についてお伺いをいたします。よろしくお願いします。排出量は世界第５位、ワースト５であり、再生可能エネルギーや政策については極めて乏しいと最低水準に位置付けられていました。ところで、品川区は環境三計画改訂プロジェクトを４００万円で計上されていますが、この内容を簡単にご説明ください。","respondent":"三ツ橋環境課長","answer":"三計画の取組みについての質問です。こちらにつきましては、東京都の計画や国全体の計画を踏まえながら、来年度、まず考えてまいりたいと考えています。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"提案","question":"ぜひこれを計画に盛り込んでいただきたいなと思っているのが１点です。削減を達成をしていくという意味で、ちょっと具体的な提案をいたしますけれども、ＣＯ２の増えた原因の１つに、サーマルリサイクルが入っていました。品川区自身も助成額を元に戻し、自然エネルギー普及を進めることにぜひ力を注いでほしい。マンションに対しては、規模に合わせてぜひ増額をお願いしたいと思いますが、いかがでしょうか。","respondent":"三ツ橋環境課長、小林品川区清掃事務所長","answer":"委員ご提案のございました様々な取組みですけれども、できること、できないこと、品川区としていろいろなものがあると思います。来年度、じっくり考えながら検討してまいりたいと考えています。サーマルリサイクルですけれども、その背景として最終処分場の問題等もありますので、直ちに方針を見直して改めることは考えておりません。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"提案","question":"私の提案の１つに太陽光発電をぜひこの品川で広げていただきたいという点がありますので、じっくりではなくて、十分考えて実現をしてください。続いて、商店街の活性化なのですけれども、商店街を応援していきたいなという思いで質問いたしますが、中小企業支援を中心に据えた予算増額を求めていきたいと思いますが、決算カードをチェックして見ましたら、商工予算が減っているのですね。","respondent":"山崎商業・ものづくり課長","answer":"現在は、旗の台のほうで具体的な対応を庁内のほうで関係部門と連携しながら、商店街のバリアフリーについても検討させていただいているというような状況で、そうした点も推進してまいりたいというふうに考えてあります。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私、武蔵小山の商店街を毎日通ってこちらに伺うのですけれども、以前、車椅子を利用されていた方が、トイレがない、８００ｍで長い商店街でいろいろなお店があるので買い物に来るのが楽しみなのだけれども、車椅子で入れるトイレかなくてすごい困るというので、一度、商店街の方とお話もしたことがあるのですが、なかなか事情がわかっても厳しい、本当に今、厳しい、景気の悪い中で。","respondent":"山崎商業・ものづくり課長","answer":"そうした公道の安全を確保するまちづくり部門と連携をしながら、にぎわいと安心のできる環境というようなところで、できる限りの対応をしてまいりたいというふうに考えるものです。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"意見","question":"できる限りの応援をしていきたいというご答弁をいただいたので、本当に、私は、この長引く不況の中で、今やらなくてどうするのかと、今本当に頑張れるところだと思いますので、よろしくお願いしたいと思います。武蔵小山の駅前の再開発の事業が始まりました。この間、区役所の近く、一本橋商店街は、１６３号線と沿道開発で店舗が本当に寂しい状態になりました。","respondent":"山崎商業・ものづくり課長","answer":"そうした再開発の工事期間中も、武蔵小山の魅力でありますアーケードと商店街の連続性が阻害されない観点でしっかり整備をしてまいりたいというふうに考えるものです。","id":"exchange-011"},{"speaker":"松永委員","kind":"質問","question":"私からは、２７１ページの公衆便所費、２７５ページのウォーキングマップアプリ運用保守等、２８１ページの航空機騒音調査、同じく、カラス・外来種対策事業について伺います。２７１ページの公衆便所維持管理についてですが、小破修理のところで、昨年度は３４２万５,０００円で、本年度は８１２万３,０００円となっておりますが、この予算増の内容について伺いたいと思います。","respondent":"多並公園課長、川島健康課長","answer":"公衆便所の中の小破修繕８１２万３,０００円につきましては、このうち４８０万円、これが昨年度よりも増えている分ですけれども、京急線が高架下をお借りして、青物横丁駅の公衆便所があるところなのですけれども。こちらの保守というのは、ＯＳのアップデートへの対応ですとか、それから随時の紙面の更新、そういった作業になってまいります。","id":"exchange-012"},{"speaker":"松永委員","kind":"質問","question":"公衆便所では、そうした青物横丁駅のトイレの移動でそのぐらいのお金がかかってしまうということなのですけれども、そのほかにも幾らかまだ計上されておりますが、主に小破修理でどういったところの損傷が目立っているのか、また、その対策というのはとられているのでしょうか。現在、以前も質問があったと思うのですが、和式と洋式の割合について伺います。","respondent":"多並公園課長","answer":"利用者の方に周知という件ですけれども、美観上の観点で、なるべくモラルに期待した形で行っているところですけれども、あまりにも多い場合は、そのような起こるところについては今後もそのような周知はもう少し図っていきたいと思っているところです。","id":"exchange-013"},{"speaker":"松永委員","kind":"質問","question":"それぞれ公衆便所といいますと、和式と洋式ということで、今、１６％が洋式というお答えをいただきました。私もたまに使うのですけれども、和式だと、よく見ると、やっぱり床が汚れていることがとても多くて、そのように感じているところであります。区のお考えについて伺いたいと思います。","respondent":"多並公園課長","answer":"そういう点で、来年度以降、速やかに観光部門と連携しながら検討し、進めていきたいと思っているのが現時点です。","id":"exchange-014"},{"speaker":"松永委員","kind":"質問","question":"昨年度の予算に比べて約１,０００万円減ということでありますが、これは航空機の騒音、前回質問させていただいた中で、測定器等の設置とか場所とか、まだ決まっていないということであったのですが、減った原因は、それも含まれているのか伺いたいと思います。これも前年度予算に比べて３２６万１,０００円から、倍の７４４万６,０００円と増えておりますが、その理由について伺います。","respondent":"三ツ橋環境課長","answer":"その中でどのようなことを考えていったらいいかというふうに考えている中で、測定機器の保守点検委託の削減であったり、または測定データの業務委託の削減であったり、年間契約として１年間契約と考えておりますので、大きなことを削減いたしました。","id":"exchange-015"},{"speaker":"松永委員","kind":"質問","question":"少し時間が余ってしまいましたので、２９７ページの大井町駅等イルミネーションの経費について伺います。前年度予算では款が違いますが、土木費で５,０００万円ついており、今回は産業経済費で６,７００万円とあります。このことについてどのような形で変わってしまったのか伺います。","respondent":"間部文化観光課長","answer":"大井町になぜ設置したかということですけれども、品川区の中心はやはり大井町駅ということで、駅前を中心ににぎわいを創出するということで、特に街路があるということと、街路の電気設備が整っていることから、今回は大井町駅で展開をしたです。","id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"中心は大井町駅ということをお聞きしました。そこで、この６,７００万円というのは、前よりもちょっと高いな、ついておるのですが、何か計画等がありましたら、最後に伺います。","respondent":"間部文化観光課長","answer":"平成２８年度予算につきましては６,７００万円ということで、大井町駅の継続を予定しておりまして、その部分が大体３,０００万円ちょっとぐらいだということですので、もう１カ所どこかに設置をしていくということで、現在、鋭意検討中ですので、観光スポットの観点や。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"私からは、まず２８１ページの温暖化対策事業についてお伺いいたします。環境三計画改訂プロジェクト、先ほどから何人かの委員からお話が出ましたけれども、そもそもこれ、改訂をする目的、必要性は何なのか。やはり温暖化防止対策がメインなのか、削減目標などは掲げる予定はあるのかお知らせください。","respondent":"三ツ橋環境課長","answer":"地域推進計画につきましては、区民や事業者とともに区が取り組んでいくＣＯ２削減計画ですけれども、その３つの計画がなかなか整合性がとれていないのが現状としています。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問","question":"削減目標とかは掲げられる予定はあるのでしょうか。","respondent":"三ツ橋環境課長","answer":"実際に、非常に削減目標というものが難しい部分がありますけれども、東京都の削減目標が実際に非常に高い部分です。区として実効性を伴う削減目標を掲げたいと考えていますが、来年度、考えながら取り組んでまいりたいと考えています。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問・要望","question":"なかなか本当に実行できるか難しいかもしれませんけれども、削減に向かっての努力はぜひともしていっていただきたいと考えております。次に、太陽光発電、助成はやっておりますけれども、この太陽光発電は、今現在、品川区の公共施設でどの程度設置されているのでしょうか。","respondent":"三ツ橋環境課長","answer":"太陽光発電につきましては、区内区有施設で３２施設です。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"太陽光発電、助成もやっておられることですし、積極的に進められていると考えていますけれども、太陽光発電以外の再生可能エネルギー、例えば水力発電、風力発電など、この点の今後の導入の検討はどうなのかということをお伺いしたいと考えています。","respondent":"三ツ橋環境課長","answer":"実際に品川区がどの程度太陽光を掲げなければいけないか、また、風力を掲げなければいけないかというものにつきましては、来年度、考えさせていただきたいと思いますけれども、目黒川であったり、立会川であったり。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問・要望","question":"原発事故のあった東日本大震災からちょうど５年の節目ということもありますし、温暖化対策、これもしっかりとやらなければいけないと考えていますので、品川区、基礎的自治体のほうでもしっかりと行っていただきたいと考えております。続けて、２８１ページの航空機騒音調査についてお伺いをいたします。確認として、航空機騒音調査を行う目的は、そもそも何なのか。","respondent":"三ツ橋環境課長","answer":"品川区として、騒音というものをどのように捉えていったらいいのか、その目的といたしましては、静かな状態をまず測っておくのが、まずは現状確認が大事だと考えています。それなので、その目的に向かって今回は考えております。","id":"exchange-022"},{"speaker":"筒井委員","kind":"質問","question":"その目的は、端的に言ったら、羽田空港の国際線増便による新ルート案による騒音対策ということだと思うのですけれども、もし騒音調査を行った場合、非常に区民も関心が高い問題なので、また、この午後３時から午後７時という時間帯は、学校とか職場にも多大な影響があると思いますので、どのぐらいの程度の騒音なのかということがわかり次第、適時、適切。","respondent":"三ツ橋環境課長","answer":"その中でどのように、例えば調査測定をした場合は、広報などの関係につきましてはお知らせはするべきだと考えております。そのほか、区民の皆様にとっても騒音というものは非常に心配な部分がありますので、そのほかのことに関してもいろいろ発信していきたいと考えています。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問・要望","question":"区民に対してしっかりとした情報提供をお願いしたいと考えております。その場合、異常な騒音とかが発生した場合、特に環境基準超えとか、受忍限度を超えるような騒音を発生した場合は、国に対して厳重な抗議を行っていただきたいと考えておるのですけれども、その点いかがでしょうか。","respondent":"三ツ橋環境課長","answer":"そのような場合になったときには、然るべき対策をとってもらうように国に申し入れていかなければいけないと思いますけれども、今、現状はまだ国の考え方が決まっていない状況ですので、今は特には考えておりません。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"そこのルート案が決定されないことを本当に願うばかりというか、撤回すべきだと考えておるのですけれども、もし万が一、通ってしまった場合、そして異常な騒音が起きた場合は、厳重な抗議をお願いしたいと考えております。次に行きます、２９７ページの観光アクションプラン推進事業についてお伺いをいたします。今回、観光アクションプランでターゲットにしたい相手はどなたなのかお知らせください。","respondent":"間部文化観光課長","answer":"したがいまして、品川区の中に歴史に関するところ、水辺に関するところ、商店街など、数々の魅力があるわけですけれども、そういった点、まず区民から始めて、多くの方に来ていただく、こういうことを平成２８年度から展開してまいりたい、このように考えてあります。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"ということで、区民がメインだということなのですけれども、その実効性のために、やはりもっと品川区の交通アクセスを向上させたほうがいいと考えております。例えば、コミュニティバスを通して品川区の中央を横断するような、そうした新しい交通手段が必要ではないかと考えておりますが、その点、どうお考えでしょうか。","respondent":"間部文化観光課長","answer":"バスもかなり充実しておりまして、いずれの駅にも徒歩１０分以内には行けるというような状況がありますし、先ほど来、お話をさせていただきましたとおり、まち歩きというのが都市型観光の肝でありますので、ぜひ区内を歩いていただきたいということでありますので、現在のところ。","id":"exchange-026"},{"speaker":"横山委員","kind":"質問","question":"私からは、２６９ページ、がん検診普及事業、子宮がん、乳がん検診推進等について、２７７ページ、不妊治療助成事業について、３０５ページ、品川産業支援交流施設経費についてと、３０７ページ、産業活性化推進事業についてお伺いをいたします。がん検診普及事業についてお伺いをいたします。子宮がん検診の対象者なのですけれども、２０歳以上の女性の区民。","respondent":"川島健康課長","answer":"子宮がんのほうは、同様の統計で、２０歳から２４歳が４３１人、２５歳から２９歳が１,３５６人、３０歳から３４歳が２,１１１人、３５歳から３９歳が２,０５７人、４０歳から４４歳が１,８５７人、４５歳から４９歳が１,３３６人、５０歳から５４歳が１,０５６人。","id":"exchange-027"},{"speaker":"横山委員","kind":"質問","question":"詳細にご説明いただきましてありがとうあります。昨年１１月の健康大学しながわの第５回公開講座にて、一般財団法人全日本労働福祉協会旗の台健診センターの西野るり子先生の講演をお聞きいたしました。","respondent":"川島健康課長","answer":"それで、平成２８年度も同様の啓発の講演会は開催する予定でおりますので、若い方を呼ぶために、どんなテーマがよいのか、それからどんな日時や会場ですとか時間がよいのかという部分、知恵を絞って検討して、よい講座になるように、これから考えていきたいと考えています。","id":"exchange-028"},{"speaker":"横山委員","kind":"質問・要望","question":"今ご答弁いただきましたけれども、今回は年齢層が少し上の方が多かったということで、平成２８年の開催では、２０代、３０代、４０代ぐらいですか、そのあたりをメインの対象にということで広く参加をいただけるような内容と開催日時で設定してくださるというお話でした。２０代から３０代、４０代の女性でも、様々なライフスタイルを送っていらっしゃるかと思います。その辺、区のご見解をお願いいたします。","respondent":"川島健康課長","answer":"ライフスタイル別の啓発については、これからも少し検討させていただければと思います。","id":"exchange-029"},{"speaker":"横山委員","kind":"質問・要望","question":"共感を得やすいキャンペーンネームを使用したほうが受診率アップにつながるのであれば、サブタイトルやキャッチコピーとしての使用を含めて、効果的な講座名ですとか、キャンペーンネームを使用しての普及啓発をお願いしたいのですけれども、区の見解をお願いいたします。","respondent":"川島健康課長","answer":"様々な新しいご提案をいただきました。私ども、どのようにしたら受診率が上がるかという部分は、いろいろ手探りでやってきたところもありますので、いただいたご提案も踏まえまして、今後検討させていただければと思います。","id":"exchange-030"},{"speaker":"横山委員","kind":"質問","question":"前向きなご答弁ありがとうあります。次の質問に移ります。不妊治療助成事業についてお伺いいたします。昨年１０月の決算特別委員会で、私のほうから質問させていただいたのですけれども、国の特定不妊治療において、平成２８年４月から４３歳未満を助成対象にする年齢制限が設けられるとお聞きしておりますが、品川区のほうで一般不妊治療費助成においては、何か変更等は生じる予定がありますでしょうか。","respondent":"川島健康課長","answer":"区の一般不妊治療は、不妊治療制度の入口として設ける制度であるということ、また、妊娠、出産を希望される方が、安心安全でリスクの少ない年齢で治療を開始することが望ましいという観点から、区の一般不妊治療にも同様の年齢制限を設ける予定です。","id":"exchange-031"},{"speaker":"横山委員","kind":"質問","question":"次に、品川産業支援交流施設経費についてお伺いいたします。ＳＨＩＰの現在までの利用状況と成果を簡単にお願いいたします。","respondent":"立木産業活性化担当課長","answer":"そのほか、光造型の高品質の３Ｄプリンターが利用としては４４時間ということで、オープンから８カ月を過ぎまして、広く認識をされてきたような状況だと捉えております。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問","question":"稼働日数、イベントホールのほうは８０％ということで、すばらしい稼働日数かと思います。会員数も順調に増えていらっしゃるということで、大分成果が見えてきているのかなというふうに思うのですけれども、今後、新たなビジネスモデルを創出、発信する拠点として、今後、期待している部分、また、イノベーションを生み出す可能性を区はどのように捉えていらっしゃいますでしょうか。","respondent":"立木産業活性化担当課長","answer":"中で、オフィスの方から、例えば、活性化のためのプランのコンテストなども実施しておりまして、その中で、例えば、グループをつくりまして決められた時間の中で課題を解決していくハッカソンみたいなものをやったらどうかというような提案もございまして。","id":"exchange-033"},{"speaker":"横山委員","kind":"提案","question":"今、ハッカソンのほうのご提案を入居者の方からいただいているということで、ブライトコアホールの使用例として、さまざま講演会ですとか、記者発表ですとかあるのですけれども、実際の使用例として、昨年の６月ですか、世界規模のハッカソンが行われたという実績があるかと思います。","respondent":"立木産業活性化担当課長","answer":"品川、大崎という立地を生かして、そういった関係機関の方々と連携をとった上で、ホール、３階、４階、連携をとりまして、そういったイベントも検討してまいりたいと思います。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"確認","question":"私からは、２７５ページ、難病対策費から、軽度外傷性脳損傷、略称ＭＴＢＩについて、２７５ページ、健康センター事業費、指定管理者運営委託、３点目、時間があれば、「伝統の技と味しながわ展」開催等経費について伺います。１点目ですけれども、軽度外傷性脳損傷、略称ＭＴＢＩの一般質問について幾つか確認をします。検討状況、そしてパンフレット作成のスケジュールを教えてください。","respondent":"舟木保健予防課長","answer":"今後、その意見をもとに内容を修正しまして、イラスト等を入れて印刷の見積もり等をしていく方向でおります。今年度は、もう日が迫っているので、今年度中は難しいかもしれませんが、来年度早い時期の完成を目指して進めてまいりたいと思います。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問","question":"なぜかというと、これは政策判断だからです。これ、国のほうではまだ認めている話ではない。一つ大きなところで、教育委員会、今回、ご答弁の中で周知をしていただく、教育機関の周知をいただくとあったのですけれども、実はここがすごく肝だと思うのですが、どのような形で周知をしていただくのか、先ほど、検討中ということだったのですが、どのようにお考えになっているのかお伺いいたします。","respondent":"舟木保健予防課長、品川庶務課長","answer":"作成したパンフレットを配布していただくのと、あと、こちらのほうからは、学校保健会等を通じて周知を進めてまいりたいと思います。パンフレット、現在、作成中ということで、作成次第、学校のほうへ配りまして、周知を図っていきたいと、このように考えてあります。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問","question":"すみません、私、再委託先を聞くのを忘れてしまったのです。２年前から労働条件等をチェックする専門家である社会保険労務士による指定管理者への労務監査を試行で行っておられると聞いていますが、これがどうなっているのか教えてください。試行した施設はどこなのか、指定管理者は誰なのか、差し支えなければ教えてください。企画調整課になると思います。","respondent":"柏原企画調整課長","answer":"平成２７年度につきましては、２事業者ということで、今、ご案内出ましたけれども、住友不動産エスフォルタ等々の共同事業体、それから社会福祉法人の新生寿会、こちらを平成２７年度はチェックということでやらせていただいたものです。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問","question":"今初めて伺いましたけれども、品川健康センターは、三社共同事業体という珍しい指定管理になっていますが、比較的大規模な企業であって、こういう複数の事業体でも労務監査は可能だったのでしょうか。もし違反があった場合、それがどのように改善をされていくのか教えてください。","respondent":"柏原企画調整課長","answer":"今回、試行という形でやらせていただきまして、まだ試行という形ですので、どういった形でこの事業を進めていくかというのは、模索しながらというところがあります。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問・要望","question":"こういう社会保険労務士のような専門家が、第三者が入ることによって、賃金とか、労働条件とか、コンプライアンスが適正かどうかというところを確認していただくことには一定の効果が期待できると思いますので、今後、しかもその中で今度は委託先に入っていくということも難しいと思うのですが、この社会保険労務士による労務監査を拡大していっていただきたいと思うのですが、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"一番大きいのは、やはり事業者がそれに対して、これは一種の監査的なところがありますので、負担もあるというのは事実です。そういったところを鑑みながら、どういったところまで進められるかというのは、もう少し検討していきたいというふうに思ってあります。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今回、販路拡大助成１５５万円とあるのですが、これについてどういうものなのか教えていただきたいということと、先日、現職の文化庁長官の青柳さんという方の講演を伺ったときに、「今後の衰退していく日本の文化を守っていくのは、実は様々な、浮世絵であるとか、歌舞伎とか、そういう文化があるけれども、見落としてならないのは、やはり工芸品である。","respondent":"山崎商業・ものづくり課長","answer":"品川の職人組の皆さんにつきましては、こうした昔から伝えられている伝統の技、技術を新しい角度からやはり考察をしてみたり、再構築をして、より洗練された製品として創出をしていく必要があるだろうということもありまして、区のほうでそうした専門家の委託もかけまして。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問","question":"今までもいろいろな職人同士のものを組み合わせて新たなものを開発されたりとか、それも展示がありますし、やはりどうしても値段もかなり高いですし、安売りしろと言っているわけではないのですけれども、値段も高いですし、やはり記念品的なものの扱いにどうしてもなってしまうという中で、そのものの価値はやはり日常生活において使うことにあるのではないのかと。","respondent":"山崎商業・ものづくり課長","answer":"それぞれの分野で技術、技を使いました伝統工芸品そのもののすばらしさを伝えることも大切ですが、先ほども申し上げた、いろいろな形で現在の時代に合わせた、例えば新伝統工芸品なるものを開発をするなり、あるいは、お求めになりやすいような価格設定ができれば。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問","question":"２９７ページ、５款産業経済費、１項産業経済費、１目産業経済総務費、若者・女性就業支援事業と、２７３ページ、４款衛生費、１項保健衛生費、４目保健指導費の出産・子育て応援事業について伺います。２９７ページの若者・女性の相談支援について伺います。予算編成を行うに当たって評価はどうだったのか、また改善点はどこだったのか伺います。","respondent":"立木産業活性化担当課長","answer":"来年度予算を組むに当たりましては、こういった部分を精査いたしまして、それで若干の増ということでしています。こちらもやはり女性の活力を社会のほうで生かしていただくということでは、非常に重要な事業と考えております。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"就労相談では、女性の就労支援には子どものいない方もおられるでしょうから、子連れだと周りの方も気になりますし、十分な相談はできません。就労相談で相談者がそのような心配をしないで相談ができる環境を、ぜひ品川区では整えてほしいと要望いたします。場所がないということで切り捨てないで、ぜひ若者・女性就労支援相談に子どもコーナーの検討をしていただきたいのですが、見解を伺います。","respondent":"立木産業活性化担当課長","answer":"中小企業センターの中には託児室もありますので、そちらのほうが空いていればご利用は可能なのですが、ただ、そこの部分で人の手当てをするという部分に関しましては、今のところ、いろいろなことがありますので、今後の研究課題とさせていただきたいと存じます。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問","question":"そうですか。では、ごめんなさい。２７３ページ、しながわ版ネウボラが本格的にスタートすることについて評価しています。１歳になったばかりの子どもと日々向き合い、日々の成長に喜んだり、悩んだりしています。そこで、まず、妊娠期相談事業について伺います。妊産婦ネウボラ相談員は、どういった方に対して支援をするのか。妊産婦ネウボラ相談員と１カ月訪問指導員の違いを簡単に教えてください。","respondent":"太田品川保健センター所長","answer":"妊娠期の相談事業ですが、助産師が対応する方は経産婦も含めて、今、妊娠中の方ということで、初産の方に限っているわけではございません。そして面談の時間は、３０分以上１時間以内ぐらいを予定しております。回数につきましても、何度も相談に見えることは可能です。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"では次に、新規事業の産後の家事支援ヘルパーについて伺います。例えば、たすけあいワーカーズとか、ＮＰＯも委託先として考えていますでしょうか。そして、現在行われている育児支援ヘルパーと家事支援ヘルパーの位置付けについて伺います。１人６カ月で１０時間の利用ですが、区としてはどのような利用内容を想定しているのか伺います。","respondent":"伊崎子ども育成課長","answer":"こういった方たちだけでなく、もう少し広く産後の不安を解消する必要がある方たちに対して支援を行うのが今回の制度でございまして、目的は産後の不安の解消、あと母体のケア、あとは家事・育児支援というところで、育児支援ヘルパーは母体ケアができないのですけれども。","id":"exchange-045"},{"speaker":"田中委員","kind":"質問","question":"そういうことですよね。そうですね。虐待死する子どもの約４割が０歳児であり、その多くがお母さんからのものという残念なことだったので、産後に約１割の母親が産後うつを発症しているということを考えると、やはりもう少し増やしてほしいなと思います。見解を伺いたいと思います。そしてもう一つ一緒に、事業者の利用料を１時間当たり幾らぐらいに想定しているのか伺います。","respondent":"伊崎子ども育成課長","answer":"この事業は、来年度初めて区として行うものですので、そういった事業の実施状況等を見まして、また利用者のお声を聞きながら、今後については検討いたします。","id":"exchange-046"},{"speaker":"田中委員","kind":"質問・要望","question":"妊産婦相談員と１カ月訪問指導員、家事・育児支援ヘルパーは違う所管であり、別の方だと伺っています。そして家事支援ヘルパーでは、家事・育児の支援が基本で、育児のことや授乳の方法、離乳食について教えてもらうことができると伺いました。このような支援は本当にありがたいと思いますが、実際に子育てしている人たちに伺うと、母親本人のレスパイトを求めている方がたくさんいます。","respondent":"伊崎子ども育成課長","answer":"その連携方法につきましても、今、検討中でございまして、子育てネウボラ相談員の配置が６月からですので、それまでにきちんとしたものを出したいと考えております。","id":"exchange-047"},{"speaker":"田中委員","kind":"提案","question":"ホテルを活用した産後ケアのモデル実施について伺います。アンケートでは、どういう質問で、どういう回答が多く、この事業が提案されたのでしょうか、具体的にお答えをお願いします。この４時間で乳児の健康状態をはかり、昼食を食べ、育児方法、授乳方法、母体の回復を早めるケアをするには、利用者本人も忙し過ぎるのではないでしょうか。","respondent":"伊崎子ども育成課長","answer":"乳児期から２歳児までの方たちの中では、やはりリフレッシュできない、自分の時間が持てないというようなお声が高かったということがございました。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"私からは、３０７ページ、産業活性化推進事業と、２６５ページ、公衆浴場について伺います。産業活性化推進事業ですが、プレス発表では、産業活性化のための新たな事業展開に向けた調査研究とあります。今回の調査は、これまでの調査と何がどう違うのでしょうか。新規事業のポイントをまずご説明ください。","respondent":"立木産業活性化担当課長","answer":"こちらの産業活性化推進事業ですけれども、こちらの事業は、今まで区のほうで産業支援施策としましては、基盤的なところ、経営の安定を図る部分と、さらに中小企業の皆様が大きく飛躍するための部分の産業支援という二階建ての構造をしてきたところですけれども。","id":"exchange-049"},{"speaker":"安藤委員","kind":"提案","question":"そこで、町工場などへの工場の家賃、あるいは動力などの固定費の補助の制度を提案したいのですけれども、品川区は、従来から現金給付となる固定費補助の考えはないとおっしゃっておりましたけれども、このままでは、ますます中小企業の経営が苦しくなるだけだと思うのですけれども、この固定費補助についてのお考えはいかがでしょうか。","respondent":"立木産業活性化担当課長","answer":"そういった形で、企業の戦略の中でそういったものを有効に活用していただいて、行政からお金をまくというような形の支援ではなく、一緒になって融資、それから経営相談等も受けておりますので、そういった中で補っていただくというような形で進めているところです。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問","question":"個々の企業に戦略や力をつけてもらうということも大事かもしれませんが、そういう従来の支援では経営が続かない中小企業があるという現実をご存じかどうか伺いたいと思います。私も何軒か町工場を訪ねて現状を伺いました。年をとって働けなくなったらどうなるのだろうかとおっしゃっておられました。区の従来の事業では救われない中小企業への支援が必要だと思いますけれども、いかがでしょうか。","respondent":"立木産業活性化担当課長","answer":"こちらのほうは、なかなか後継者が見つからないというような部分で、なおかつ、技術的なところはこれからも続けてまいりたいとか、そういった部分の相談ですとか、あとはどういった形で、例えば事業を譲渡なりということも考えているというような中で、いろいろな支援策を。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは質問です。次に、公衆浴場についてお伺いします。銭湯を地域からこれ以上なくさないための支援を求めて質問いたします。貴重な地域資源とはどういうことか、もう少し伺いたいと思います。公衆衛生の観点はもちろん、健康増進、地域コミュニティの醸成、古くから続く銭湯文化、観光資源、いろいろ意義があると思いますけれども、貴重な地域資源とはどういう意味か伺いたいと思います。","respondent":"立木産業活性化担当課長、川島健康課長","answer":"そういった中で例えば、区内で事業を続けたい場合の立地継続支援というような支援もあります。そういったメニューをさまざま用意する中で、支援はさせていただきたいと考えています。東京オリンピック・パラリンピックの開催に向けましては、外国人観光客を呼ぶための観光資源にもなるということで、少しでも多くの公衆浴場にいつまでも地域で愛され続け。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"今もそういったお言葉がありましたけれども、様々なそうした意味で補助などを一昨年引き上げたということですが、この銭湯への支援策の今後の方向性を伺います。昨年度、支援策を引き上げてからの昨年と今年で、区内の公衆浴場の数はどう変わったか、この数年の経緯と、その理由や背景などもあわせて伺いたいと思います。","respondent":"川島健康課長","answer":"こうした支援、継続してやっていけば、１軒廃業にはなりましたが、まだまだ頑張れるのではないかと考えております。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問","question":"昨年に戸越四丁目の銭湯が廃業されてしまったということで、支援策を打ったのだけれども、１軒減ったということでした。激減している廃業の理由は、営業不振、高齢化、後継者不足、施設の老朽化などたくさんありますが、これらを解決して銭湯をこれ以上減らさないために何が必要なのか、区の見解を伺います。","respondent":"川島健康課長","answer":"現状、今、持家率が大体９６％にも上るということで、なかなか皆様、公衆浴場に足を運ばない方が増えているということです。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"ここをどう考えるのか。私は、さらなる支援の充実や強化が急務だと思いますけれども、いかがでしょうか。","respondent":"川島健康課長","answer":"一企業というところの考え方からすれば、どこまで支援を手厚くすることがいいのかという部分のバランスの問題もあると思いますが、かなり私どもも手厚い設備改修の補助ですとか、いろいろな部分で手を差し伸べておりますので。","id":"exchange-055"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"本日は、ページ２６７の任意予防接種からロタウイルスワクチン、Ｂ型肝炎、ＭＲ（麻しん・風しん）に、肺炎球菌に、ページ２６７の新興感染症対策と先天性風しん症候群対策、ページ２６９の２０歳からの健康診査、２０歳以上４０歳未満についてお伺いしていきたいと思います。自民党・子ども未来は、平成２８年度政策要望の第１位に、ロタウイルスワクチンの接種費助成を掲げました。","respondent":"舟木保健予防課長","answer":"１価のワクチンについては６週から２４週まで。５価のワクチンについては６週から３２週までとしています。助成回数については２回となります。１回当たり７,０００円を予定しております。実施機関は、区内の契約医療機関で行う予定で、今後、調査してまいりたいと思います。","id":"exchange-056"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"ご丁寧なご説明ありがとうございました。１価のワクチンと５価のワクチンは接種の量も違いますし、有効期間が違うので、３２週と２４週、その期間を間違っては困るので、その辺のこともしっかりと保健当局のほうで対応していただきたいと思うのですが、また、接種費用の一部助成を始めるに当たりまして、特に区としてこの点は注意しなければいけないという注意点に関してご説明をお願いします。","respondent":"舟木保健予防課長","answer":"接種をするに当たりまして留意すべき点なのですが、まず今言われているのは、ワクチン接種後に特に初回の接種後７日以内に腸重積の発症のリスクが増えるということが指摘されておりますので、接種するに当たっては、保護者の方に十分説明。","id":"exchange-057"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"平成２５年度の厚生労働省のロタウイルスワクチンの中間報告書によると、ロタウイルスワクチンの接種率は、品川区では大体６５％ぐらいだと推定されています。それとともに区議会でもたびたびロタウイルスワクチンの接種の助成の重要性を訴え、助成の要望を行ってきました。助成を要望してきた小児科医として、また自民党・子ども未来の一員として、この決定を誇りに思うものであります。","respondent":"舟木保健予防課長","answer":"ロタウイルスによる感染症に関しては、非常に多くの乳幼児が感染いたしますので、高額な接種費用の一部を助成することで、より多くの乳幼児の方に接種していただいて、重症化予防、引いては集団予防が期待できるものと考えています。","id":"exchange-058"},{"speaker":"鈴木（博）委員","kind":"意見","question":"Ｂ型肝炎ワクチンについてお尋ねします。Ｂ型肝炎ワクチンは、２年前から、品川区の場合は３,０００円の接種助成を行ってきたわけですが、状況が今、変化してきたようなので、簡単にその最近の動きについてお知らせください。","respondent":"舟木保健予防課長","answer":"まだ詳細な内容については国のほうから連絡がありませんが、ありましたら、すぐに情報共有したいと思いますし、また、こちらも定期化に向けて準備をしてまいりたいと考えています。","id":"exchange-059"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"２０歳からの健康診査についてお尋ねします。昨年の決算特別委員会総括質疑において、我が会派の渡部委員が、「３５歳からの健康診査を、より若い世代からの生活習慣病に対する対策の強化をする必要がある」として、２０歳からの健康診査の実施を要望いたしました。平成２８年度予算案に、２０歳からの健康診査が新規事業として計上され、自民党・子ども未来の要望が実現したことは高く評価いたします。","respondent":"川島健康課長","answer":"２０歳からの健康診査につきましては、女性の健診と３５歳からの健診を統合して、健診項目を見直し、新たに実施するものです。","id":"exchange-060"},{"speaker":"鈴木（博）委員","kind":"質問","question":"主なターゲットが女性は鉄欠乏性貧血、男性の場合は痛風だということがわかりました。健診の結果をもとに生活習慣病対策を確実に成果があるものにするには、多くの方に受診していただかなければなりません。新規事業の広報や周知、受診者数を増やすためにどのような対策をお考えか、簡単にご説明をお願いします。","respondent":"川島健康課長","answer":"お知らせのポスターを医療機関に張っていただきます。それから、広報しながわの４月１１日号に第一報を掲載する予定です。","id":"exchange-061"},{"speaker":"鈴木（博）委員","kind":"質問","question":"詳しいご説明ありがとうございました。次に、新興感染症として、ジカウイルス感染症対策として、歳入に引き続き、蚊を防ぐ防蚊対策についてお伺いいたします。２０１５年の第３回定例会の一般質問で、デング熱について質問いたしました。今回の質問では、これから夏に向けて活動が活発になるヒトスジシマカの防蚊対策について、品川区の取組みをいま一度ご説明をお願いしたいと思います。","respondent":"高山生活衛生課長","answer":"具体的にはボウフラが羽化しないような形で、薬剤であります昆虫制御剤を雨水ます３万カ所に投入することによりまして、５月から１０月の幼虫が育ちやすい時期に発生を抑制することで、蚊の総量の抑制を図ってまいりたい、そのように考えております。","id":"exchange-062"},{"speaker":"鈴木（博）委員","kind":"質問","question":"先天性風しん症候群対策についてお伺いします。妊娠を希望する夫婦等に対する風しん抗体検査と予防接種の接種費用助成事業が、平成２８年も継続されることは高く評価いたします。一言でこの事業の内容についてご説明をお願いします。","respondent":"舟木保健予防課長","answer":"抗体検査を女性の方、男性の方、受けていただきまして、抗体が低い方に風しんの予防接種を全額助成で実施しております。風しんの抗体化検査につきましては、今までに風しんにかかったことがなく、予防接種を受けたことがない方としています。","id":"exchange-063"},{"speaker":"鈴木（博）委員","kind":"確認","question":"東京都のホームページを見ますと、風しん抗体検査事業というのがありまして、それを見ると、ワクチンの接種が必須条件にはなっていないことを確認いたしました。東京都の場合は、実際これが外れているみたいなのですが、今、品川区としては、それについてはどのようにお考えでしょうか。","respondent":"舟木保健予防課長","answer":"ただ、区としましては、区独自で妊娠を希望する女性と同居している男性、あるいは妊婦と同居している男性の方も広くこの事業の対象としております。ただ、妊婦健診で風しんの抗体価が低かった方に対しての予防接種の対応につきましては、今後、検討してまいりたいと思います。","id":"exchange-064"},{"speaker":"鈴木（博）委員","kind":"確認","question":"ぜひ風しんに感受性がある女性、男性が１人でも減るように、弾力的な対応をお願いしたいと思います。プロジェクトの事務局は東京商工会議所に置いて、まず都内の企業に呼びかけて、従業員に風しんの抗体検査や予防接種の確認などをする協力企業を募ります。非常にすばらしい取組みだと思われますが、この取組みに品川区はどのように対応されているか、かかわっているか、ご説明をお願いします。","respondent":"舟木保健予防課長","answer":"今回、風しんの流行につきましては、２０代から４０代での感染者が多かったということを考えますと、職域への周知は非常に重要だと認識しております。","id":"exchange-065"},{"speaker":"鈴木（博）委員","kind":"意見","question":"二度と風しんと麻しんの流行を起こさないように、そして先天性風しん症候群で産まれる赤ちゃんを減らすように、今後も区のほうも一層のご努力をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"塚本委員","kind":"質問・要望","question":"先ほども感染症の話も、ジカ熱とかありましたけれども、狂犬病についても外国からの流入の危険がある中で、この接種率が７０％ということで、３割の方が接種をしていないというような状況になっているわけですけれども、この原因についてどのようにお考えになっているかお伺いいたします。","respondent":"高山生活衛生課長","answer":"狂犬病予防法におきましては、接種等がない場合には２０万円以下の罰金ということで、非常に重い罰を予定しているものではあるのですが、なかなかそういった部分が飼い主の方の責務として伝わっていない部分があろうかと思います。","id":"exchange-067"},{"speaker":"塚本委員","kind":"質問・要望","question":"今、飼い主の責務というのでしょうか、２０万円以下の罰金というお話もありましたけれども、これは実際はそういうことが、罰金をとられるとかということが事実上どの程度あるのかということをお伺いしたいのと、意識の低下ということで、実際には国内で全く発生していないという、長年発生していないということでしたけれども、そういった中でも。","respondent":"高山生活衛生課長","answer":"ついては、接種率向上に向けてどのような対策が考えられるかですが、先立っても他の委員のご質問の中でもお答えしたことではありますが、狂犬病の予防接種の法定接種期間が４月から６月という３カ月の期間なのですが、従前は２週間の期間を区切りまして。","id":"exchange-068"},{"speaker":"塚本委員","kind":"意見","question":"費用面のメリットもあるかもしれないということで、発見できるがんの対象としても、胃がん、肺がん、大腸がん、乳がんなど、いわゆる日本のがんの死亡率の上位３つを占めるものが全部入っておりますので、こういったものを品川区として、今はまだ実用化ではもちろんないのですけれども、どのように今、この評価というか、見ていらっしゃるか、おうかがいをしたいと思います。","respondent":"川島健康課長","answer":"区で実施しておりますがん検診につきましては、原則として国が認めた対策型検診として位置付けたものをやるというようなスタンスでやっておりますので、もう少しどういう形でそれが普及してくるかとか、それからまた、国がどのような形でこれを認めていくかという部分。","id":"exchange-069"},{"speaker":"塚本委員","kind":"質問","question":"国がということだったと思うのですけれども、国が決めないと、やはりこういうことは一切できないというところにあるのかということが一つと、多分、受診率も国の決めたやり方でないと受診率としてはアップしないのでしょうけれども、例えば、こういったものがある程度実用化されて、しっかりとした結果がとれるというふうなことであれば。","respondent":"川島健康課長","answer":"実は、先ほどもご質問のありましたリスク検診につきましては、国がまだ認めていないものなのですけれども、そういったものを導入するという部分もまれではあるのですが。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。私も参加をさせていただきましたけれども、大変にいい内容だったなというふうに思いますけれども、まず最初にお伺いしたいのは、参加した人数と、どういった区民の方が参加されていたのかということで、あらあら教えていただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"ワークライフバランスのＳＨＩＰにおける講演会につきましては、３４名の参加です。参加者の内訳としましては、企業の経営者の方々も含めまして、そうした人事部門のご担当者、あるいは従業員の方というような内訳になってあります。","id":"exchange-071"},{"speaker":"塚本委員","kind":"意見","question":"こういったことを品川区内の企業でも、ぜひこの啓発を機に進めていただくということは非常にいいことだなというふうに思うのですけれども、中には業態とか、どちらかというと、これは創造的なイノベーション系の企業ではなくて、業態で決まった時間働かないと生産性が決まってきてしまうというような、そういった業態とか企業の規模、一定数の従業員がいないとというようなこともあるかと思うのですけれども。","respondent":"山崎商業・ものづくり課長","answer":"そういう意味では、最近では、１２月から小規模事業者も一定義務化されましたけれども、ストレスチェックの制度が入ったり、それからマイナンバーの制度が入ったり、こうしたいろいろな経営課題を一つひっくるめてワークライフバランスの考え方も入れた。","id":"exchange-072"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういったことの意識の変革ということ非常に大事なのではないかと。制度だけではなかなか実際には進んでいかないという事例がたくさんこの間にも出てきているというところだと思います。そういったところで無関心の払拭というところでの意識啓発、ここに区として尽力いただけることを要望したいというふうに思うのですけれども、その点についての区のお考えを最後にお聞かせいただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"いろいろな方、全て経営者の視点、あるいは、全ての従業員の視点から、例えば満足度調査などをとりまして、ブラッシュアップをするような継続的な取組みを続けてまいりたいというふうに考えてあります。","id":"exchange-073"},{"speaker":"木村委員","kind":"質問","question":"２０歳以上４０歳未満、２,８５０人、２,５９２万円余ですけれども、前年度までは３５歳以上ということでありましたが、これ、素朴な質問になりますが、どこの誰が本当に２０歳の若者が健診を受けなければいけないような病気になると思っているのでしょうか。この事業、平成２８年度の新規事業でしょうけれども、なぜこんなに若返ったのかということをもう一度お願いしたいと思います。","respondent":"川島健康課長","answer":"３５歳からの健診の結果が非常に悪い結果の方が多くて、５１％の方が何らかの悪い医師の所見があったということで、３５歳より前の段階で予防をするという意味、早い段階で手を打つという、そういったことで今回この健診の導入をしたです。","id":"exchange-074"},{"speaker":"木村委員","kind":"質問","question":"２０代男性と女性では、この健診自体にどちらが関心を多く持たれているのか。毎日不摂生をしているにもかかわらず、自分だけは大丈夫だろうとか、若いから大丈夫、病気になどならないと考えているからだと思うのですけれども、絶対数、女性のほうが多いと思いますが、いかがでしょうか。","respondent":"川島健康課長","answer":"別の狙いですが、かなり先の話にはなりますが、多分この健診をやることによって、２０年後、３０年後の医療費がもしかすると削減されるのではないかという、そういう狙いもあります。","id":"exchange-075"},{"speaker":"木村委員","kind":"意見","question":"まさにそのとおりで、私も大変不摂生をしておりました。ほかの市区町村に、このようにして２０歳から健診がなされているところはあるのかどうかということもお聞かせを願いたいと思います。","respondent":"川島健康課長","answer":"品川区を除きまして１２区で２０歳からやっております。無料の区が８区あります。","id":"exchange-076"},{"speaker":"木村委員","kind":"質問・要望","question":"将来的に医療費削減のためにも、この事業が成功することを願っておりますし、頑張っていただきたいと思っています。そして、５歳刻みで健診を行っているとのことですけれども、この５歳刻みのよい点が何かあれば教えていただきたいと思いますし、区民は５年ごとに健診に定期的に来るのかどうかということもお聞かせください。","respondent":"川島健康課長","answer":"５歳刻みの効果ということですが、こちらは、やはり毎年毎年ということだと、いろいろと受ける方も大変ですしというところもありますし、やはり区で制度として実施する以上、ある一定間隔を開けてやるとかということはよくある話ですので。","id":"exchange-077"},{"speaker":"木村委員","kind":"意見","question":"よくある話ということで収めたいと思いますけれども、８０２０、そして９０１６顕彰というものがあります。そういうことで、行政としてどのように歯と健康についてのことを把握されているのかどうかということもお聞かせを願えればと思います。","respondent":"川島健康課長","answer":"歯は食べ物の入口ということもあります。歯が丈夫ならおいしく食事ができて、会話ができて、いろいろ楽しくなって、それから内臓も丈夫になるということですので、健康の重要なバロメーターになるのではないかというふうに考えてあります。","id":"exchange-078"},{"speaker":"木村委員","kind":"質問・要望","question":"まさにそのとおりでありまして、本当に１００歳まで生きられる方というのは、歯が丈夫で、そしてよく歩かれるということをよく聞いております。この予算書には記載されていませんけれども、８０歳代、そして９０歳代では、５１５人がこの顕彰を受けていますけれども、ちなみに、この予算書とは少し違うのですけれども、１００歳以上の顕彰はないのかどうか、あれば教えていただきたいと思います。","respondent":"川島健康課長","answer":"歯の顕彰につきましては、この８０歳と９０歳のものしかないです。","id":"exchange-079"},{"speaker":"木村委員","kind":"質問・要望","question":"お大事にしていただきたいと考えています。これ、４行下のもったいないプロジェクト等なのですけれども、先ほどもほかの委員からも午前中に質問がありました。かぶってしまいますけれども、申し訳ございません。この３１万２,０００円ですけれども、ほかの委員からもありましたけれども、なぜこの事業が、始まるきっかけは何だったのかということと、そしてまた、趣旨をお聞かせ願えればと思っています。","respondent":"三ツ橋環境課長","answer":"その中で品川区としても、もったいないプロジェクトというものを考えてまいりたいと思いまして、区内商店街の中で推進店を設けております。","id":"exchange-080"},{"speaker":"木村委員","kind":"質問","question":"３１万３,０００円、予算計上されておりますけれども、これは何に使う金額なのでしょうか、お聞かせください。","respondent":"三ツ橋環境課長","answer":"こちらにつきましては、ステッカー代がメインです。","id":"exchange-081"},{"speaker":"木村委員","kind":"質問・要望","question":"ステッカー代ですね。本当に先ほどもどなたか質問がありましたけれども、本当にこういうものがどんどんと品川区内に行き届くことがいいことだと思いますので、頑張っていただきたいと思います。予算を増やせば、この事業が急速に進むのかどうか、また、それとも我々は地道に活動をしていくのだということを選ぶのか、どちらを選んでいくのでしょうか。お聞かせください。","respondent":"三ツ橋環境課長","answer":"今回、今年度の夏から取組みを始めまして、今まさに４４店舗の取組みとなっております。その中で来年度はステッカーが両面シールのステッカーになっております。じわじわと進めていくのも一つの手ですけれども、一気に加速させていきたいという思いもあります。","id":"exchange-082"},{"speaker":"木村委員","kind":"意見","question":"この事業について職員の方にお話ししたところ、対応していただいた女性職員の方が、大変声が力強くて、前向きなご返答をいただきました。この事業にかける意気込みというものをすごく感じることができました。目標はまず５０店舗を目指すということでありますけれども、先ほどお話がありましたけれども、その先のことをどのように考えているのかお聞かせを願えればと思います。","respondent":"三ツ橋環境課長","answer":"５０店舗になりましたら、環境啓発の冊子を作成したいと考えています。その中でもお店の方がいろいろと会報などもつくってもらえればと考えています。いろいろな商店街、ほかの小規模な商店街を中心といたしまして取組みを推進していきたいと考えています。","id":"exchange-083"},{"speaker":"木村委員","kind":"質問","question":"今現在は、どのようにして、ただ声かけだけでやっているのか、どのように今はやっているのでしょうか。","respondent":"三ツ橋環境課長","answer":"今現在ですけれども、商店街連合会とも協力をしながら、商店街の中で推進できる店舗を探してまいります。そして、この取組みに賛同していただける店舗につきましては、取組みを推進してまいっております。","id":"exchange-084"},{"speaker":"木村委員","kind":"質問・要望","question":"本当に体力の要るお仕事です。歩いてやられていると思いますけれども、どうぞ十分にお気を付けください。頑張っていただきたいと思います。私たちの年代は、物を大切にするように教育を受けてきました。特に食べ物を残すことによっては厳しく指導されてきました。最後にお聞かせを願いたいと思います。","respondent":"三ツ橋環境課長","answer":"特に今回はもったいないプロジェクトの中の食品ロスというものを掲げております。区民の皆様も、そして商店街の皆様も、そして区が全体が一丸となって取り組むことが大事だと考えています。","id":"exchange-085"},{"speaker":"沢田委員","kind":"質問・要望","question":"３０１ページの商店街振興事業、商店街装飾灯について、それから３０１ページの経営相談事業、中小企業支援関係について、事業承継支援事業についてお伺いしたいと思います。まさに同じタイミングでたけうち委員と同じ話を地域の方から聞いておりましたので、私もぜひこれについては皆さんに知っていただきたいなという思いを込めて質問させていただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"そうしまして、その相差でいろいろ区としましても、電気代削減などの経済的効果も十分踏まえて、今後、検討してまいりたいというふうに考えているものです。","id":"exchange-086"},{"speaker":"沢田委員","kind":"質問・要望","question":"本当に高い８割の補助が都から出ているとは言っても、やはりそれなりの商店街の負担もあります。次に、事業経営相談のことで聞いていきたいと思います。今の中小企業支援の中で、今回もたくさんのメニュー、また支援の充実が図られていますけれども、今現在の経営相談の状況、どんな相談内容なのか、簡単な推移等がわかりましたら教えてください。","respondent":"山崎商業・ものづくり課長","answer":"最近では、新しく事業を起こす起業・開業の部分の相談も増えております。それから、それ以外としましては、今、現状の事業をどういうふうに継続していくべきであるかという事業承継の相談がここのところ増えております。","id":"exchange-087"},{"speaker":"沢田委員","kind":"質問","question":"今回、１００年以上の企業を顕彰されたということもこの間ありましたけれども、やはり長く企業は地域に残っていただいて貢献していただくためにも、世代交代等、事業承継はしっかりと支援をしていかなくてはいけないところだと思うのですけれども、今までもビジネス・カタリストの方が経営支援等、事業承継については支援されていたということですけれども、このたびの新規の予算計上によって。","respondent":"山崎商業・ものづくり課長","answer":"緊急に対応するような場合につきましては、よりその事業承継に特化した専門的な知見のある専門家を派遣するなど、レベルアップに努めて事業承継の支援に邁進したいという考えです。","id":"exchange-088"},{"speaker":"沢田委員","kind":"質問・要望","question":"専門家の方もぜひ使っていただいて、また、ほかのいろいろな各種支援制度がそういう方は把握されていると思いますので、区内にある小規模事業者に対する支援の拡充をしっかりと図っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"西本委員","kind":"提案","question":"この品川ビジネスクラブに助成金を４,３５１万円余が出されているわけなのですが、この団体はどういう団体であって、どういう成り立ちであって、なぜこの助成金というのが出てきているのかをお知らせください。それから、「避難訓練をしたほうがいいのではないか」という話を提案したら、「避難経路を業者と確認したので避難訓練は不要である」という返答。こういう情報は区としては認識があるのでしょうか。","respondent":"立木産業活性化担当課長","answer":"今委員からお話しいただいた内容は、全てではございませんけれども、聞いているところもあります。そういった中で、今、新たに聞いた部分もありますので、指定管理者としっかり意見交換しまして、適正な運営がなされるように今後改善してまいりたいと思います。","id":"exchange-090"},{"speaker":"西本委員","kind":"質問・要望","question":"この監査はどういうふうにされているのかというところを教えてください。もっと知っている人、ノウハウを持っている方々がやっていれば、利用者の側に立った使用勝手であるとか、要望であるとか、気持ちを受けとめてくれるとか、そういうことができるのではないの、本当にノウハウなかったのですかねなどという話なのです。なので、選定するときの要件がどうだったのだろうか。いかがでしょうか。","respondent":"立木産業活性化担当課長","answer":"こちらに関しましては、区のほうから財団のほうにきちんと内部の検査等を行ってあります。指定管理のほうのモニタリングも対象になっておりますので、そういったところではきちんと内部監査に関しては行っているという認識です。","id":"exchange-091"},{"speaker":"西本委員","kind":"質問・要望","question":"５０％出資をしているということですけれども、ただ、いろいろ事業を見ますと、同じような事業をいろいろな区民の皆様、そしていろいろな団体がいるのです。それからＳＨＩＰについては、これからいろいろ工夫していただきたい部分があるので、ぜひ利用者からの意見をいただくような、ご意見箱ではないですけれども、そういうものがあるといいなと思うのですが、最後にそれをお聞きしたいと思います。","respondent":"立木産業活性化担当課長","answer":"いろいろな団体との連携に関しましては、これからもしっかりやっていきたいと思います。利用者満足度の調査に関しましては、しっかり何か意見をお伺いできるような形を整えたいと思います。","id":"exchange-092"},{"speaker":"こんの委員","kind":"質問・要望","question":"順不同ですけれども、２７３ページの産後ケア事業について、事業の内容などを確認をさせていただきたいというふうに思います。この事業は、大変に私ども区議会公明党といたしましても、かねてからの要望でございましたので、こうした形でのモデル事業ということで実施を踏み切っていただきましたことを評価いたします。","respondent":"榎本荏原保健センター所長","answer":"産後ケア事業についてご説明します。","id":"exchange-093"},{"speaker":"こんの委員","kind":"質問","question":"ご説明ありがとうございました。いわゆる育児不安の初産の方を中心に、育児不安の解消、またお母さんの体のケアというところでのご説明だったのですけれども、これ、先ほど、田中委員からも質問が出ていましたけれども、４時間の中でこれがケアができるかどうかというところが非常に私も思っております。もう少し、こういうことがケアで、こういう体制をとったのだというご説明をいただけますでしょうか。","respondent":"榎本荏原保健センター所長","answer":"この間、産後ケア事業を進めるにあたりまして、現在、すくすく赤ちゃん訪問ですとか、様々な事業で連携しております助産師会、それから区内の東京医療保健大学の助産師を養成している先生方ともいろいろ協議をいたしまして、今の産婦。","id":"exchange-094"},{"speaker":"こんの委員","kind":"質問","question":"一旦ここでケアを受けるのですけれども、その後この方がきちんとケアされて育児がきちんと乗っていくかどうかというのは、育児ヘルパーとかを使っていくから大丈夫という考えなのか、そこら辺はどうなのでしょうか。もう少しお考えをお聞きしたいと思います。","respondent":"榎本荏原保健センター所長","answer":"今回、産後のケア事業日帰り型ということですけれども、これ以外に、お母様が相談できる場所というのをネウボラネットワークの中ででも、現在、考えているところでございまして、講習会形式で行っているところ、それから、保健センターでも母乳相談等も行っておりますし。","id":"exchange-095"},{"speaker":"こんの委員","kind":"確認","question":"今後のことの、まだモデルケースが始まらないですけれども、今後のことも確認をしておきたいと思います、お願いします。","respondent":"榎本荏原保健センター所長","answer":"委員おっしゃられましたように、利用者の方々のアンケートなどもとり、その中でご希望を、きっちりニーズを捉えて、今後、今は日帰り型ということですが、ほかの個別ケアであったり、集団ケアであったり、様々な形式があると思いますので。","id":"exchange-096"},{"speaker":"渡部委員","kind":"質問","question":"品物が結構いろいろなものが出ていますけれども、ある意味、百貨店との契約ですから、そのクオリティーにかなったものが出ていまして、１万円相当で果たして本当に１万円かななどとうがった見方をしていたのですが、本当に１万円、希望小売価格１万円のものがしっかり並んでいて、結構いいものも出ています。そもそもこの掲載品目をどのようにして選ばれたのか教えてください。","respondent":"太田品川保健センター所長","answer":"育児用品と、それから妊婦が使えるものということで、８０点以上というふうに規定しておりまして、特におもちゃ券にも対応できますように、玩具については２５点以上というふうにかなり多く掲載してもらうということになっておりまして、今回。","id":"exchange-097"},{"speaker":"渡部委員","kind":"質問","question":"ただ、ちょっとこれ、仕組みを見ましたら、東京都の補助金がたしか１０分の１０ですね。ですけれども、やはり様々な部分で活用いただけるような、本当に妊婦を支えていくのだというような意味で言うと、この子ども商品券等の利用、これであれば、自分の自治体でつくることもないですし、様々な仕組みの中で動けるのでいいのかななどというふうに思っているのですが、その辺のお考えはいかがでしょうか。","respondent":"太田品川保健センター所長","answer":"１１月、１２月の利用者の出産後の方にアンケートを行いまして、育児カタログ以外にも希望するものについて伺いましたところ、産後ケア施設利用が３６％、子ども商品券が３４％、タクシー券と家事代行がそれぞれ１５％ずつと、数の上で決め手を欠きましたので。","id":"exchange-098"},{"speaker":"渡部委員","kind":"提案","question":"一つの提案としてさせていただきましたので、ぜひご検討いただければと思います。内容を確認しますと、本当に立派ですし、もらった側が気持ちよくなるようなカタログだと思います。しかしながら、そのような観点で、今、要望もさせていただきましたので、ご検討いただければと思います。３０３ページ、クラスターフェア、ＳＨＩＰでこの間ありまして、この中でビジネス創造コンテストについて伺います。","respondent":"立木産業活性化担当課長","answer":"こちらのビジネス創造コンテストは、品川ビジネスクラブと品川区で共催で行っているものです。一般枠と、あと、今、委員がおっしゃられました区民枠ということで、小学校から中学校、高校生の部と２部門で行ってあります。","id":"exchange-099"},{"speaker":"渡部委員","kind":"意見","question":"その小学生とかが、きっと僕らが考えもつかないような発想で、こうなったらいいなということを出してくれているのだと思うのです。どういうものが出ているかとか、例えば、ホームページでもいいですので、ぜひ知りたいなと。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-100"},{"speaker":"のだて委員","kind":"質問","question":"私からは、２９５ページの産業振興経費の景況調査にかかわって、景気回復を伺います。区長は施政方針で「日本の経済は回復」と述べましたが、私は景気が良くなったとはとても思えません。何をもって景気が回復したと考えるのか、その評価する具体的な指標、データは何か伺います。","respondent":"山崎商業・ものづくり課長","answer":"品川区景況調査、３カ月に一度行っております。根拠につきましては、景況調査の状況です。いろいろ業種・業態がありますが、全ての業種・業態の平均値のＤＩ値というものがあります。こちらのほうは、景気がいいと思っている、あるいは悪いというこの比率です。","id":"exchange-101"},{"speaker":"のだて委員","kind":"質問","question":"マイナスというのは、悪いと思っている人が多いということだと思います。地域を歩いていても、商店や工場の方からは、景気を良くしてほしい、アベノミクスの恩恵は回ってこないという声が寄せられます。どうして国民に景気回復の実感がないのか伺います。景気回復とは間違いではないでしょうか、伺います。国民の所得は増えているのでしょうか。この３点を伺います。","respondent":"山崎商業・ものづくり課長","answer":"日銀の短観なども含めて、経済状況の大体のＤＩ値のカーブというのは同様のものというようなことで区としては捉えているというようなことです。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問","question":"私が伺ったのは、景気回復の実感がないのはなぜか。区長の回復したというのは間違いではないのか。そして、国民の所得は増えているのか。この３点です。いかがでしょうか。本会議場でも、「デフレマインドからの脱却」と言っておりますけれども、景気回復とは気持ちの問題なのでしょうか。この点も伺います。","respondent":"山崎商業・ものづくり課長","answer":"そうした意味では、品川区としましては、経営基盤の底上げとして、経営相談を受けながら最適な経済支援策にこれまでも企業の方々の要望にお応えしてつないでいるというようなことです。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問","question":"景気回復が気持ちの問題なのかとお聞きしたので、その点も改めて伺いたいと思います。実質賃金は４年連続で下がっています。アベノミクスの３年間で５％も下がっています。消費税８％増税後の家計、消費支出は下がっています。これらの政府発表の数字の紹介ですが、まずはこれが事実だと認めますか、伺います。景気が回復したとの区長の説明は間違っていると思いますが、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"それで、景況の実感というのは、それぞれ気持ちで景気がいいとか悪いとかということも一つ言えますが、それぞれの中小企業の経営者にとりましては、やはり前年度との販売額の比較でありますとか、あるいは、原材料費が高騰して、やはり儲けが少なくなった。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問","question":"私が特に注目したのは、消費税増税後の家計消費支出の推移です。出展は総務省家計調査２０１６年１月分速報の２人以上世帯の消費支出の推移です。消費税８％増税前に一時駆け込み需要で増えるものの、その後はずっと落ち込んでいます。消費税１０％に増税したら、家計消費はさらに落ち込むと思いますが、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"そのときどきの消費喚起に資するような、例えばプレミアム付商品券などを通じて、区としては、そのときどきで最適な施策について適用しているというふうに考えてあります。","id":"exchange-105"},{"speaker":"のだて委員","kind":"意見","question":"プレミアム付商品券などを出しているということで、家計消費の落ち込みを心配するならば、この１０％増税こそ反対すべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-106"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"２８１ページの環境対策、紙の削減について。それと、２９５ページと２９７ページ、伝統的産業の振興と就業支援、これをまとめてお伺いします。これは欧米などでは受診率向上で役立っているそうでありますが、この点についても区の見解をお伺いいたします。環境対策についてですが、まず、紙資源の利用に関する調査をこれまでされているでしょうか。その目標値も教えてください。","respondent":"川島健康課長、三ツ橋環境課長、山崎商業・ものづくり課長","answer":"具体的にはまだどういうふうにするかというのは、これから知恵を絞るところですが、年代が上の方は。ペーパーレス化のご質問です。区では、しながわエコリンク、環境マネジメントシステムを今年度から実施しております。こうしたところに区の支援を入れるなりしまして、こういう分野の後継者の育成についても区としても考えてまいります。","id":"exchange-107"},{"speaker":"石田（し）委員","kind":"提案","question":"紙の削減ですが、江東区で、議会として紙ゼロを目指すということで、ＩＣＴを活用して、新聞報道では、年１００万枚の削減効果があるのではないかというような大きな見出しも出ていました。そんな中、この間もＩＣＴの研修会に行ったときに神奈川県の話を聞いたのですが、これ、１字でもミスをすると刷り直したりとか、そういった意味では紙の無駄遣いも出てきてしまうのかと。要望で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-108"},{"speaker":"本多委員","kind":"質問・要望","question":"２９７ページの消費者啓発費、消費生活相談について伺います。相談員経費６人ということなのですけれども、昨今の状況の特徴をお聞かせいただきたいと思います。数につきましては、平成２２年度から平成２６年度までの相談件数は事務事業概要で把握しておりますので数は結構です。昨今の特徴についてお聞かせください。","respondent":"山崎商業・ものづくり課長","answer":"消費者相談の特徴です。やはり消費者の被害に遭いやすい、あるいは狙われやすい高齢者の方々の相談と、それから逆に、ＩＴ化が推進していまして、スマホなどにおける詐欺というようなところで、若い方の相談が増えているというようなことが特徴かなというふうに捉えております。","id":"exchange-109"},{"speaker":"本多委員","kind":"質問","question":"消費者生活相談の事務事業概要の目的を見ますと、購入した商品やサービスに対する苦情ですとか、契約上のトラブルが目的だと書いてあって、これは昭和４９年度から事業開始なのですが、おそらく事業を開始した当初は、買ったものに対する苦情ですとか、契約上のトラブルとか、そういった目的だったと思うのですが、今の答弁を聞いていると、買ったものとかではなく。","respondent":"山崎商業・ものづくり課長","answer":"そうしたときに、買ったものと品物の違いがあったり、あるいは、今、携帯電話の契約をすると、例えばインターネットの回線サービスと抱き合わせにして、このプランだとこれだけ安くなりますよとか、そういういろいろなバリエーションがございまして。","id":"exchange-110"},{"speaker":"本多委員","kind":"質問","question":"洋服でも本でも、一般の方が提供すると、物に対して金銭が発生するので、名前とか、住所、電話番号を出さなければいけない。出すのはいいと思ってみんな出すと思うのですけれども、そうすると、それにまつわるリサイクルに対して何か電話販売とかの非常にそういう連絡が増えてくるというケースがあるのですが、そういうケースの苦情というのは承知をされていますでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"物を介した取引のときに、出品者といいますか、リサイクル品を提供する方々のお名前とか住所の情報の個人情報が流出するというようなことについては、そういったケースに限らず、消費者相談で一定ご相談の内容としてはあります。","id":"exchange-111"},{"speaker":"本多委員","kind":"質問","question":"それで、特殊詐欺対策について移っていきますけれども、都内の特殊詐欺被害は、平成２５年をピークに２年連続で減少しておりますけれども、昨年は１,８７９件、約６６億３,０００万円の被害が発生しておりまして、依然として高止まり状態でありますけれども、品川区内としてはどういう状況でしょうか。","respondent":"山崎商業・ものづくり課長","answer":"実際に被害に遭われた額でありますとか、あるいは、このまま行くとということで、被害に遭う恐れのあった額というものについては、年々、例えば土地売買のお話ですと、金額が急にはね上がったりする関係もあって、金額についてはそれぞれの年度でバラつきがありますが。","id":"exchange-112"},{"speaker":"本多委員","kind":"質問・要望","question":"都内全体では減りつつあるのですけれども、品川区内の被害が増えているということなので、対策を強化をしていただきたいと思います。しかし、被害に遭ってしまった。９７％の人が家族の声を間違えるわけがない、けれども、被害に遭ったとか、そういった油断というか、そういった部分があろうかと思いますけれども、その辺についての課題や対策はどのように捉えているでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"例えばなりすまし詐欺などにつきましては、高齢者の方々の電話機に、電話が鳴ったときに、そうした注意喚起をするような機器を、これは警察などと連携しながら機器を備え付けるなどの対応によって未然に防止するというようなことで、そうした関係機関と連携しながら対応している。","id":"exchange-113"},{"speaker":"本多委員","kind":"質問・要望","question":"これ、平成２７年度の６月から都が始めて、まだ９カ月ぐらいなのですけれども、区市町村に貸出しをしていて、もうそれに取り組まれていると思うのですけれども、これは現在まだ９カ月なのですけれども、被害がゼロなのですね。なので、効果が上がっていると思いますので、ぜひこの辺を着眼して強化をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"若林委員","kind":"質問・要望","question":"それからもう１つ、ご答弁があったのが、二、三十年後の医療費の抑制も１つの見込みもあるという、そういう目的もあるということで、そもそもこの健診と健康とか健康づくりの関係性が、どういうものになっているのかというのをお聞きしたいと思います。それから２８４ページのリサイクル推進費、ちょっと何点か一遍にお聞きいたします。これが実は資源には出せない。","respondent":"川島健康課長、小林品川区清掃事務所長","answer":"三次予防というのが、リハビリですとか再発防止という形になります。シュレッダーをお持ちでない家庭についての支援策については、現段階では検討しておりませんでしたが、これから個人情報保護の意識から、そういうシュレッダーをかけたごみの増加等が想定されますので、その動向を含めまして。","id":"exchange-115"},{"speaker":"若林委員","kind":"質問・要望","question":"それを保険事業の充実に活用していくというふうに計画が出されております。社協のほうではボランティアの仕組みもあります。こういうところにつなげていくということがすごく大事ではないのかなというふうに思いますので、ご答弁をいただきたいと思います。ぜひそういう資源ごみにするための方策として、ぜひご検討いただきたいということを、これは要望にとどめします。","respondent":"川島健康課長","answer":"この健康プランの中にもデータヘルス計画を進めるというものが位置付けられておりますので、こういった重要な取組みを、成果をいろいろな施策の中に反映できるように、私どもも国保医療年金課と連携をしまして、健康づくり施策を進めていきたいというふうに考えてあります。","id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"質問","question":"新規の２つを先にお尋ねします。そして、事業承継支援事業のほうは、ほかの委員の方から質問もありましたが、こういった中小企業の継承持続に対して、いろいろ手立てを打つということでしたが、極端な話、Ｍ＆Ａ、あるいは形を変えてといいましょうか、看板を変えて、経営者は変わらず発展的な業種変更というか、そういったところまでお考えになられているのでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"企業の価値なり付加価値が認められるからこそ、他の事業所がその技術なり経営力を買い取るというようなことですので、こうした分野につきましては、非常に専門的な支援といいますか、そういったことが必要ですので、そうした専門家と連携を組みながら。","id":"exchange-117"},{"speaker":"いながわ委員","kind":"質問・要望","question":"私から、２６５ページと２９５ページの公衆浴場について、２８３ページ、エコライフ普及事業、間伐材に関連して、多摩産材を含む質問をするということと、２９７ページの観光アクションプラン推進事業、歩行者用観光案内標識設置についてお伺いをしていきたいと思います。そして、今後の公衆浴場のあり方、先ほども質問がありましたけれども、ちょっとかぶってしまうかもしれませんが、それを教えてください。","respondent":"川島健康課長、山崎商業・ものづくり課長、三ツ橋環境課長、間部文化観光課長","answer":"都の改築の補助に合わせて区が助成するというような形の公衆衛生に関連するような設備の改修についての支援を行っているものです。もう一つのほうは、事業所支援ということで、円滑な運営、事業の組織力強化ということで。木材の利用に関する方針ですが、今年度、制定いたしました。歩行者用の観光案内板の助成ですけれども、これは歳入で計上してある部分ですけれども、まずこれ、観光財団から入っているということで。","id":"exchange-118"},{"speaker":"いながわ委員","kind":"質問・要望","question":"外国人に関しては、ホームページ上で、さっき見たら、品川区の浴場が３１軒と出ていたのです。その点についての認識を端的にお伺いするということと、間伐材、自分が聞いておいて大変恐縮なのですけれども、それを制定したことによって、今後、品川区がどうあるのかということを教えていただきたいと思います。多言語は結構ですので、来年度もそういった補助金が来るかどうかだけ確認をお願いします。","respondent":"間部文化観光課長、三ツ橋環境課長","answer":"タトゥーの件ですけれども、タトゥーについては、これは生活文化といいますか、欧米人の方はかなり入れられている方がおりまして、国のほうでも、今までは禁止をしていましたけれども。今までも公共施設などでは間伐材は取り組んでおりましたけれども、今後は都の補助金などを使うことができますので、公共的な空間の活用ができると考えています。","id":"exchange-119"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひ間伐材、多摩産材も含めて、有効利用、ゆくゆくはそういったものを民間にも取り入れる補助金なども設立していただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"伊藤委員","kind":"質問・要望","question":"２９７ページ、観光アクションプランに関連して質問します。それから例えば、ここを起点にしながわ水族館等々、あちこちのところに観光に行っていただいて、具体的な観光をしていただきたい、という要望が相当来たのですよ。だから、民間の方々が既にやっていることについて、ぜひ品川区はビジネスモデルとして検討していただきたいと思うのですが、いかがですかということをまずお伺いします。","respondent":"間部文化観光課長","answer":"アートンシェルターにつきましては、鮫洲駅の近くに１２月にオープンしたということで、私たちもその辺は認識をしています。","id":"exchange-121"},{"speaker":"伊藤委員","kind":"質問・要望","question":"やはりある程度、はっきり言えば、商店街では、温度差、体力差も相当あります。だから、そういうようなことについて品川区も冷静に判断をしていただいた上で、ある程度、逆に情報提供していく仕組みをつくっていくということが必要と思うのですが、いかがでしょうか。あわせてお答えください。","respondent":"間部文化観光課長","answer":"当然、私どもも情報収集に努めていきますけれども、観光協会も地域から情報が集まるような手立てを今回の観光プランの中でも、情報発信・収集の面で考えていくということになっていますので、その点で強めていきたいと思います。","id":"exchange-122"},{"speaker":"伊藤委員","kind":"質問","question":"それからもう１点は、いろいろ勉強していますと、平成３０年がちょうど明治維新から１５０周年だということがわかりました。だから、それは非常に回っていけば、誰もが喜ぶし、区内の経済発展になるし、それからできれば、これ、１５０周年だけではなくて、前後に企画展なり特別展を開いて、そういう観光プランを検討していくべきではないでしょうかということを質問します。ご答弁をお願いいたします。","respondent":"間部文化観光課長","answer":"荏原神社から品川寺、花海道を通って浜川砲台、涙橋を通って龍馬像、品川歴史館を通って大森貝塚、大森駅に行く。全長７kmで３時間ぐらいなのですけれども、これプラス、お食事の部分だけつけ加えて、また改めて実施をしていきたいと思います。","id":"exchange-123"},{"speaker":"伊藤委員","kind":"質問","question":"浜川砲台のことについて、いろいろお話を聞きます。浜川砲台、わかりますか。そうすると、多分、劣化が進んでくる可能性があると思われますし、それから、あそこをもし観光拠点として整備していくのであれば、もっとやはり説明板なり、様々な物事を追加していって、高知県に負けないような仕組みをつくっていかないといけないと思うのですが、いかがでしょうか。ご答弁をお願いいたします。","respondent":"間部文化観光課長","answer":"砲台が雨ざらしでということでありますけれども、こちらは寄贈を受けまして、皆さんのご寄附で、せっかく数百万円をかけて建てたということですので、今後の管理運営につきましては、公園の所管とも十分協議をしながら。","id":"exchange-124"},{"speaker":"伊藤委員","kind":"質問","question":"要は、これもおそらく観光の拠点にしていこうと思っていらっしゃると思いますので、それは様々な所管で調整をしていただきながら、保全もそうですけれども、説明の部分も、今ありますけれども、もっとしっかりしたものをつくっていただきますようにお願いをしておきます。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-125"},{"speaker":"南委員","kind":"質問・要望","question":"２月２１日の日曜日に、品川区上空を低空飛行する羽田新ルート案の中止を求めて住民の会が区内をパレードしました。マスコミもこの集会に初めから最後までカメラを回して、そしてパレード参加者にコメントを求め、ＮＨＫはその日のうちに二度もニュースで取り上げました。認識しているとしたら、その受け止めはどういうふうに受け止めておられるか、そこを伺います。","respondent":"三ツ橋環境課長","answer":"委員もご指摘のように、３月５日は、南大井で説明会が、ミニオープンハウスが開催されましたけれども、そのときに私も行きましたけれども、その中のやはり区民の皆様の不安な声というのは十分こちらといたしましても伝わってありますし、直接区へのご要望なども伝わっております。","id":"exchange-126"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひもう一度、その点についての見解を答弁していただきたいと思います。区は、この間、繰り返し協議の場を離れないよう国に対して必要なことを求めていく、こういうふうに言明していらっしゃいます。区民の率直な声は、品川区上空の低空飛行は中止を、こういうふうに求めているわけですけれども、この品川の上空を飛ぶな、こういうことを品川区自身は国に対して求めているのでしょうか、いないのでしょうか。","respondent":"三ツ橋環境課長","answer":"したがいまして、国が国の責任で説明をしている段階と受け止めております。現段階での協議の場ですけれども、国や都との意見交換で、まずは都との連絡会というものがあります。こちらにつきましては、幹事会が８回、またワーキンググループが６回ございました。","id":"exchange-127"},{"speaker":"南委員","kind":"質問・要望","question":"その辺の見解も伺いたいと思います。東京都は、教室型の説明会をしろということを伝えていくという、そういう態度を明らかにしているのですけれども、品川区はこの説明会のあり方、オープンハウスではなくて教室型で説明会をきちんと開いて、区民の皆さんのいろいろな意見をしっかりつかむ、そういう努力をしろということを私は言うべきだと思うのですけれども、この点についてもいかがでしょうか。","respondent":"三ツ橋環境課長","answer":"しかしながら、国が国の責任において説明会をするに当たって、まずはオープンハウス型の説明会ということを考えておりますので、そちらについては、また引き続き注視していきたいと考えています。","id":"exchange-128"},{"speaker":"南委員","kind":"質問・要望","question":"両方の意見があって、様々な意見があるというふうにおっしゃる。確かにそうです、いろいろな意見があると思います。その辺について確認をしたいと思います。それと先ほど、品川区の上空は飛ぶなということを求めてほしい、求めているのかというふうに質問したのですけれども、ちょっとごめんなさい、答弁が確認できなかったので、もう一度、大事なところなのでお願いします。","respondent":"三ツ橋環境課長","answer":"区といたしまして、しっかり求めてほしいですけれども、まずは今の段階では説明を聞いている段階と踏まえておりますので、そのように考えております。","id":"exchange-129"},{"speaker":"南委員","kind":"質問","question":"環境方策が出されてから考えなければいけない、今年の夏に出される環境方策、この飛行計画は、今年の夏に一定の方針が出るわけですね。ですから、環境方策が出されてから考えないとでは、もう手遅れ、この上を飛ぶことを固定化させてしまうことになります。したがって、今のこの時期が大事なのだというふうに思うのです。その認識はないですか。","respondent":"三ツ橋環境課長","answer":"直接区に区民の声としていただいたものにつきましては、国に対してきちんと上げております。今回、夏の環境方策につきましては、やはりこのときに案が出されるですので、また、区としてもしっかりそれを注視していきたいと考えています。","id":"exchange-130"},{"speaker":"南委員","kind":"質問・要望","question":"何回も繰り返し説明会を行っている、議会でもいろいろ議論し、そして意見書も上げている、区のほうも一番最初に要望書を出している、そういう中で、やはり私は、要望書を出してきている中で、この説明会で大半が困る、騒音は嫌だ、墜落の心配がある、こんな計画はやめてほしい、別のルートにしてほしいと、そういうふうに言っている、その時点で、やはりきちんと伝えていくということが大事なので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"たけうち委員","kind":"提案","question":"産業活性化推進事業ですが、昨年の第３回定例会の一般質問で、中小企業への事業承継支援について拡充を要望しましたので、今回、事業承継の支援事業が新規ということでここに出ておりまして、非常にうれしく思うとともに、しっかりと取り組んでいただきたいという思いなのですが、それと連携して、この産業活性化の事業展開をするということで、プレス発表で、中小企業約５００社に対して企業訪問等を行って。","respondent":"川島健康課長、山崎商業・ものづくり課長、立木産業活性化担当課長","answer":"そのほかやらなければならないことは、先ほどもご答弁させていただいたのですが、胃の内視鏡の検査を、すぐに導入は難しいのですが、その辺。商店街装飾灯のＬＥＤ化につきましては、経常的な電気代の経済効果も十分見極めまして、スピード感を持って検討してまいりたいというふうに思ってあります。３００社ほど、こちらが融資、経営相談のほうの窓口にいらっしゃる企業に対しての聞き取り調査をする予定です。","id":"exchange-132"},{"speaker":"たけうち委員","kind":"提案","question":"がん検診につきましては、いろいろ取組みをされるということで、非常に期待いたしますが、一つご提案というか、情報なのですけれども、京都府の亀岡市、また大阪府の茨木市等で、女性のがん検診に限ってなのですが、子宮頸がん、乳がん、また女性だけではないのですけれども、肺がんですとか、胃がん、大腸がん、この５つをセットにしまして、１日でできるような体制をつくったところ。","respondent":"川島健康課長、山崎商業・ものづくり課長","answer":"受診率を増やすために、受診される方の利便性を考えました重要なご提案だと思うのですが、現在、区では、契約医療機関で個別に受診していただくという体系をとっているので。街路灯をそもそも立替えの場合につきましては、先ほど委員のおっしゃられたとおり、東京都と区と商店街のほうで３分の１ずつのものが基本ですが、環境に資するＬＥＤ街灯の立替えにつきましては、既に、大変申し訳ございません。","id":"exchange-133"},{"speaker":"たけうち委員","kind":"質問・要望","question":"はい、わかりました。がん検診のほうですけれども、ぜひそうしたお知らせも積極的にＰＲしていただくとともに、一応、京都と大阪では、セットにすることで若干利用料を割引しているのです。そういったことももし工夫できるならばお願いしたいなと思いますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"松澤委員","kind":"質問","question":"３点お聞きしたいと思います。２６５ページ、４款衛生費、１項保健衛生費、１目保健衛生総務費、ＡＥＤ管理費について。２点目が、２６７ページ、結核健康診断について。３点目が、５款産業経済費、３０３ページ、プレミアム付区内共通商品券発行助成について。１点目のＡＥＤ管理費についてですけれども、ＡＥＤの管理というともう決まっていると思いますけれども、内容についてお知らせください。","respondent":"川島健康課長","answer":"こちらは、リース契約を結びまして、あと、維持管理のほうは健康課のほうで担っているような形になってあります。設置台数は２１５台、そういった内訳になります。","id":"exchange-135"},{"speaker":"松澤委員","kind":"質問","question":"わかりました。リース契約ですと、当然、管理のほかに何か事故があった場合の保険契約というのですか、それも全て入っているということでよろしいでしょうか。","respondent":"川島健康課長","answer":"保険の契約のほうは、特段、今、加入はしていないということなのですが、事故というか、実際に使用したものにつきましては、健康課のほうに、ピッチの端末のほうからすぐ情報が入りまして、部品の取替えですとか、それからバッテリーの交換だとかという形の作業を行ってあります。","id":"exchange-136"},{"speaker":"松澤委員","kind":"質問・要望","question":"それと、平成２８年度予算では、認証保育所、私立保育園の設置助成というのがありますけれども、この管理費は当然のことながら助成しただけで、それぞれの保育所、保育園が持つということでよろしいでしょうか。","respondent":"今井待機児童対策担当課長","answer":"ＡＥＤの設置につきましては、区立保育園だけではなくて、私立の認可保育所、それから認証保育所のほうも設置しておりますけれども、開設前に設置するように指導しておりまして、管理運営費につきましては、開設時には補助が出ますけれども。","id":"exchange-137"},{"speaker":"松澤委員","kind":"質問・要望","question":"２点目の結核健康診断についていきたいと思います。結核というものは、かつて日本では亡国病と言われるほど高い蔓延率があったのですけれども、戦後はストレプトマイシンというのですか、いい薬ができて急速に低下して、一時は結核の流行は終わったと言われるようになりましたけれども、ところが、また発生件数が増えてきたというふうに言われています。現在の品川区の状況をお知らせいただきたいと思います。","respondent":"舟木保健予防課長","answer":"品川区の状況ですが、大体年間新規の発生患者が８０名前後、平成２７年については６０名前後というふうな形で、今のところ、手元に集計があります。","id":"exchange-138"},{"speaker":"松澤委員","kind":"質問","question":"当然、この予算案を見てみましても、昨年に比べて１３８万円減ということで、当然ながら発生率が減っているのかなというふうにも思われます。これはなぜなのかということをお聞きしたいと思います。それと、発生件数が減っていても、この検診件数が減るかどうかというのはまた別物だと思いますので、どのような呼びかけで検診を行っているのかということをお聞きしたいと思います。","respondent":"舟木保健予防課長","answer":"結核検診の内訳としましては、６５歳以上の区民の方を対象とした定期に行っている年１回の検診と、あとは結核患者の発生に伴って行います患者の家族検診、あとは、結核患者の管理のための管理検診等になっております。","id":"exchange-139"},{"speaker":"松澤委員","kind":"質問","question":"はい、わかりました。今の答弁の中でも出てきたのですけれども、最近は高齢者が多いという話なのですけれども、これはなぜ高齢者が多いのかということをお聞きしたいと思います。それと、昔はよくＢＣＧとかツベルクリン検査というようなことをしていたのですけれども、今現在、そういうツベルクリン検査とか、ＢＣＧとかの接種というものはどのようになっているのでしょうか。","respondent":"舟木保健予防課長","answer":"以前は４カ月健診で必ずその場でやっていたのですが、そのような形で少しずつ変わってきたということで、医療機関での個別接種で品川区は今実施しているところです。","id":"exchange-140"},{"speaker":"松澤委員","kind":"質問","question":"次に行きたいと思います。プレミアム付区内共通商品券発行助成、今年は３億円、３億円ということで、６億円発行予定となっていますけれども、平成２５年が６億円、平成２６年が７億円、春４億円、秋３億円。そしてなおかつ、秋には３億円発行しています。今年度は、春・秋で６億円、実際には少なくなっているのですけれども、これはどうしてそういう形をとられたのかお聞きしたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"今年度につきましては、国の交付金を活用したです。来年度、平成２８年度につきましては、次年度の消費税の部分等々もあります。そうした関係もあって、一応、これまでの定番の６億円に戻させていただいたというような経緯です。","id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"私は、２９７ページ、観光アクションプラン推進事業、そして２９５ページ、産業振興経費についてお聞きしたいと思います。なぜ品川区のシティプロモーションは観光事業に組み込まれていないのかお聞かせください。","respondent":"中元広報広聴課長","answer":"決して観光事業に足を踏み入れていないということでございませんで、まずシティプロモーションのきっかけとして、区へ訪れていただくという部分では、観光に力を入れていくという考え方です。","id":"exchange-142"},{"speaker":"須貝委員","kind":"質問・要望","question":"こういうものを全国的に海外、国内もそうですが、発信していくというのだったら、それぞれの事業でやはり私はＰＲしていくべきなのかと思うのですが、実際、品川区のシティプロモーションの取組みと目指すものを、簡単でいいのですが教えていただきたいということと、今、品川区は、実際、知名度は高いし、住んでみたい区ということで出していますが、各事業のＰＲなら、これ、理解できるのです。","respondent":"中元広報広聴課長","answer":"地方の方々との関係ですが、現在、全国連携プロジェクトにも取り組んでございまして、品川区だけではなくて、地方との連携、協定の中で、お互いに伸びていければいいという思いで取り組んでいるものです。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"すみません、これは質問ではないので、増え続けていくということは、今後の品川区の状況を考えると、いかがなものかという意見だけ言わせていただきます。引き続きまして、先ほど、区内経済の実態についての質問がありました。区内産業の経営状況や区民の消費状況について、品川区は実態を把握しているのでしょうか。品川区の実態、それから区民の消費状況についてお聞かせください。","respondent":"山崎商業・ものづくり課長","answer":"景況動向です。昨年の第２四半期、７月から９月につきましては、平均の全体の業況ＤＩ値が、リーマンショック後、最高の値を記録しましたということを申し上げました。","id":"exchange-144"},{"speaker":"須貝委員","kind":"意見","question":"品川区内の、例えば産業の経営状況、区民の消費の状況についてはどう捉えていますか。","respondent":"山崎商業・ものづくり課長","answer":"消費の部分につきましては、先ほど、プレミアム付商品券の関係で、今年度につきましては、春・夏と１１億円を超える販売をしているということで、そこで一定の消費喚起効果というものが出ているというようなことで分析をしています。","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"すみません、今、区内産業の経営状況ですか、これについてお答えがなかったので、今、消費のほうは少し上向いたのか、プレミアム付商品券についてというようなお話を今いただきました。もう１回だけお聞かせください。","respondent":"山崎商業・ものづくり課長","answer":"一つ括って、なかなか表現するのが困難な、二極化という局面があります。一定程度業績を伸ばしている企業もあります。ただ、平均値をとると、景況感はそんなに悪い数値ではなく、７月から９月までについては、これまでの最高の景況感であったというようなことは事実です。","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"私は、先ほど、直近の１０月から１２月期のお話をしました。悪くなっています。実際、国内産業の景況や国民の消費状況が一向によくならないから、仕方なく日銀は異次元の金融緩和政策を実施しました。そういう実態がありますね。ですから、消費が伸びないということだと思いますが、消費が伸びなければ、大半の区内産業も衰退するのは当たり前だと私は思いますが、もう一度ご見解をお聞かせください。","respondent":"山崎商業・ものづくり課長","answer":"先ほども少しご説明申し上げました。金利を０.１％でも銀行の方々にご理解を賜って、区の制度融資を中小企業の方々に、少なくとも使っていただきやすいようなことをしています。","id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"ここで財政課にお聞きしたいのですが、今ご答弁がありました。財政課としても、今度、区全体ですね、財政課だからもっと全体を広く見ているかと思うのですが、財政課の見解はどうなのですか。","respondent":"秋山財政課長","answer":"ただ、その中で、一つ一つのそういう事実に対して、一つの指標を見て、悪かったとか、良かったとかということで政策を決めていくということはやはりこれはできないので、そういうマクロの視点、ミクロの視点をあわせて総合的に判断をしていくということで、今回。","id":"exchange-148"},{"speaker":"須貝委員","kind":"意見","question":"再度申し上げたいと思います。だから、国は全体を見ています。結局、異次元の金融緩和をやって、だめでマイナス金利を実行しました。それだけ悪いということでしょう。実態経済。それから、国民の実質所得も減っているわけです。それはマスコミでも出ていました。皆さん、知らないのかと。そういう実態があるので、それに対して今申し上げましたが、不安を感じますが、もう一度ご見解をお聞かせください。","respondent":"秋山財政課長","answer":"今の経済が悪いとかということを評価するのではなく、今の状態を見て、では、区の政策としてどうしていくのか。区民の、中小企業も含めて、下支えするにはどうすればいいのかということで政策を行っているです。","id":"exchange-149"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は大変な時期をこれから迎えると思います。ぜひそういう方にも目を向けて、今後、予算を立てていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"},{"speaker":"あべ委員","kind":"質問・要望","question":"私からは、２６９ページ、２０歳からの健康診査、それから、２８１ページの航空機騒音調査、そして２９１ページの粗大ごみの中継所、そして３０３ページのものづくり活性化事業に関連しまして、産業支援交流施設ならびに武蔵小山創業支援センター等々、あるいはビジネスクラブ等についてもお伺いをしたいと思います。質問に入ります。","respondent":"川島健康課長","answer":"１６歳から１９歳の方の女性の部分につきましては、ここ数年、激変緩和ということで、あまり利用される方はいなかったのですが、配慮していきたいというふうに考えてありますが、名前としても２０歳からの健康診査というもののほうが、通りもいいですし。","id":"exchange-151"},{"speaker":"あべ委員","kind":"質問","question":"確かに制度がシンプルになったということは、お知らせもしやすいと思いますし、いい意味の改善という意味もあると考えています。全くわからないという状態で放置しているとは思わないので、大体でいいです、どのくらいの対象者なのか、それに対して２,８５０人というのがどのくらいに当たるのかということを教えてください。","respondent":"川島健康課長","answer":"１６歳から１９歳につきましては、私どもの配慮ということで、これはご理解いただければというふうに思っております。それから、対象人口につきましては、１２万４,３２７人ということです。これがこの制度に該当するのがどれだけあるかというのは、算出が非常に困難であります。","id":"exchange-152"},{"speaker":"あべ委員","kind":"提案","question":"そういったことに新年度からはぜひ力を入れることを検討していただきたいと思います。そういった様々な努力をすることを提案しますけれども、お考えをお知らせください。改めてお考えを伺います。粗大ごみ中継所につきましては、昨年、無償貸与を含めて交渉をというふうにご提案をいたしましたけれども、その後何か進展があれば教えてください。簡単で結構です。","respondent":"川島健康課長、三ツ橋環境課長、柏原企画調整課長","answer":"今のご提案の成人式というのは、非常にきっかけとしてはタイミングのよいイベントだと思いますので、少し検討させていただければと思います。航空機の騒音調査につきましては、区といたしましては、慎重に考えて検討してまいりたいと考えています。２３区全体としてといいますか、区長会事務局としても、東京都に対して協議申入れをしています。その協議を今進めているといったところです。","id":"exchange-153"},{"speaker":"あべ委員","kind":"質問・要望","question":"例えば、ＳＨＩＰなどでプレゼンの再現をするなど、何か機会を生かすことは考えていらっしゃいますでしょうか。続けて伺います。区内でも在宅ワークを行うお母さんたちの団体も活動しておりますし、在宅の仕事こそ拠点が必要という意味から、テレワーク拠点の機能を、今後、武蔵小山創業支援センターの中に持たせるということはできないかということ、これもお考えを伺いたいと思います。","respondent":"立木産業活性化担当課長","answer":"武蔵小山創業支援センターに関しましては、東京都の認証保育所もある関係で、先ほどおっしゃられました託児機能つきのシェアオフィスみたいな形も、一応協定の中に盛り込んですので、そういったところでは、今後、うまく連携はとれると考えております。","id":"exchange-154"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、２６９ページ、２０歳からの健康診査、同じページの成人歯科健診、そして２９７ページの就労支援事業について伺いたいと思います。しかし、先ほどからほかの委員の質問の中でも、生活習慣病の若年化、そして３５歳健診での結果も５１％がよくない状況だということでしたけれども、なぜそんな悪い状況になっているのか、区の見解を聞かせてください。","respondent":"川島健康課長","answer":"やはり生活習慣が悪くなっている方がいるのでというところだと思います。それから、生活習慣病が若年化しているというふうに言われている傾向がそのまま現れているのではないかという分析です。","id":"exchange-155"},{"speaker":"石田（ち）委員","kind":"質問","question":"こういった若者の健康の状況には、仕事が忙しい、長時間労働をしているとか、非正規雇用で低賃金でストレスを抱えているとか、お金がない、健康管理するための知識がないなど、こうしたことも悪化の原因の一つではないかと。ここに健康格差があると私は思うのです。それで改めて、２０歳からの健診、この健康格差の縮小という観点はあるのでしょうか、伺います。","respondent":"川島健康課長","answer":"そこを早め早めに手を打ちまして、そういったことを正していくということが、長期的には健康寿命の延伸とかという話にもつながっていくのではないか、そういう考え方になります。","id":"exchange-156"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういった生活の不摂生だったり、暴飲暴食だったり、そういった状況が自分の責任でないところで起こされていくという、こういった状況もあると思うのです。若い世代には特に。２人に１人が非正規ですから。ですから、そういった状況でも健康格差、これを品川区としてはどう考えているのか伺いたいと思います。","respondent":"川島健康課長","answer":"品川区ではそういった観点からの施策の導入ということではないので、なかなかお答えも難しいのですが、やはりその年代の方たちの行動をどのように変えていくかということです。その辺を早め早めに手を打つという予防の観点からの政策的な考え方で導入をしたというものです。","id":"exchange-157"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"年収２００万円以下のワーキングプアが１,１００万人を超えているという状況です。そして若者の２人に１人が非正規雇用、こういう状況の中で、もはやこの健康問題は自己責任ではないと。私は４０歳からの成人歯科健診を若者の健診とセットでやってほしいと求め続けてきました。ぜひ若者の健診と一緒にこの成人歯科健診、一緒にできるように対象拡大をしていただきたいと思いますけれども、いかがでしょうか。","respondent":"川島健康課長","answer":"区としましては、歯周病が今おっしゃったとおり、生活習慣病の一つであるということで、リスクの高い４０歳以上の壮年期の方に特化して歯科健診を実施するという考え方です。","id":"exchange-158"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今のうちから若い世代に歯科健診ができる状況をつくっていただきたいと思います。そして、この周知の仕方を伺いたいと思います。３５歳の健診のときから周知の工夫をしていただきたいということを求めてまいりました。区のほうも工夫をしたいとは言ってきました。２０歳からとさらに若い世代からとなりますけれども、どのような周知をされるのか、お考えなのかお聞かせください。","respondent":"川島健康課長","answer":"広報しながわへ掲載する。それから、先ほども申しましたが、国保のニュースレターといいますか、こんにちは国保という部分、年に二、三回発行のものにも、このご案内を一緒に入れていただく、そういったものを工夫してやっていこうというふうに考えてあります。","id":"exchange-159"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり若い世代は、自分の悩みや不安が区役所とつながっているということがあまり感覚が弱いのではないかと思うのです。仕事のこと、体のこと、心のこと、これは先日も質問しましたＬＧＢＴのことも含めて、区ではこういう相談ができる場があって、支援する事業もあるよという、こういったパンフレットを２０歳から全員に配る。こういったことをしていただきたいと思いますが、いかがでしょうか。","respondent":"川島健康課長","answer":"せっかくシンプルになった２０歳からの健康診査というところで、これを一本化して打ち出しして啓発、周知していきたいというふうに考えております。","id":"exchange-160"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ就労センターぐらいには置いていただきたいと思います。一般質問でも取り上げてきましたけれども、労働監督官との連携で、就職面接会とあわせて、労基法セミナーを開催したということですけれども、開催に至った経緯と、次もあるのかどうか伺いたいと思います。それと、セミナーの内容はどんなものだったのか、また、参加者から感想などがあったのかどうか、そこを伺いたいと思います。","respondent":"立木産業活性化担当課長","answer":"参加した方のアンケートを見せていただいたところ、やはり今まで自分が知らなかったことが今回よくわかったというようなことでお声を頂戴しております。","id":"exchange-161"},{"speaker":"石田（ち）委員","kind":"質問","question":"今お話の中にありました厚生労働省のパンフレット、この中から働くルールについて幾つか質問します。１つ、ライブに行きたいという理由で有給休暇がとれますか。そして２つ目、妊娠をしたらやめてもらうと言われた、こういうときはどうしたらいいのかというところを、ぜひお答えください。","respondent":"立木産業活性化担当課長","answer":"質問の意図は、これは内容を答えるという形でよろしいでしょうか。","id":"exchange-162"},{"speaker":"石田（ち）委員","kind":"質問","question":"今お答えいただいた内容なども若い世代は知らないまま社会に出ていく、そういう中で、何を言われてもそのまま受け入れて、ブラック企業などでも働かざるを得ない状況になっていきます。区として、こうしたセミナーもあわせてですけれども、労働基準法、そして働くルール、これから社会に出る若者やルールを知らずに働いている方々に、どのように知ってもらおうと思っているのか伺いたいと思います。","respondent":"立木産業活性化担当課長","answer":"そういった形で、いろいろな形で参加していただいて知っていただくことと、あと、例えば『ポケット労働法』みたいなものは、東京都のホームページからも見られるようになってありますので、そういったご案内等もしていきたいと考えています。","id":"exchange-163"},{"speaker":"石田（ち）委員","kind":"提案","question":"先ほど、セミナーの開催の経緯なども伺いましたが、働くルールを知り、ブラック企業に引っかからないように、おかしいと思ったら相談できるように、さらなる周知がやはり必要だなと、ルールがあるよということをさらに広げていただきたいと思います。ですので、やはり区役所の窓口や就労センター、そういったところに置いていくことが必要だと思うのですけれども、いかがでしょうか。","respondent":"立木産業活性化担当課長","answer":"そちらとの連携等もとった上で、いろいろな周知を図っていきたいと思います。『ポケット労働法』に関しまして、最近、紙で見るよりはスマホで見るというような若者文化に合わせたような形で当面は対応したいと考えております。","id":"exchange-164"},{"speaker":"浅野委員","kind":"提案","question":"最初に新興感染症の対策ですけれども、平成２１年の第１回定例会で、会派のほうから新型インフルエンザの感染拡大防止と、区役所機能の維持のための事業継続計画の策定を提案しております。このとき、様々な課題でありますとか、ノウハウが、この体制を整えることによって蓄積をされたと思いますけれども、いかがでしょうか。","respondent":"舟木保健予防課長","answer":"ただ、その後もエボラ出血熱の海外での流行や、ＭＥＲＳの発生、近隣の韓国での発生や、最近は、デング熱、ジカウイルス感染症等の海外での流行等もありますので、感染症のことについては、常にそういう危機管理の視点を忘れずに対応を継続しています。","id":"exchange-165"},{"speaker":"浅野委員","kind":"確認","question":"きちんとやられたことかと思います。新年度を迎えることになりますけれども、人事異動などで組織も変わることかと思います。職員間で業務内容を含めて事業継続計画を確実に引き継ぐことが重要かと思いますけれども、いかがでしょうか。あわせて年度の早いうちに危機管理対策本部の立ち上げ訓練などを実施して、万全の体制を確認することも重要だと思いますが、いかがでしょうか。","respondent":"江部危機管理室長、舟木保健予防課長","answer":"平成２２年の新型インフルエンザ以降、各部でそれぞれの危機事象について計画を立て、先ほど申しました例えば感染症、エボラが発生したというようなときには、それの関係部署が集まった緊急会議を開き、手順の確認をするなどが。職員間での訓練ということで、いつも防護服の着脱訓練につきましては、年数回計画し、実施しております。新任の職員等、担当が代わったときにも情報の共有あるいは認識の共有ということで、そちらのほうは常にやっているところです。","id":"exchange-166"},{"speaker":"浅野委員","kind":"質問・要望","question":"廃棄物排出指導費ですけれども、家電リサイクル法によりまして、家庭用のエアコン、テレビ、冷蔵庫、洗濯機、この４品目については消費者がリサイクル費用を負担をして廃棄をするというのでしょうか、処理をすることになっていますが、この件につきましては、区民にどのような形で浸透させているのかということについてお聞きしたいと思います。","respondent":"小林品川区清掃事務所長","answer":"ちなみに、平成２６年度実績では、家電４品目を含めて１２品、平成２７年度は、本日までのところ６品の対応を終えたところです。","id":"exchange-167"},{"speaker":"浅野委員","kind":"質問","question":"外国語版ホームページ作成経費助成ですけれども、作成した企業数、またアクセス数、あと、実際に問い合わせ、受注などにつながった件数があれば教えてください。対応はどのような形でされるのか、メールとか、例えば電話などでこのホームページを見てアクセスしたいというのでしょうか、交渉したいということがあった場合の対応については、企業が行われるのか、それとも違う場で行われるのか教えてください。","respondent":"立木産業活性化担当課長","answer":"こちらの外国語版ホームページ作成経費の助成の関係ですけれども、こちらのほうが、平成２６年度の場合だと７件の申請で、６７万２,０００円。平成２７年度、今年度は、今現在、５件ということで、４４万１,０００円の助成金額となっています。","id":"exchange-168"},{"speaker":"渡辺委員","kind":"質問","question":"２８５ページ、リサイクル活動支援事業、それと２９７ページの観光アクションプラン、この２つで聞いてまいります。初めに、リサイクル活動の集団回収報奨金の主な仕組みと集団回収に関する団体があるかと思います。主な団体、主な仕組みを教えてください。広域観光まちづくり支援事業費の補助等で、この広域連携のところの平成２８年度のテーマ的なもの、これをお知らせください。","respondent":"小林品川区清掃事務所長、間部文化観光課長","answer":"集団回収のお尋ねですけれども、集団回収につきましては、各地域で自主的にリサイクル活動を行っていただいたものに対しまして、主に古紙を中心に１kgにつき６円の報償金を団体活動費として支給しています。観光展の経費部分については、この平成２８年度、観光プランが今年度策定されまして、これのお披露目というようなことも含めまして、観光に関する事業者を集めて実施をするということで、一応今のところですけれども。","id":"exchange-169"},{"speaker":"渡辺委員","kind":"質問","question":"リサイクルで、これ、伺った内容は、もう皆さんもご存じのように、集団回収、朝早くから町会の方、あるいは自治会の方が、マンションごとも含めてやっていらっしゃる。１kg６円で報奨金がいただける。その単価の問題ではないのですが、実は新聞もとっている家庭が、もうこの１０年スパンで言えば大きく減ってきた。そこで今年度、平成２８年度の協議会の発足というところに大変興味を持ちました。","respondent":"小林品川区清掃事務所長、間部文化観光課長","answer":"再資源化につきましては、今までもリサイクル通信等を通じて、そのリサイクルの流れ、どういうものに再商品化されているのかのＰＲに努めてまいりましたが。ただ、４０人が集まって総会をするだけでは、なかなか事業の推進が難しいということで、分科会をつくりまして、例えば、国際化の外国人向けの受け入れ関係のプロジェクトですとか、ウォーターフロントに関する部分、また。","id":"exchange-170"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それぞれありがとうございました。そもそも品川区は観光をやれるいい環境だと思います。２３区や全国を見ても、アクセスも含めて注目度もあるからできるわけで、それで、やはり区民サービスにすごくいろいろつながるのだなという思いがある中で、いい会議体というのですか、有意義な、そのためには、今言った大きな会議もそうなのですが、繰り返しますが、事務局機能、これはどの組織を見ていても思います。","respondent":"間部文化観光課長","answer":"今後は区内の大学とも連携して、例えば女子大生の意見も取り入れるなど、魅力ある観光施策を進めていくために、鋭意頑張ってまいりたいと思います。","id":"exchange-171"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/257095?Template=document&Id=1044#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":124870,"voices":419}}]);
